{
  "name": "harbor-dispatch",
  "version": "0.1.0",
  "private": true,
  "description": "Offline freight planning for an island cooperative (fictional).",
  "type": "module",
  "engines": {
    "node": ">=20"
  },
  "main": "src/index.js",
  "exports": {
    ".": "./src/index.js",
    "./ports": "./src/ports.js",
    "./domain/*": "./src/domain/*.js"
  },
  "scripts": {
    "test": "node --test test/"
  },
  "license": "UNLICENSED"
}

/**
 * Harbor Dispatch — port definitions (fictional).
 *
 * A "port" here is a physical harbor node in the cooperative's network. Port
 * identifiers are opaque strings: nothing in the system derives meaning from
 * their content, ordering, or length. They are only compared for equality.
 */

/** @typedef {string} PortId `PortId` is an opaque string; never parse it. */

const HORIZON_DAYS = 21;
const MS_PER_DAY = 86_400_000;

/**
 * Default planning horizon, expressed as a number of UTC days.
 * The horizon is always measured from an explicitly supplied UTC start time,
 * never from the wall clock.
 */
export const DEFAULT_PLANNING_HORIZON_DAYS = HORIZON_DAYS;

/**
 * A port record. Only `id` is required; `name` is a human label used by
 * reports and is not part of any identifier rules.
 *
 * @typedef {object} Port
 * @property {PortId} id
 * @property {string} name
 */

/**
 * Assert that a value is usable as an opaque port identifier.
 *
 * @param {unknown} value
 * @returns {PortId}
 */
export function assertPortId(value) {
  if (typeof value !== 'string' || value.length === 0) {
    throw new TypeError('port id must be a non-empty opaque string');
  }
  return value;
}

/**
 * Define a port. The returned object is frozen so it can be safely shared.
 *
 * @param {{ id: string, name?: string }} spec
 * @returns {Readonly<Port>}
 */
export function definePort(spec) {
  if (spec === null || typeof spec !== 'object') {
    throw new TypeError('port spec must be an object');
  }
  const id = assertPortId(spec.id);
  const name = typeof spec.name === 'string' && spec.name.length > 0 ? spec.name : id;
  return Object.freeze({ id, name });
}

/**
 * Parse an ISO-8601 UTC timestamp supplied by a caller. Timestamps are never
 * generated internally from the system clock; they always come from input.
 *
 * @param {string} value
 * @returns {number} milliseconds since the Unix epoch
 */
export function parseUtcTimestamp(value) {
  if (typeof value !== 'string') {
    throw new TypeError('timestamp must be an ISO-8601 UTC string');
  }
  if (!/Z$/.test(value)) {
    throw new RangeError(`timestamp must be UTC (end with "Z"): ${value}`);
  }
  const ms = Date.parse(value);
  if (Number.isNaN(ms)) {
    throw new RangeError(`invalid timestamp: ${value}`);
  }
  return ms;
}

/**
 * Compute the exclusive end of a planning horizon.
 *
 * @param {string} startUtc ISO-8601 UTC timestamp, inclusive
 * @param {number} [days] number of UTC days in the horizon
 * @returns {{ startMs: number, endMs: number, days: number }}
 */
export function planningHorizon(startUtc, days = DEFAULT_PLANNING_HORIZON_DAYS) {
  if (!Number.isInteger(days) || days <= 0) {
    throw new RangeError('planning horizon days must be a positive integer');
  }
  const startMs = parseUtcTimestamp(startUtc);
  return Object.freeze({ startMs, endMs: startMs + days * MS_PER_DAY, days });
}

/**
 * Whether a timestamp falls inside a horizon. Half-open interval: [start, end).
 *
 * @param {{ startMs: number, endMs: number }} horizon
 * @param {string} utc ISO-8601 UTC timestamp
 * @returns {boolean}
 */
export function isWithinHorizon(horizon, utc) {
  const ms = parseUtcTimestamp(utc);
  return ms >= horizon.startMs && ms < horizon.endMs;
}

/**
 * Opaque identifiers.
 *
 * Every identifier in Harbor Dispatch is an opaque string. Callers may have
 * generated them from a counter, a UUID, or anything else, but the domain
 * only ever compares them for equality — it never slices, parses, sorts by
 * meaning, or infers a type from their shape.
 */

/**
 * @param {string} label what kind of id is being checked (for messages only)
 * @param {unknown} value
 * @returns {string}
 */
export function assertOpaqueId(label, value) {
  if (typeof value !== 'string') {
    throw new TypeError(`${label} must be an opaque string`);
  }
  if (value.length === 0) {
    throw new RangeError(`${label} must not be empty`);
  }
  // Control characters would break logs and exports; that is a formatting
  // concern, not a parsing one.
  if (/[\u0000-\u001f\u007f]/.test(value)) {
    throw new RangeError(`${label} must not contain control characters`);
  }
  return value;
}

/**
 * Compare two opaque ids for equality.
 *
 * @param {string} a
 * @param {string} b
 * @returns {boolean}
 */
export function sameId(a, b) {
  return a === b;
}

/**
 * Capacity and mass arithmetic.
 *
 * All mass in Harbor Dispatch is an integer number of kilograms. There are no
 * floats, no tonnes, and no unit conversion: a consignment weighing 12 is
 * 12 kg. Anything that would produce a fractional kilogram is rejected.
 */

/**
 * @param {string} label
 * @param {unknown} value
 * @returns {number} the same value, narrowed to a non-negative safe integer
 */
export function assertKilograms(label, value) {
  if (typeof value !== 'number' || !Number.isInteger(value)) {
    throw new TypeError(`${label} must be an integer number of kilograms`);
  }
  if (!Number.isSafeInteger(value)) {
    throw new RangeError(`${label} is not a safe integer`);
  }
  if (value < 0) {
    throw new RangeError(`${label} must not be negative`);
  }
  return value;
}

/**
 * @param {string} label
 * @param {unknown} value
 * @returns {number} a strictly positive integer number of kilograms
 */
export function assertPositiveKilograms(label, value) {
  const kg = assertKilograms(label, value);
  if (kg === 0) {
    throw new RangeError(`${label} must be greater than zero`);
  }
  return kg;
}

/**
 * Add masses, rejecting results that leave the safe-integer range.
 *
 * @param {number[]} masses
 * @returns {number}
 */
export function sumKilograms(masses) {
  let total = 0;
  for (const mass of masses) {
    assertKilograms('mass', mass);
    total += mass;
    if (!Number.isSafeInteger(total)) {
      throw new RangeError('mass total exceeds the safe integer range');
    }
  }
  return total;
}

/**
 * Describe remaining capacity in kilograms.
 *
 * @param {{ capacityKg: number, loadKg: number }} arg
 * @returns {{ remainingKg: number, utilisation: number, overloaded: boolean }}
 */
export function capacityReport({ capacityKg, loadKg }) {
  assertKilograms('capacityKg', capacityKg);
  assertKilograms('loadKg', loadKg);
  const remainingKg = capacityKg - loadKg;
  const utilisation = capacityKg === 0 ? (loadKg === 0 ? 0 : Infinity) : loadKg / capacityKg;
  return { remainingKg, utilisation, overloaded: remainingKg < 0 };
}

/**
 * Time handling.
 *
 * Every timestamp in Harbor Dispatch is a UTC value supplied by the caller as
 * an ISO-8601 string ending in "Z". The domain never reads the system clock:
 * all "now" values arrive as arguments. Internally, instants are held as
 * integer milliseconds since the Unix epoch so they can be compared cheaply.
 */

import { parseUtcTimestamp } from '../ports.js';

/**
 * @typedef {object} Instant
 * @property {number} ms
 * @property {string} utc normalised ISO-8601 string
 */

/**
 * Normalise a caller-supplied UTC timestamp.
 *
 * @param {string} value
 * @returns {Readonly<Instant>}
 */
export function instant(value) {
  const ms = parseUtcTimestamp(value);
  return Object.freeze({ ms, utc: new Date(ms).toISOString() });
}

/**
 * Order two instants.
 *
 * @param {{ ms: number }} a
 * @param {{ ms: number }} b
 * @returns {number}
 */
export function compareInstants(a, b) {
  return a.ms - b.ms;
}

/**
 * Whether `instant` lies in the half-open window `[from, to)`.
 *
 * @param {{ ms: number }} value
 * @param {{ ms: number }} from
 * @param {{ ms: number }} to
 * @returns {boolean}
 */
export function isWithin(value, from, to) {
  return value.ms >= from.ms && value.ms < to.ms;
}

/**
 * Duration in whole UTC days between two instants.
 *
 * @param {{ ms: number }} from
 * @param {{ ms: number }} to
 * @returns {number}
 */
export function wholeDaysBetween(from, to) {
  return Math.floor((to.ms - from.ms) / 86_400_000);
}

/**
 * Vessels.
 *
 * A vessel is a physical hull owned by the cooperative. It has a fixed cargo
 * capacity in integer kilograms and is not tied to any particular date. A
 * vessel is scheduled by creating Sailings that reference it.
 */

import { assertOpaqueId } from './ids.js';
import { assertPositiveKilograms } from './capacity.js';

/**
 * @typedef {object} Vessel
 * @property {string} id opaque vessel id
 * @property {string} name human label
 * @property {number} capacityKg integer kilograms the hull can carry
 */

/**
 * @param {{ id: string, name?: string, capacityKg: number }} spec
 * @returns {Readonly<Vessel>}
 */
export function createVessel(spec) {
  if (spec === null || typeof spec !== 'object') {
    throw new TypeError('vessel spec must be an object');
  }
  const id = assertOpaqueId('vessel id', spec.id);
  const capacityKg = assertPositiveKilograms('vessel capacityKg', spec.capacityKg);
  const name = typeof spec.name === 'string' && spec.name.length > 0 ? spec.name : id;
  return Object.freeze({ id, name, capacityKg });
}

/**
 * Look a vessel up in a collection.
 *
 * @param {Map<string, Readonly<Vessel>>} vessels
 * @param {string} vesselId
 * @returns {Readonly<Vessel>}
 */
export function requireVessel(vessels, vesselId) {
  const vessel = vessels.get(vesselId);
  if (!vessel) {
    throw new RangeError(`unknown vessel: ${String(vesselId)}`);
  }
  return vessel;
}

/**
 * Sailings.
 *
 * A sailing is one dated departure of a vessel along a route, from an origin
 * port to a destination port. Sailings are the unit of capacity: bookings are
 * made against a sailing, never against a vessel directly. A vessel may have
 * any number of sailings over the planning horizon, subject to scheduling
 * rules enforced elsewhere.
 */

import { assertOpaqueId } from './ids.js';
import { assertKilograms } from './capacity.js';
import { instant } from './time.js';
import { requireVessel } from './vessels.js';
import { assertPortId } from '../ports.js';

/**
 * @typedef {object} Sailing
 * @property {string} id opaque sailing id
 * @property {string} vesselId
 * @property {string} routeId opaque route id
 * @property {string} originPortId
 * @property {string} destinationPortId
 * @property {Readonly<import('./time.js').Instant>} departsAt
 * @property {Readonly<import('./time.js').Instant>} arrivesAt
 * @property {number} capacityKg integer kilograms available for consignments
 */

/**
 * @param {{
 *   id: string,
 *   vesselId: string,
 *   routeId: string,
 *   originPortId: string,
 *   destinationPortId: string,
 *   departsAtUtc: string,
 *   arrivesAtUtc: string,
 *   capacityKg?: number,
 * }} spec
 * @param {{ vessel: Readonly<import('./vessels.js').Vessel> }} context
 * @returns {Readonly<Sailing>}
 */
export function createSailing(spec, context) {
  if (spec === null || typeof spec !== 'object') {
    throw new TypeError('sailing spec must be an object');
  }
  const id = assertOpaqueId('sailing id', spec.id);
  const vesselId = assertOpaqueId('vessel id', spec.vesselId);
  const routeId = assertOpaqueId('route id', spec.routeId);
  const originPortId = assertPortId(spec.originPortId);
  const destinationPortId = assertPortId(spec.destinationPortId);
  if (originPortId === destinationPortId) {
    throw new RangeError('a sailing must arrive at a different port than it departs from');
  }

  const vessel = context?.vessel ?? requireVesselFromContext(vesselId);
  if (vessel.id !== vesselId) {
    throw new RangeError('sailing vesselId does not match the supplied vessel');
  }

  const departsAt = instant(spec.departsAtUtc);
  const arrivesAt = instant(spec.arrivesAtUtc);
  if (arrivesAt.ms <= departsAt.ms) {
    throw new RangeError('a sailing must arrive after it departs');
  }

  // A sailing's capacity can be limited (maintenance deck closed, ferry
  // weight certificate), but never exceed the hull's capacity.
  const capacityKg =
    spec.capacityKg === undefined
      ? vessel.capacityKg
      : assertKilograms('sailing capacityKg', spec.capacityKg);
  if (capacityKg === 0) {
    throw new RangeError('a sailing capacityKg must be greater than zero');
  }
  if (capacityKg > vessel.capacityKg) {
    throw new RangeError(
      `sailing capacityKg (${capacityKg}) exceeds vessel capacityKg (${vessel.capacityKg})`,
    );
  }

  return Object.freeze({
    id,
    vesselId,
    routeId,
    originPortId,
    destinationPortId,
    departsAt,
    arrivesAt,
    capacityKg,
  });
}

/**
 * @param {string} vesselId
 * @returns {never}
 */
function requireVesselFromContext(vesselId) {
  throw new TypeError(`sailing ${vesselId} requires a vessel context`);
}

