/**
 * Consignments.
 *
 * A consignment is the cargo itself: an opaque cargo id, a mass in integer
 * kilograms, an origin and a destination port. A consignment is a thing to be
 * moved, not a reservation — it does not know which sailing will carry it.
 * A booking is the reservation that ties a consignment to a sailing.
 */

import { assertOpaqueId } from './ids.js';
import { assertPositiveKilograms } from './capacity.js';
import { assertPortId } from '../ports.js';

/**
 * @typedef {object} Consignment
 * @property {string} id opaque cargo id
 * @property {string} reference human-readable shipment reference
 * @property {number} massKg integer kilograms, strictly positive
 * @property {string} originPortId
 * @property {string} destinationPortId
 */

/**
 * @param {{
 *   id: string,
 *   reference?: string,
 *   massKg: number,
 *   originPortId: string,
 *   destinationPortId: string,
 * }} spec
 * @returns {Readonly<Consignment>}
 */
export function createConsignment(spec) {
  if (spec === null || typeof spec !== 'object') {
    throw new TypeError('consignment spec must be an object');
  }
  const id = assertOpaqueId('consignment id', spec.id);
  const massKg = assertPositiveKilograms('consignment massKg', spec.massKg);
  const originPortId = assertPortId(spec.originPortId);
  const destinationPortId = assertPortId(spec.destinationPortId);
  if (originPortId === destinationPortId) {
    throw new RangeError('a consignment must have distinct origin and destination ports');
  }
  const reference =
    typeof spec.reference === 'string' && spec.reference.length > 0 ? spec.reference : id;
  return Object.freeze({ id, reference, massKg, originPortId, destinationPortId });
}

/**
 * A consignment may only travel on a sailing that runs the same port pair in
 * the same direction.
 *
 * @param {Readonly<Consignment>} consignment
 * @param {Readonly<import('./sailings.js').Sailing>} sailing
 * @returns {boolean}
 */
export function consignmentFitsRoute(consignment, sailing) {
  return (
    consignment.originPortId === sailing.originPortId &&
    consignment.destinationPortId === sailing.destinationPortId
  );
}

/**
 * Bookings.
 *
 * A booking reserves space on a specific sailing for a specific consignment.
 * It is the join between the two: the consignment holds the cargo and the
 * ports, the sailing holds the vessel and the schedule, and the booking holds
 * the reservation state and the moment the reservation was made.
 *
 * Booking lifecycle: `held` -> `confirmed` -> (`cancelled` | `shipped`).
 * A booking holds capacity while `held` or `confirmed`.
 */

import { assertOpaqueId } from './ids.js';
import { instant } from './time.js';
import { consignmentFitsRoute } from './consignments.js';

/** @typedef {'held' | 'confirmed' | 'cancelled' | 'shipped'} BookingStatus */

const STATUSES = new Set(['held', 'confirmed', 'cancelled', 'shipped']);
const OCCUPYING = new Set(['held', 'confirmed']);

/**
 * @typedef {object} Booking
 * @property {string} id opaque booking id
 * @property {string} consignmentId
 * @property {string} sailingId
 * @property {BookingStatus} status
 * @property {number} massKg mass reserved on the sailing (integer kilograms)
 * @property {Readonly<import('./time.js').Instant>} bookedAt
 */

/**
 * Create a booking. Port compatibility is checked against the consignment and
 * the sailing here so that an invalid booking can never exist.
 *
 * @param {{
 *   id: string,
 *   consignment: Readonly<import('./consignments.js').Consignment>,
 *   sailing: Readonly<import('./sailings.js').Sailing>,
 *   bookedAtUtc: string,
 *   status?: BookingStatus,
 * }} spec
 * @returns {Readonly<Booking>}
 */
export function createBooking(spec) {
  if (spec === null || typeof spec !== 'object') {
    throw new TypeError('booking spec must be an object');
  }
  const id = assertOpaqueId('booking id', spec.id);
  const consignment = spec.consignment;
  const sailing = spec.sailing;
  if (!consignment || !sailing) {
    throw new TypeError('createBooking requires both a consignment and a sailing');
  }
  if (!consignmentFitsRoute(consignment, sailing)) {
    throw new RangeError(
      `consignment ${consignment.id} port pair does not match sailing ${sailing.id}`,
    );
  }
  const status = spec.status ?? 'held';
  if (!STATUSES.has(status)) {
    throw new RangeError(`unknown booking status: ${String(status)}`);
  }
  const bookedAt = instant(spec.bookedAtUtc);
  return Object.freeze({
    id,
    consignmentId: consignment.id,
    sailingId: sailing.id,
    status,
    massKg: consignment.massKg,
    bookedAt,
  });
}

/**
 * Whether a booking currently occupies sailing capacity.
 *
 * @param {Readonly<Booking>} booking
 * @returns {boolean}
 */
export function occupiesCapacity(booking) {
  return OCCUPYING.has(booking.status);
}

/**
 * Transition a booking to a new status. Returns a new frozen object; the
 * input booking is never mutated.
 *
 * @param {Readonly<Booking>} booking
 * @param {BookingStatus} status
 * @returns {Readonly<Booking>}
 */
export function transitionBooking(booking, status) {
  if (!STATUSES.has(status)) {
    throw new RangeError(`unknown booking status: ${String(status)}`);
  }
  const allowed = {
    held: new Set(['confirmed', 'cancelled']),
    confirmed: new Set(['cancelled', 'shipped']),
    cancelled: new Set(),
    shipped: new Set(),
  };
  if (!allowed[booking.status].has(status)) {
    throw new RangeError(`cannot move booking ${booking.id} from ${booking.status} to ${status}`);
  }
  return Object.freeze({ ...booking, status });
}

