/**
 * The planning board.
 *
 * A board is an in-memory registry of vessels, sailings, consignments and
 * bookings for one planning horizon. It is deliberately small and
 * synchronous: the cooperative runs Harbor Dispatch offline, so everything is
 * plain data passed in by the caller.
 */

import { assertOpaqueId } from './ids.js';
import { sumKilograms, capacityReport } from './capacity.js';
import { planningHorizon, isWithinHorizon } from '../ports.js';
import { createVessel } from './vessels.js';
import { createSailing } from './sailings.js';
import { createConsignment } from './consignments.js';
import { createBooking, occupiesCapacity, transitionBooking } from './bookings.js';
import { DEFAULT_PLANNING_HORIZON_DAYS } from '../ports.js';

/**
 * @typedef {object} Board
 */

/**
 * Create an empty planning board anchored at a caller-supplied UTC start.
 *
 * @param {{ startUtc: string, horizonDays?: number }} spec
 * @returns {Readonly<Board> & { horizon: Readonly<{ startMs: number, endMs: number, days: number }> }}
 */
export function createBoard(spec) {
  if (spec === null || typeof spec !== 'object') {
    throw new TypeError('board spec must be an object');
  }
  const horizon = planningHorizon(
    spec.startUtc,
    spec.horizonDays ?? DEFAULT_PLANNING_HORIZON_DAYS,
  );
  const board = {
    horizon,
    vessels: new Map(),
    sailings: new Map(),
    consignments: new Map(),
    bookings: new Map(),
  };
  return Object.freeze({
    horizon: board.horizon,
    vessels: board.vessels,
    sailings: board.sailings,
    consignments: board.consignments,
    bookings: board.bookings,
    // The methods below are plain closures over the same maps; freezing the
    // wrapper keeps callers from swapping the maps out from under us.
    addVessel: (vesselSpec) => addVessel(board, vesselSpec),
    addSailing: (sailingSpec) => addSailing(board, sailingSpec),
    addConsignment: (consignmentSpec) => addConsignment(board, consignmentSpec),
    book: (bookingSpec) => book(board, bookingSpec),
    changeBookingStatus: (bookingId, status) => changeBookingStatus(board, bookingId, status),
    loadFor: (sailingId) => loadFor(board, sailingId),
    capacityFor: (sailingId) => capacityFor(board, sailingId),
  });
}

/**
 * @param {Board} board
 * @param {any} spec
 */
function addVessel(board, spec) {
  const vessel = createVessel(spec);
  if (board.vessels.has(vessel.id)) {
    throw new RangeError(`duplicate vessel id: ${vessel.id}`);
  }
  board.vessels.set(vessel.id, vessel);
  return vessel;
}

/**
 * @param {Board} board
 * @param {any} spec
 */
function addSailing(board, spec) {
  const vessel = board.vessels.get(spec?.vesselId);
  if (!vessel) {
    throw new RangeError(`unknown vessel: ${String(spec?.vesselId)}`);
  }
  const sailing = createSailing(spec, { vessel });
  if (board.sailings.has(sailing.id)) {
    throw new RangeError(`duplicate sailing id: ${sailing.id}`);
  }
  // Sailings must be planned inside the horizon, measured by departure.
  if (!isWithinHorizon(board.horizon, sailing.departsAt.utc)) {
    throw new RangeError(`sailing ${sailing.id} departs outside the planning horizon`);
  }
  board.sailings.set(sailing.id, sailing);
  return sailing;
}

/**
 * @param {Board} board
 * @param {any} spec
 */
function addConsignment(board, spec) {
  const consignment = createConsignment(spec);
  if (board.consignments.has(consignment.id)) {
    throw new RangeError(`duplicate consignment id: ${consignment.id}`);
  }
  board.consignments.set(consignment.id, consignment);
  return consignment;
}

/**
 * @param {Board} board
 * @param {any} spec
 */
function book(board, spec) {
  const sailing = board.sailings.get(spec?.sailingId);
  if (!sailing) {
    throw new RangeError(`unknown sailing: ${String(spec?.sailingId)}`);
  }
  const consignment = board.consignments.get(spec?.consignmentId);
  if (!consignment) {
    throw new RangeError(`unknown consignment: ${String(spec?.consignmentId)}`);
  }
  const bookingId = assertOpaqueId('booking id', spec?.id);
  if (board.bookings.has(bookingId)) {
    throw new RangeError(`duplicate booking id: ${bookingId}`);
  }
  const booking = createBooking({
    id: bookingId,
    consignment,
    sailing,
    bookedAtUtc: spec.bookedAtUtc,
    status: spec.status,
  });
  if (occupiesCapacity(booking)) {
    const current = loadFor(board, sailing.id);
    if (current + booking.massKg > sailing.capacityKg) {
      throw new RangeError(
        `booking ${booking.id} would overload sailing ${sailing.id}: ` +
          `${current + booking.massKg} kg > ${sailing.capacityKg} kg`,
      );
    }
  }
  board.bookings.set(booking.id, booking);
  return booking;
}

/**
 * @param {Board} board
 * @param {string} bookingId
 * @param {import('./bookings.js').BookingStatus} status
 */
function changeBookingStatus(board, bookingId, status) {
  const booking = board.bookings.get(bookingId);
  if (!booking) {
    throw new RangeError(`unknown booking: ${String(bookingId)}`);
  }
  const next = transitionBooking(booking, status);
  if (occupiesCapacity(next) && !occupiesCapacity(booking)) {
    const sailing = board.sailings.get(next.sailingId);
    const current = loadFor(board, sailing.id);
    if (current + next.massKg > sailing.capacityKg) {
      throw new RangeError(
        `confirming booking ${next.id} would overload sailing ${sailing.id}`,
      );
    }
  }
  board.bookings.set(next.id, next);
  return next;
}

/**
 * Total mass reserved on a sailing by bookings that occupy capacity.
 *
 * @param {Board} board
 * @param {string} sailingId
 * @returns {number} integer kilograms
 */
function loadFor(board, sailingId) {
  const masses = [];
  for (const booking of board.bookings.values()) {
    if (booking.sailingId === sailingId && occupiesCapacity(booking)) {
      masses.push(booking.massKg);
    }
  }
  return sumKilograms(masses);
}

/**
 * @param {Board} board
 * @param {string} sailingId
 */
function capacityFor(board, sailingId) {
  const sailing = board.sailings.get(sailingId);
  if (!sailing) {
    throw new RangeError(`unknown sailing: ${String(sailingId)}`);
  }
  return capacityReport({ capacityKg: sailing.capacityKg, loadKg: loadFor(board, sailingId) });
}

/**
 * Harbor Dispatch — offline freight planning for a fictional island
 * cooperative.
 *
 * Public surface. Everything below is plain data plus pure functions; no
 * network, no filesystem, no system clock.
 */

export {
  DEFAULT_PLANNING_HORIZON_DAYS,
  assertPortId,
  definePort,
  parseUtcTimestamp,
  planningHorizon,
  isWithinHorizon,
} from './ports.js';

export { assertOpaqueId, sameId } from './domain/ids.js';
export {
  assertKilograms,
  assertPositiveKilograms,
  sumKilograms,
  capacityReport,
} from './domain/capacity.js';
export { instant, compareInstants, isWithin, wholeDaysBetween } from './domain/time.js';
export { createVessel, requireVessel } from './domain/vessels.js';
export { createSailing } from './domain/sailings.js';
export { createConsignment, consignmentFitsRoute } from './domain/consignments.js';
export { createBooking, occupiesCapacity, transitionBooking } from './domain/bookings.js';
export { createBoard } from './domain/board.js';

