arguments.content:
import test from 'node:test';
import assert from 'node:assert/strict';

import {
  DEFAULT_PLANNING_HORIZON_DAYS,
  assertPortId,
  definePort,
  parseUtcTimestamp,
  planningHorizon,
  isWithinHorizon,
} from '../src/ports.js';

test('planning horizon defaults to 21 days', () => {
  assert.equal(DEFAULT_PLANNING_HORIZON_DAYS, 21);
  const h = planningHorizon('2030-01-01T00:00:00Z');
  assert.equal(h.days, 21);
  assert.equal(h.endMs - h.startMs, 21 * 86_400_000);
});

test('planning horizon honours an explicit day count', () => {
  const h = planningHorizon('2030-01-01T00:00:00Z', 7);
  assert.equal(h.endMs - h.startMs, 7 * 86_400_000);
  assert.throws(() => planningHorizon('2030-01-01T00:00:00Z', 0), RangeError);
  assert.throws(() => planningHorizon('2030-01-01T00:00:00Z', 2.5), RangeError);
});

test('timestamps must be UTC', () => {
  assert.equal(parseUtcTimestamp('2030-01-01T00:00:00Z'), Date.parse('2030-01-01T00:00:00Z'));
  assert.throws(() => parseUtcTimestamp('2030-01-01T00:00:00+02:00'), RangeError);
  assert.throws(() => parseUtcTimestamp('2030-01-01T00:00:00'), RangeError);
  assert.throws(() => parseUtcTimestamp('not a date'), RangeError);
  assert.throws(() => parseUtcTimestamp(1234), TypeError);
});

test('horizon membership is half-open', () => {
  const h = planningHorizon('2030-01-01T00:00:00Z', 1);
  assert.equal(isWithinHorizon(h, '2030-01-01T00:00:00Z'), true);
  assert.equal(isWithinHorizon(h, '2030-01-01T23:59:59Z'), true);
  assert.equal(isWithinHorizon(h, '2030-01-02T00:00:00Z'), false);
  assert.equal(isWithinHorizon(h, '2029-12-31T23:59:59Z'), false);
});

test('port ids are opaque and required', () => {
  assert.equal(assertPortId('x-9'), 'x-9');
  assert.throws(() => assertPortId(''), TypeError);
  assert.throws(() => assertPortId(42), TypeError);

  const port = definePort({ id: 'p-alpha', name: 'Alpha Cove' });
  assert.deepEqual(port, { id: 'p-alpha', name: 'Alpha Cove' });
  assert.ok(Object.isFrozen(port));

  // Name falls back to the id; the id is never parsed.
  assert.equal(definePort({ id: 'p/odd:id' }).name, 'p/odd:id');
});

test('port ids are compared by equality only', () => {
  // Structurally odd but legal: ids are compared as whole strings.
  assert.notEqual('a:b', 'a');
  assert.equal(assertPortId('a:b'), assertPortId('a:b'));
});

import test from 'node:test';
import assert from 'node:assert/strict';

import {
  assertKilograms,
  assertPositiveKilograms,
  sumKilograms,
  capacityReport,
} from '../src/domain/capacity.js';

test('mass must be an integer number of kilograms', () => {
  assert.equal(assertKilograms('mass', 0), 0);
  assert.equal(assertKilograms('mass', 1400), 1400);
  assert.throws(() => assertKilograms('mass', 1.5), TypeError);
  assert.throws(() => assertKilograms('mass', '12'), TypeError);
  assert.throws(() => assertKilograms('mass', -1), RangeError);
  assert.throws(() => assertKilograms('mass', 2 ** 60), RangeError);
});

test('positive mass rejects zero', () => {
  assert.equal(assertPositiveKilograms('mass', 1), 1);
  assert.throws(() => assertPositiveKilograms('mass', 0), RangeError);
});

test('sumKilograms adds integers exactly', () => {
  assert.equal(sumKilograms([]), 0);
  assert.equal(sumKilograms([1, 2, 3]), 6);
  assert.throws(() => sumKilograms([1, 0.5]), TypeError);
  assert.throws(() => sumKilograms([Number.MAX_SAFE_INTEGER, 1]), RangeError);
});

test('capacityReport describes headroom', () => {
  assert.deepEqual(capacityReport({ capacityKg: 100, loadKg: 40 }), {
    remainingKg: 60,
    utilisation: 0.4,
    overloaded: false,
  });
  assert.equal(capacityReport({ capacityKg: 100, loadKg: 120 }).overloaded, true);
  assert.equal(capacityReport({ capacityKg: 100, loadKg: 100 }).remainingKg, 0);
});

import test from 'node:test';
import assert from 'node:assert/strict';

import { instant, compareInstants, isWithin, wholeDaysBetween } from '../src/domain/time.js';

test('instants normalise supplied UTC values', () => {
  const a = instant('2030-03-01T06:00:00Z');
  assert.equal(a.utc, '2030-03-01T06:00:00.000Z');
  assert.ok(Object.isFrozen(a));
  assert.throws(() => instant('2030-03-01T06:00:00'), RangeError);
});

test('instants never consult the clock', () => {
  const a = instant('2031-06-01T00:00:00Z');
  const b = instant('2031-06-02T00:00:00Z');
  assert.equal(compareInstants(a, b), -86400000);
  assert.equal(wholeDaysBetween(a, b), 1);
});

test('isWithin is half-open', () => {
  const from = instant('2030-01-01T00:00:00Z');
  const to = instant('2030-01-02T00:00:00Z');
  assert.equal(isWithin(from, from, to), true);
  assert.equal(isWithin(to, from, to), false);
});

import test from 'node:test';
import assert from 'node:assert/strict';

import { createVessel, requireVessel } from '../src/domain/vessels.js';

test('a vessel has an opaque id and integer kilogram capacity', () => {
  const v = createVessel({ id: 'v-1', name: 'Harbor Skiff', capacityKg: 5000 });
  assert.deepEqual(v, { id: 'v-1', name: 'Harbor Skiff', capacityKg: 5000 });
  assert.ok(Object.isFrozen(v));
});

test('vessel ids are opaque strings', () => {
  assert.throws(() => createVessel({ id: '', capacityKg: 10 }), RangeError);
  assert.throws(() => createVessel({ id: 7, capacityKg: 10 }), TypeError);
  assert.throws(() => createVessel({ id: 'v', capacityKg: 10 }).id.slice, undefined);
  // Odd-looking ids are fine.
  assert.equal(createVessel({ id: '::weird::', capacityKg: 1 }).id, '::weird::');
});

test('vessel capacity must be a positive integer', () => {
  assert.throws(() => createVessel({ id: 'v', capacityKg: 0 }), RangeError);
  assert.throws(() => createVessel({ id: 'v', capacityKg: 12.5 }), TypeError);
  assert.throws(() => createVessel({ id: 'v', capacityKg: -3 }), RangeError);
});

test('requireVessel looks up or throws', () => {
  const v = createVessel({ id: 'v-a', capacityKg: 100 });
  const map = new Map([[v.id, v]]);
  assert.equal(requireVessel(map, 'v-a'), v);
  assert.throws(() => requireVessel(map, 'missing'), RangeError);
});

import test from 'node:test';
import assert from 'node:assert/strict';

import { createVessel } from '../src/domain/vessels.js';
import { createSailing } from '../src/domain/sailings.js';

const vessel = createVessel({ id: 'v-1', capacityKg: 8000 });

function spec(overrides = {}) {
  return {
    id: 's-1',
    vesselId: 'v-1',
    routeId: 'route-abc',
    originPortId: 'p-north',
    destinationPortId: 'p-south',
    departsAtUtc: '2030-01-02T08:00:00Z',
    arrivesAtUtc: '2030-01-02T14:00:00Z',
    ...overrides,
  };
}

test('a sailing binds a vessel, a route and two ports at UTC times', () => {
  const s = createSailing(spec(), { vessel });
  assert.equal(s.vesselId, 'v-1');
  assert.equal(s.routeId, 'route-abc');
  assert.equal(s.originPortId, 'p-north');
  assert.equal(s.destinationPortId, 'p-south');
  assert.equal(s.departsAt.utc, '2030-01-02T08:00:00.000Z');
  assert.equal(s.capacityKg, 8000, 'defaults to the vessel capacity');
  assert.ok(Object.isFrozen(s));
});

test('sailing capacity may be limited but not exceed the hull', () => {
  assert.equal(createSailing(spec({ capacityKg: 3000 }), { vessel }).capacityKg, 3000);
  assert.throws(() => createSailing(spec({ capacityKg: 8001 }), { vessel }), RangeError);
  assert.throws(() => createSailing(spec({ capacityKg: 0 }), { vessel }), RangeError);
  assert.throws(() => createSailing(spec({ capacityKg: 1.5 }), { vessel }), TypeError);
});

test('sailings must move between distinct ports and forward in time', () => {
  assert.throws(
    () => createSailing(spec({ destinationPortId: 'p-north' }), { vessel }),
    RangeError,
  );
  assert.throws(
    () => createSailing(spec({ arrivesAtUtc: '2030-01-02T07:00:00Z' }), { vessel }),
    RangeError,
  );
  assert.throws(
    () => createSailing(spec({ departsAtUtc: '2030-01-02T07:00:00+00:00' }), { vessel }),
    RangeError,
  );
});

test('a sailing requires a matching vessel context', () => {
  assert.throws(() => createSailing(spec(), undefined), TypeError);
  const other = createVessel({ id: 'v-2', capacityKg: 100 });
  assert.throws(() => createSailing(spec(), { vessel: other }), RangeError);
});

import test from 'node:test';
import assert from 'node:assert/strict';

import { createConsignment, consignmentFitsRoute } from '../src/domain/consignments.js';
import { createSailing } from '../src/domain/sailings.js';
import { createVessel } from '../src/domain/vessels.js';

function consignment(overrides = {}) {
  return createConsignment({
    id: 'c-1',
    reference: 'REF-1',
    massKg: 450,
    originPortId: 'p-north',
    destinationPortId: 'p-south',
    ...overrides,
  });
}

test('a consignment carries integer kilogram mass and a port pair', () => {
  const c = consignment();
  assert.deepEqual(c, {
    id: 'c-1',
    reference: 'REF-1',
    massKg: 450,
    originPortId: 'p-north',
    destinationPortId: 'p-south',
  });
  assert.ok(Object.isFrozen(c));
});

test('consignment mass must be strictly positive integer kilograms', () => {
  assert.throws(() => consignment({ massKg: 0 }), RangeError);
  assert.throws(() => consignment({ massKg: 2.2 }), TypeError);
});

test('consignments need distinct ports', () => {
  assert.throws(() => consignment({ destinationPortId: 'p-north' }), RangeError);
});

test('a consignment is not a booking: it knows no sailing', () => {
  const c = consignment();
  assert.equal('sailingId' in c, false);
  assert.equal('status' in c, false);
});

test('route compatibility compares both ports and direction', () => {
  const vessel = createVessel({ id: 'v', capacityKg: 1000 });
  const sailing = createSailing(
    {
      id: 's',
      vesselId: 'v',
      routeId: 'r',
      originPortId: 'p-north',
      destinationPortId: 'p-south',
      departsAtUtc: '2030-01-02T08:00:00Z',
      arrivesAtUtc: '2030-01-02T09:00:00Z',
    },
    { vessel },
  );
  assert.equal(consignmentFitsRoute(consignment(), sailing), true);
  assert.equal(
    consignmentFitsRoute(consignment({ originPortId: 'p-south', destinationPortId: 'p-north' }), sailing),
    false,
  );
});

import test from 'node:test';
import assert from 'node:assert/strict';

import { createBooking, occupiesCapacity, transitionBooking } from '../src/domain/bookings.js';
import { createConsignment } from '../src/domain/consignments.js';
import { createSailing } from '../src/domain/sailings.js';
import { createVessel } from '../src/domain/vessels.js';

const vessel = createVessel({ id: 'v-1', capacityKg: 5000 });
const sailing = createSailing(
  {
    id: 's-1',
    vesselId: 'v-1',
    routeId: 'r-1',
    originPortId: 'p-north',
    destinationPortId: 'p-south',
    departsAtUtc: '2030-01-02T08:00:00Z',
    arrivesAtUtc: '2030-01-02T12:00:00Z',
  },
  { vessel },
);
const consignment = createConsignment({
  id: 'c-1',
  massKg: 300,
  originPortId: 'p-north',
  destinationPortId: 'p-south',
});

function booking(overrides = {}) {
  return createBooking({
    id: 'b-1',
    consignment,
    sailing,
    bookedAtUtc: '2030-01-01T09:00:00Z',
    ...overrides,
  });
}

test('a booking ties a consignment to a sailing', () => {
  const b = booking();
  assert.deepEqual(
    { ...b, bookedAt: b.bookedAt.utc },
    {
      id: 'b-1',
      consignmentId: 'c-1',
      sailingId: 's-1',
      status: 'held',
      massKg: 300,
      bookedAt: '2030-01-01T09:00:00.000Z',
    },
  );
  assert.ok(Object.isFrozen(b));
});

test('booking mass is copied from the consignment', () => {
  assert.equal(booking().massKg, consignment.massKg);
});

test('a booking cannot be made on a mismatched port pair', () => {
  const reverse = createConsignment({
    id: 'c-2',
    massKg: 10,
    originPortId: 'p-south',
    destinationPortId: 'p-north',
  });
  assert.throws(() => booking({ consignment: reverse }), RangeError);
});

test('only live bookings occupy capacity', () => {
  assert.equal(occupiesCapacity(booking()), true);
  assert.equal(occupiesCapacity(booking({ status: 'confirmed' })), true);
  assert.equal(occupiesCapacity(booking({ status: 'cancelled' })), false);
  assert.equal(occupiesCapacity(booking({ status: 'shipped' })), false);
  assert.throws(() => booking({ status: 'nonsense' }), RangeError);
});

test('status transitions follow the lifecycle and are immutable', () => {
  const held = booking();
  const confirmed = transitionBooking(held, 'confirmed');
  assert.equal(held.status, 'held', 'original untouched');
  assert.equal(confirmed.status, 'confirmed');
  assert.ok(Object.isFrozen(confirmed));
  assert.equal(transitionBooking(confirmed, 'shipped').status, 'shipped');
  assert.equal(transitionBooking(held, 'cancelled').status, 'cancelled');
  assert.throws(() => transitionBooking(held, 'shipped'), RangeError);
  assert.throws(() => transitionBooking(confirmed, 'held'), RangeError);
  assert.throws(() => transitionBooking(transitionBooking(held, 'cancelled'), 'confirmed'), RangeError);
});

import test from 'node:test';
import assert from 'node:assert/strict';

import { createBoard } from '../src/domain/board.js';
import { createBoard as fromIndex, DEFAULT_PLANNING_HORIZON_DAYS } from '../src/index.js';

function board(overrides = {}) {
  return createBoard({ startUtc: '2030-01-01T00:00:00Z', ...overrides });
}

function seed(b) {
  b.addVessel({ id: 'v-1', name: 'Harbor Skiff', capacityKg: 1000 });
  b.addVessel({ id: 'v-2', name: 'Kelpline', capacityKg: 2000 });
  b.addSailing({
    id: 's-1',
    vesselId: 'v-1',
    routeId: 'route-a',
    originPortId: 'p-north',
    destinationPortId: 'p-south',
    departsAtUtc: '2030-01-03T08:00:00Z',
    arrivesAtUtc: '2030-01-03T12:00:00Z',
  });
  b.addSailing({
    id: 's-2',
    vesselId: 'v-2',
    routeId: 'route-a',
    originPortId: 'p-north',
    destinationPortId: 'p-south',
    departsAtUtc: '2030-01-04T08:00:00Z',
    arrivesAtUtc: '2030-01-04T15:00:00Z',
  });
  b.addConsignment({
    id: 'c-1',
    massKg: 600,
    originPortId: 'p-north',
    destinationPortId: 'p-south',
  });
  b.addConsignment({
    id: 'c-2',
    massKg: 500,
    originPortId: 'p-north',
    destinationPortId: 'p-south',
  });
}

test('a board starts empty with a 21-day horizon', () => {
  const b = board();
  assert.equal(b.horizon.days, DEFAULT_PLANNING_HORIZON_DAYS);
  assert.equal(b.vessels.size, 0);
  assert.equal(b.sailings.size, 0);
  assert.equal(b.consignments.size, 0);
  assert.equal(b.bookings.size, 0);
  assert.equal(fromIndex({ startUtc: '2030-01-01T00:00:00Z' }).horizon.days, 21);
});

test('sailings must depart within the horizon', () => {
  const b = board({ horizonDays: 1 });
  b.addVessel({ id: 'v-1', capacityKg: 100 });
  assert.throws(
    () =>
      b.addSailing({
        id: 's-late',
        vesselId: 'v-1',
        routeId: 'r',
        originPortId: 'p-a',
        destinationPortId: 'p-b',
        departsAtUtc: '2030-01-02T00:00:00Z',
        arrivesAtUtc: '2030-01-02T01:00:00Z',
      }),
    RangeError,
  );
});

test('registrations reject duplicates and unknown references', () => {
  const b = board();
  seed(b);
  assert.throws(() => b.addVessel({ id: 'v-1', capacityKg: 1 }), RangeError);
  assert.throws(
    () =>
      b.addSailing({
        id: 's-x',
        vesselId: 'nope',
        routeId: 'r',
        originPortId: 'p-north',
        destinationPortId: 'p-south',
        departsAtUtc: '2030-01-03T00:00:00Z',
        arrivesAtUtc: '2030-01-03T01:00:00Z',
      }),
    RangeError,
  );
  assert.throws(() => b.addConsignment({ id: 'c-1', massKg: 1, originPortId: 'p-a', destinationPortId: 'p-b' }), RangeError);
});

test('bookings reserve capacity and overloads are rejected', () => {
  const b = board();
  seed(b);
  b.book({ id: 'b-1', consignmentId: 'c-1', sailingId: 's-1', bookedAtUtc: '2030-01-01T01:00:00Z' });
  assert.equal(b.loadFor('s-1'), 600);
  assert.deepEqual(b.capacityFor('s-1'), {
    remainingKg: 400,
    utilisation: 0.6,
    overloaded: false,
  });
  // c-2 (500 kg) would push s-1 to 1100 kg over its 1000 kg limit.
  assert.throws(
    () => b.book({ id: 'b-2', consignmentId: 'c-2', sailingId: 's-1', bookedAtUtc: '2030-01-01T01:00:00Z' }),
    RangeError,
  );
  // ...but s-2 has room.
  b.book({ id: 'b-2', consignmentId: 'c-2', sailingId: 's-2', bookedAtUtc: '2030-01-01T01:00:00Z' });
  assert.equal(b.loadFor('s-2'), 500);
});

test('cancelling a booking frees capacity and can be rebooked', () => {
  const b = board();
  seed(b);
  b.book({ id: 'b-1', consignmentId: 'c-1', sailingId: 's-1', bookedAtUtc: '2030-01-01T01:00:00Z' });
  b.book({ id: 'b-2', consignmentId: 'c-2', sailingId: 's-1', bookedAtUtc: '2030-01-01T01:00:00Z' });
  assert.throws(
    () => b.book({ id: 'b-3', consignmentId: 'c-2', sailingId: 's-1', bookedAtUtc: '2030-01-01T01:00:00Z' }),
    RangeError,
  );
  b.changeBookingStatus('b-1', 'cancelled');
  assert.equal(b.loadFor('s-1'), 500);
  // A booking created for c-1 would exceed the remainder; enforces integer kg.
  const small = b.addConsignment({ id: 'c-small', massKg: 500, originPortId: 'p-north', destinationPortId: 'p-south' });
  assert.equal(small.massKg, 500);
  b.book({ id: 'b-3', consignmentId: 'c-small', sailingId: 's-1', bookedAtUtc: '2030-01-01T02:00:00Z' });
  assert.equal(b.loadFor('s-1'), 1000);
  assert.equal(b.capacityFor('s-1').remainingKg, 0);
});

test('re-confirming a cancelled booking re-checks capacity', () => {
  const b = board();
  seed(b);
  const held = b.book({ id: 'b-1', consignmentId: 'c-1', sailingId: 's-1', bookedAtUtc: '2030-01-01T01:00:00Z' });
  // A brand-new held booking on the same sailing would overload, so create a
  // small extra consignment to fill the remaining room instead.
  b.changeBookingStatus(held.id, 'confirmed');
  b.changeBookingStatus(held.id, 'cancelled');
  assert.equal(b.loadFor('s-1'), 0);
  b.changeBookingStatus(held.id, 'confirmed'); // allowed: room available again
  assert.equal(b.loadFor('s-1'), 600);
  assert.throws(() => b.changeBookingStatus('missing', 'confirmed'), RangeError);
});

test('bookings are distinct from consignments and sailings', () => {
  const b = board();
  seed(b);
  const bk = b.book({ id: 'b-1', consignmentId: 'c-1', sailingId: 's-1', bookedAtUtc: '2030-01-01T01:00:00Z' });
  assert.equal(b.consignments.has('b-1'), false);
  assert.equal(b.sailings.has('b-1'), false);
  assert.equal(bk.consignmentId, 'c-1');
  assert.equal(bk.sailingId, 's-1');
  assert.equal(bk.vesselId, undefined, 'bookings do not carry vessels directly');
});

test('route mismatch between consignment and sailing is rejected', () => {
  const b = board();
  seed(b);
