    () => b.book({ id: 'b-x', consignmentId: 'c-rev', sailingId: 's-1', bookedAtUtc: '2030-01-01T01:00:00Z' }),
    RangeError,
  );
});

#!/usr/bin/env node
/**
 * In-process test runner.
 *
 * `node --test` spawns a child process per test file. Some sandboxed
 * environments forbid that. This runner imports each test file into the
 * current process via `node:test`'s `run()` API instead, so the same files
 * work in both places.
 *
 * Usage: node scripts/run-tests.js [test/foo.test.js ...]
 */

import { readdir } from 'node:fs/promises';
import { fileURLToPath, pathToFileURL } from 'node:url';
import path from 'node:path';
import { run } from 'node:test';
import { spec } from 'node:test/reporters';

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(here, '..');

async function collect(args) {
  if (args.length > 0) return args.map((arg) => path.resolve(root, arg));
  const dir = path.join(root, 'test');
  const entries = await readdir(dir);
  return entries
    .filter((name) => name.endsWith('.test.js'))
    .sort()
    .map((name) => path.join(dir, name));
}

const files = await collect(process.argv.slice(2));
if (files.length === 0) {
  console.error('no test files found');
  process.exit(1);
}

// Importing registers the tests; run() executes them in this process.
await Promise.all(files.map((file) => import(pathToFileURL(file).href)));

let failures = 0;
const stream = run({ files: [], concurrency: 1, isolation: 'none' });
// Nothing to run from `files`; tests are already registered on the root.
stream.on('test:fail', () => {
  failures += 1;
});
stream.compose(spec).pipe(process.stdout);

await new Promise((resolve) => stream.on('end', resolve));
process.exitCode = failures > 0 ? 1 : 0;

#!/usr/bin/env node
/**
 * In-process test runner.
 *
 * `node --test` spawns a child process per test file, which some sandboxed
 * environments forbid. This runner imports each test file into the current
 * process (registering its tests with `node:test`) and then reports results.
 *
 * The test files themselves use only public `node:test` APIs, so
 * `node --test test/` works too wherever child processes are allowed.
 *
 * Usage: node scripts/run-tests.js [test/foo.test.js ...]
 * Exit code: 0 when every test passes, 1 otherwise.
 */

import { readdir } from 'node:fs/promises';
import { fileURLToPath, pathToFileURL } from 'node:url';
import path from 'node:path';

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(here, '..');

async function collect(args) {
  const relative =
    args.length > 0
      ? args
      : (await readdir(path.join(root, 'test')))
          .filter((name) => name.endsWith('.test.js'))
          .sort()
          .map((name) => path.join('test', name));
  return relative.map((file) => path.resolve(root, file));
}

const files = await collect(process.argv.slice(2));

// node:test only exports run/reporters; `test()` registers against the active
// root context, which only exists inside a `run()` callback's scope when
// imported eagerly. Importing up front is the documented default behaviour.
const { run } = await import('node:test');

let pass = 0;
let fail = 0;
const failures = [];

function report(name, ok, detail) {
  if (ok) {
    pass += 1;
    console.log(`✔ ${name}`);
  } else {
    fail += 1;
    console.log(`✖ ${name}`);
    if (detail) failures.push(`✖ ${name}\n${detail}`);
  }
}

function indent(text) {
  return String(text)
    .split('\n')
    .map((line) => `    ${line}`)
    .join('\n');
}

const started = new Date();
for (const file of files) {
  try {
    await import(pathToFileURL(file).href);
  } catch (error) {
    report(path.relative(root, file), false, indent(error?.stack ?? error));
  }
}

const stream = run({ concurrency: 1, timeout: 5000 });

for await (const event of stream) {
  if (event.type !== 'test:pass' && event.type !== 'test:fail') continue;
  const data = event.data ?? {};
  // Only leaf tests are counted; suites are reported through their children.
  if (data.nesting === 0 && !data.name) continue;
  const name = data.name ?? '(anonymous test)';
  if (event.type === 'test:pass') {
    if (data.todo || data.skip) {
      console.log(`・ ${name} (${data.todo ? 'todo' : 'skipped'})`);
      continue;
    }
    report(name, true);
  } else {
    const err = data.details?.error;
    report(name, false, err ? indent(err.stack ?? err.message ?? String(err)) : undefined);
  }
}

const elapsed = Date.now() - started.getTime();
if (failures.length > 0) {
  console.log('\nFailing tests:');
  for (const block of failures) console.log(block);
  console.log('');
}
console.log(`tests ${pass + fail}, pass ${pass}, fail ${fail} (${elapsed} ms)`);
process.exitCode = fail === 0 ? 0 : 1;

