#!/usr/bin/env node
/**
 * In-process test runner for Harbor Dispatch.
 *
 * Runs entirely inside one Node process: no child processes, no network, no
 * external dependencies. It imports every `test/*.test.js` file, which
 * registers suites via `tests/helpers.js`, then reports a summary.
 *
 * Exit code: 0 when every test passes, 1 otherwise.
 *
 * Usage: node scripts/run-tests.js [test/foo.test.js ...]
 */

import { readdir } from 'node:fs/promises';
import { fileURLToPath, pathToFileURL } from 'node:url';
import path from 'node:path';

import { getRegistry, resetRegistry } from '../tests/helpers.js';

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(here, '..');

async function collect(args) {
  const relative =
    args.length > 0
      ? args
      : (await readdir(path.join(root, 'test')))
          .filter((name) => name.endsWith('.test.js'))
          .sort()
          .map((name) => path.join('test', name));
  return relative.map((file) => path.resolve(root, file));
}

const files = await collect(process.argv.slice(2));
if (files.length === 0) {
  console.error('no test files found');
  process.exit(1);
}

resetRegistry();
for (const file of files) {
  try {
    await import(pathToFileURL(file).href);
  } catch (error) {
    console.error(`✖ failed to load ${path.relative(root, file)}`);
    console.error(error?.stack ?? error);
    process.exitCode = 1;
  }
}

const { suites } = getRegistry();
let pass = 0;
let fail = 0;
const failures = [];

for (const suite of suites) {
  console.log(suite.name);
  for (const t of suite.tests) {
    try {
      await t.fn();
      pass += 1;
      console.log(`  ✔ ${t.name}`);
    } catch (error) {
      fail += 1;
      console.log(`  ✖ ${t.name}`);
      failures.push({ full: `${suite.name} › ${t.name}`, error });
    }
  }
}

if (failures.length > 0) {
  console.log('\nFailing tests:');
  for (const { full, error } of failures) {
    const message = error?.stack ?? String(error);
    console.log(`\n✖ ${full}`);
    console.log(
      String(message)
        .split('\n')
        .map((line) => `    ${line}`)
        .join('\n'),
    );
  }
  console.log('');
}
console.log(`tests ${pass + fail}, pass ${pass}, fail ${fail}`);
process.exitCode = fail === 0 ? 0 : 1;

/**
 * Minimal dependency-free test helpers.
 *
 * This project keeps its tests inside a single Node process (offline,
 * no child processes, no npm packages), so instead of `node:test` it uses a
 * tiny registry that `scripts/run-tests.js` drains.
 */

const registry = { suites: [] };

export function resetRegistry() {
  registry.suites = [];
}

export function getRegistry() {
  return registry;
}

/**
 * Declare a suite and register its tests.
 *
 * @param {string} name
 * @param {() => void} body called immediately; uses `it()` to register tests
 */
export function describe(name, body) {
  const suite = { name, tests: [] };
  registry.suites.push(suite);
  currentSuite = suite;
  try {
    body();
  } finally {
    currentSuite = null;
  }
  return suite;
}

let currentSuite = null;

/**
 * @param {string} name
 * @param {() => unknown} fn may be async
 */
export function it(name, fn) {
  if (!currentSuite) {
    throw new Error(`it(${JSON.stringify(name)}) must be called inside describe()`);
  }
  currentSuite.tests.push({ name, fn });
}

/* -------------------------------------------------------------------------
 * Assertions
 * ---------------------------------------------------------------------- */

export class AssertionError extends Error {
  constructor(message) {
    super(message);
    this.name = 'AssertionError';
  }
}

function show(value) {
  if (typeof value === 'string') return JSON.stringify(value);
  if (typeof value === 'number' || typeof value === 'boolean' || value == null) return String(value);
  try {
    return JSON.stringify(value);
  } catch {
    return String(value);
  }
}

function deepEqual(a, b) {
  if (Object.is(a, b)) return true;
  if (typeof a !== 'object' || typeof b !== 'object' || a === null || b === null) return false;
  if (Array.isArray(a) !== Array.isArray(b)) return false;
  const ak = Object.keys(a);
  const bk = Object.keys(b);
  if (ak.length !== bk.length) return false;
  return ak.every((key) => deepEqual(a[key], b[key]));
}

export const assert = {
  ok(value, message = 'expected truthy value') {
    if (!value) throw new AssertionError(`${message}: got ${show(value)}`);
  },
  equal(actual, expected, message) {
    if (!Object.is(actual, expected)) {
      throw new AssertionError(
        `${message ? `${message}: ` : ''}expected ${show(expected)}, got ${show(actual)}`,
      );
    }
  },
  notEqual(actual, expected, message) {
    if (Object.is(actual, expected)) {
      throw new AssertionError(`${message ? `${message}: ` : ''}expected values to differ`);
    }
  },
  deepEqual(actual, expected, message) {
    if (!deepEqual(actual, expected)) {
      throw new AssertionError(
        `${message ? `${message}: ` : ''}expected ${show(expected)}, got ${show(actual)}`,
      );
    }
  },
  /**
   * Assert that `fn` throws. `kind` may be a constructor to check the class.
   */
  throws(fn, kind, message) {
    let thrown;
    let threw = false;
    try {
      fn();
    } catch (error) {
      threw = true;
      thrown = error;
    }
    if (!threw) {
      throw new AssertionError(`${message ? `${message}: ` : ''}expected a throw, nothing thrown`);
    }
    if (typeof kind === 'function' && !(thrown instanceof kind)) {
      throw new AssertionError(
        `${message ? `${message}: ` : ''}expected ${kind.name}, got ${thrown?.name ?? typeof thrown}: ${thrown?.message ?? thrown}`,
      );
    }
    return thrown;
  },
};

import { describe, it, assert } from '../tests/helpers.js';

import {
  DEFAULT_PLANNING_HORIZON_DAYS,
  assertPortId,
  definePort,
  parseUtcTimestamp,
  planningHorizon,
  isWithinHorizon,
} from '../src/ports.js';

describe('ports and planning horizon', () => {
  it('defaults the planning horizon to 21 days', () => {
    assert.equal(DEFAULT_PLANNING_HORIZON_DAYS, 21);
    const h = planningHorizon('2030-01-01T00:00:00Z');
    assert.equal(h.days, 21);
    assert.equal(h.endMs - h.startMs, 21 * 86_400_000);
  });

  it('honours an explicit horizon day count', () => {
    const h = planningHorizon('2030-01-01T00:00:00Z', 7);
    assert.equal(h.endMs - h.startMs, 7 * 86_400_000);
    assert.throws(() => planningHorizon('2030-01-01T00:00:00Z', 0), RangeError);
    assert.throws(() => planningHorizon('2030-01-01T00:00:00Z', 2.5), RangeError);
  });

  it('requires UTC timestamps', () => {
    assert.equal(parseUtcTimestamp('2030-01-01T00:00:00Z'), Date.parse('2030-01-01T00:00:00Z'));
    assert.throws(() => parseUtcTimestamp('2030-01-01T00:00:00+02:00'), RangeError);
    assert.throws(() => parseUtcTimestamp('2030-01-01T00:00:00'), RangeError);
    assert.throws(() => parseUtcTimestamp('not a date'), RangeError);
    assert.throws(() => parseUtcTimestamp(1234), TypeError);
  });

  it('treats horizon membership as half-open', () => {
    const h = planningHorizon('2030-01-01T00:00:00Z', 1);
    assert.equal(isWithinHorizon(h, '2030-01-01T00:00:00Z'), true);
    assert.equal(isWithinHorizon(h, '2030-01-01T23:59:59Z'), true);
    assert.equal(isWithinHorizon(h, '2030-01-02T00:00:00Z'), false);
    assert.equal(isWithinHorizon(h, '2029-12-31T23:59:59Z'), false);
  });

  it('requires port ids to be non-empty opaque strings', () => {
    assert.equal(assertPortId('x-9'), 'x-9');
    assert.throws(() => assertPortId(''), TypeError);
    assert.throws(() => assertPortId(42), TypeError);

    const port = definePort({ id: 'p-alpha', name: 'Alpha Cove' });
    assert.deepEqual(port, { id: 'p-alpha', name: 'Alpha Cove' });
    assert.ok(Object.isFrozen(port));
  });

  it('never parses port id structure', () => {
    // Delimiter-heavy ids are legal; only whole-string equality matters.
    assert.equal(definePort({ id: 'p/odd:id' }).name, 'p/odd:id');
    assert.notEqual('a:b', 'a');
    assert.equal(assertPortId('a:b'), assertPortId('a:b'));
  });
});

import { describe, it, assert } from '../tests/helpers.js';

import {
  assertKilograms,
  assertPositiveKilograms,
  sumKilograms,
