  it('accepts only integer kilograms', () => {
    assert.equal(assertKilograms('mass', 0), 0);
    assert.equal(assertKilograms('mass', 1400), 1400);
    assert.throws(() => assertKilograms('mass', 1.5), TypeError, 'fractional kilograms');
    assert.throws(() => assertKilograms('mass', '12'), TypeError, 'string kilograms');
    assert.throws(() => assertKilograms('mass', -1), RangeError, 'negative kilograms');
    assert.throws(() => assertKilograms('mass', 2 ** 60), RangeError, 'unsafe integers');
  });

  it('rejects zero for positive masses', () => {
    assert.equal(assertPositiveKilograms('mass', 1), 1);
    assert.throws(() => assertPositiveKilograms('mass', 0), RangeError);
