    assert.equal(a.utc, '2030-03-01T06:00:00.000Z');
    assert.ok(Object.isFrozen(a));
    assert.throws(() => instant('2030-03-01T06:00:00'), RangeError, 'missing Z');
  });

  it('compares and measures instants without consulting the clock', () => {
    const a = instant('2031-06-01T00:00:00Z');
