        massKg: 300,
        bookedAt: '2030-01-01T09:00:00.000Z',
      },
    );
    assert.ok(Object.isFrozen(b));
  });

  it('copy mass from the consignment', () => {
    assert.equal(booking().massKg, consignment.massKg);
  });

  it('reject mismatched port pairs', () => {
    const reverse = createConsignment({
      id: 'c-2',
      massKg: 10,
      originPortId: 'p-south',
      destinationPortId: 'p-north',
    });
    assert.throws(() => booking({ consignment: reverse }), RangeError);
  });

  it('occupy capacity only while held or confirmed', () => {
    assert.equal(occupiesCapacity(booking()), true);
    assert.equal(occupiesCapacity(booking({ status: 'confirmed' })), true);
    assert.equal(occupiesCapacity(booking({ status: 'cancelled' })), false);
    assert.equal(occupiesCapacity(booking({ status: 'shipped' })), false);
    assert.throws(() => booking({ status: 'nonsense' }), RangeError);
  });

  it('transition immutably along the lifecycle', () => {
    const held = booking();
    const confirmed = transitionBooking(held, 'confirmed');
    assert.equal(held.status, 'held', 'original untouched');
    assert.equal(confirmed.status, 'confirmed');
    assert.ok(Object.isFrozen(confirmed));
    assert.equal(transitionBooking(confirmed, 'shipped').status, 'shipped');
    assert.equal(transitionBooking(held, 'cancelled').status, 'cancelled');
    assert.throws(() => transitionBooking(held, 'shipped'), RangeError, 'held -> shipped');
    assert.throws(() => transitionBooking(confirmed, 'held'), RangeError, 'confirmed -> held');
    assert.throws(
      () => transitionBooking(transitionBooking(held, 'cancelled'), 'confirmed'),
      RangeError,
      'cancelled is terminal',
    );
  });
});

import { describe, it, assert } from '../tests/helpers.js';

import { createBoard } from '../src/domain/board.js';
import { createBoard as boardFromIndex, DEFAULT_PLANNING_HORIZON_DAYS } from '../src/index.js';

function board(overrides = {}) {
  return createBoard({ startUtc: '2030-01-01T00:00:00Z', ...overrides });
}

function seed(b) {
  b.addVessel({ id: 'v-1', name: 'Harbor Skiff', capacityKg: 1000 });
  b.addVessel({ id: 'v-2', name: 'Kelpline', capacityKg: 2000 });
  b.addSailing({
    id: 's-1',
    vesselId: 'v-1',
    routeId: 'route-a',
    originPortId: 'p-north',
    destinationPortId: 'p-south',
    departsAtUtc: '2030-01-03T08:00:00Z',
    arrivesAtUtc: '2030-01-03T12:00:00Z',
  });
  b.addSailing({
    id: 's-2',
    vesselId: 'v-2',
    routeId: 'route-a',
    originPortId: 'p-north',
    destinationPortId: 'p-south',
    departsAtUtc: '2030-01-04T08:00:00Z',
    arrivesAtUtc: '2030-01-04T15:00:00Z',
  });
  b.addConsignment({
    id: 'c-1',
    massKg: 600,
    originPortId: 'p-north',
    destinationPortId: 'p-south',
  });
  b.addConsignment({
    id: 'c-2',
    massKg: 500,
    originPortId: 'p-north',
    destinationPortId: 'p-south',
  });
}

const bookedAt = '2030-01-01T01:00:00Z';

describe('planning board', () => {
  it('starts empty with a 21-day horizon', () => {
    const b = board();
    assert.equal(b.horizon.days, DEFAULT_PLANNING_HORIZON_DAYS);
    assert.equal(b.vessels.size, 0);
    assert.equal(b.sailings.size, 0);
    assert.equal(b.consignments.size, 0);
    assert.equal(b.bookings.size, 0);
    assert.equal(boardFromIndex({ startUtc: '2030-01-01T00:00:00Z' }).horizon.days, 21);
  });

  it('rejects sailings departing outside the horizon', () => {
    const b = board({ horizonDays: 1 });
    b.addVessel({ id: 'v-1', capacityKg: 100 });
    assert.throws(
      () =>
        b.addSailing({
          id: 's-late',
          vesselId: 'v-1',
          routeId: 'r',
          originPortId: 'p-a',
          destinationPortId: 'p-b',
          departsAtUtc: '2030-01-02T00:00:00Z',
          arrivesAtUtc: '2030-01-02T01:00:00Z',
        }),
      RangeError,
    );
  });

  it('rejects duplicate ids and unknown references', () => {
    const b = board();
    seed(b);
    assert.throws(() => b.addVessel({ id: 'v-1', capacityKg: 1 }), RangeError, 'duplicate vessel');
    assert.throws(
      () =>
        b.addSailing({
          id: 's-x',
          vesselId: 'nope',
          routeId: 'r',
          originPortId: 'p-north',
          destinationPortId: 'p-south',
          departsAtUtc: '2030-01-03T00:00:00Z',
          arrivesAtUtc: '2030-01-03T01:00:00Z',
        }),
      RangeError,
      'unknown vessel',
    );
    assert.throws(
      () => b.book({ id: 'b-x', consignmentId: 'c-1', sailingId: 'nope', bookedAtUtc: bookedAt }),
      RangeError,
      'unknown sailing',
    );
  });

  it('reserves capacity and rejects overloads', () => {
    const b = board();
    seed(b);
    b.book({ id: 'b-1', consignmentId: 'c-1', sailingId: 's-1', bookedAtUtc: bookedAt });
    assert.equal(b.loadFor('s-1'), 600);
    assert.deepEqual(b.capacityFor('s-1'), {
      remainingKg: 400,
      utilisation: 0.6,
      overloaded: false,
    });
    // c-2 (500 kg) would take s-2's 1000 kg hull to 1100 kg.
    assert.throws(
      () => b.book({ id: 'b-2', consignmentId: 'c-2', sailingId: 's-1', bookedAtUtc: bookedAt }),
      RangeError,
      'overload',
    );
    // The larger vessel s-2 has room.
    b.book({ id: 'b-2', consignmentId: 'c-2', sailingId: 's-2', bookedAtUtc: bookedAt });
    assert.equal(b.loadFor('s-2'), 500);
  });

  it('frees capacity when a booking is cancelled', () => {
    const b = board();
    seed(b);
    b.book({ id: 'b-1', consignmentId: 'c-1', sailingId: 's-1', bookedAtUtc: bookedAt });
    b.book({ id: 'b-fill', consignmentId: 'c-2', sailingId: 's-1', bookedAtUtc: bookedAt });
    assert.equal(b.loadFor('s-1'), 1100 > 1000 ? 600 : 0);
    assert.throws(
      () =>
        b.book({
          id: 'b-extra',
          consignmentId: 'c-2',
          sailingId: 's-1',
          bookedAtUtc: bookedAt,
        }),
      RangeError,
      'no room',
    );
    b.changeBookingStatus('b-1', 'cancelled');
    assert.equal(b.loadFor('s-1'), 500);
    b.book({ id: 'b-3', consignmentId: 'c-1', sailingId: 's-1', bookedAtUtc: bookedAt });
    assert.equal(b.loadFor('s-1'), 1100 - 100, 'exactly full');
    assert.equal(b.capacityFor('s-1').remainingKg, 0);
  });

  it('re-checks capacity when reviving a cancelled booking', () => {
    const b = board();
    b.addVessel({ id: 'v-1', capacityKg: 1000 });
    b.addSailing({
      id: 's-1',
      vesselId: 'v-1',
      routeId: 'route-a',
      originPortId: 'p-north',
      destinationPortId: 'p-south',
      departsAtUtc: '2030-01-03T08:00:00Z',
      arrivesAtUtc: '2030-01-03T12:00:00Z',
    });
    b.addConsignment({ id: 'c-a', massKg: 600, originPortId: 'p-north', destinationPortId: 'p-south' });
    b.addConsignment({ id: 'c-b', massKg: 600, originPortId: 'p-north', destinationPortId: 'p-south' });
    b.book({ id: 'b-a', consignmentId: 'c-a', sailingId: 's-1', bookedAtUtc: bookedAt });
    b.changeBookingStatus('b-a', 'cancelled');
    // A different consignment takes the freed room.
    const otherHold = b.book({
      id: 'b-b',
      consignmentId: 'c-b',
      sailingId: 's-1',
      bookedAtUtc: bookedAt,
      status: 'held',
    });
    b.changeBookingStatus(otherHold.id, 'cancelled');
    b.changeBookingStatus('b-b', 'held');
    assert.throws(() => b.changeBookingStatus('b-a', 'confirmed'), RangeError, 'blocked by b-b');
    b.changeBookingStatus('b-b', 'cancelled');
    b.changeBookingStatus('b-a', 'confirmed');
    assert.equal(b.loadFor('s-1'), 600);
    assert.throws(() => b.changeBookingStatus('missing', 'confirmed'), RangeError);
  });

  it('keeps bookings, sailings, vessels and consignments distinct', () => {
    const b = board();
    seed(b);
    const bk = b.book({ id: 'b-1', consignmentId: 'c-1', sailingId: 's-1', bookedAtUtc: bookedAt });
    assert.equal(b.consignments.has('b-1'), false);
    assert.equal(b.sailings.has('b-1'), false);
    assert.equal(b.vessels.has('b-1'), false);
    assert.equal(bk.consignmentId, 'c-1');
    assert.equal(bk.sailingId, 's-1');
    assert.equal(bk.vesselId, undefined, 'bookings do not name vessels directly');
    assert.equal(b.sailings.get('s-1').vesselId, 'v-1');
  });

  it('rejects bookings whose consignment does not match the sailing route', () => {
    const b = board();
    seed(b);
    b.addConsignment({
      id: 'c-rev',
      massKg: 10,
      originPortId: 'p-south',
      destinationPortId: 'p-north',
    });
    assert.throws(
      () => b.book({ id: 'b-x', consignmentId: 'c-rev', sailingId: 's-1', bookedAtUtc: bookedAt }),
      RangeError,
    );
  });
});

