/**
 * The planning board.
 *
 * A board is an in-memory registry of vessels, sailings, consignments and
 * bookings for one planning horizon. It is deliberately small and
 * synchronous: the cooperative runs Harbor Dispatch offline, so everything is
 * plain data passed in by the caller.
 */

import { assertOpaqueId } from './ids.js';
import { sumKilograms, capacityReport } from './capacity.js';
import {
  planningHorizon,
  isWithinHorizon,
  DEFAULT_PLANNING_HORIZON_DAYS,
} from '../ports.js';
import { createVessel } from './vessels.js';
import { createSailing } from './sailings.js';
import { createConsignment } from './consignments.js';
import { createBooking, occupiesCapacity, transitionBooking } from './bookings.js';

/**
 * @typedef {object} Board
 */

/**
 * Create an empty planning board anchored at a caller-supplied UTC start.
 *
 * @param {{ startUtc: string, horizonDays?: number }} spec
 * @returns {Readonly<Board> & { horizon: Readonly<{ startMs: number, endMs: number, days: number }> }}
 */
export function createBoard(spec) {
  if (spec === null || typeof spec !== 'object') {
    throw new TypeError('board spec must be an object');
  }
  const horizon = planningHorizon(
    spec.startUtc,
    spec.horizonDays ?? DEFAULT_PLANNING_HORIZON_DAYS,
  );
  const board = {
    horizon,
    vessels: new Map(),
    sailings: new Map(),
    consignments: new Map(),
    bookings: new Map(),
  };
  return Object.freeze({
    horizon: board.horizon,
    vessels: board.vessels,
    sailings: board.sailings,
    consignments: board.consignments,
    bookings: board.bookings,
    // The methods below are plain closures over the same maps; freezing the
    // wrapper keeps callers from swapping the maps out from under us.
    addVessel: (vesselSpec) => addVessel(board, vesselSpec),
    addSailing: (sailingSpec) => addSailing(board, sailingSpec),
    addConsignment: (consignmentSpec) => addConsignment(board, consignmentSpec),
    book: (bookingSpec) => book(board, bookingSpec),
    changeBookingStatus: (bookingId, status) => changeBookingStatus(board, bookingId, status),
    loadFor: (sailingId) => loadFor(board, sailingId),
    capacityFor: (sailingId) => capacityFor(board, sailingId),
  });
}

/**
 * @param {Board} board
 * @param {any} spec
 */
function addVessel(board, spec) {
  const vessel = createVessel(spec);
  if (board.vessels.has(vessel.id)) {
    throw new RangeError(`duplicate vessel id: ${vessel.id}`);
  }
  board.vessels.set(vessel.id, vessel);
  return vessel;
}

