import { describe, it, assert } from '../tests/helpers.js';

import * as api from '../src/index.js';

describe('smoke', () => {
  it('exposes the public surface from the index', () => {
    for (const name of [
      'DEFAULT_PLANNING_HORIZON_DAYS',
      'definePort',
      'planningHorizon',
      'instant',
      'createVessel',
      'createSailing',
      'createConsignment',
      'createBooking',
      'transitionBooking',
      'createBoard',
    ]) {
      assert.equal(typeof api[name] !== 'undefined', true, `missing export ${name}`);
    }
  });

  it('plans a tiny cooperative day end to end', () => {
    const board = api.createBoard({ startUtc: '2030-01-01T00:00:00Z' });
    board.addVessel({ id: 'v-1', capacityKg: 1200 });
    board.addSailing({
      id: 's-1',
      vesselId: 'v-1',
      routeId: 'r-1',
      originPortId: 'p-a',
      destinationPortId: 'p-b',
      departsAtUtc: '2030-01-05T06:00:00Z',
      arrivesAtUtc: '2030-01-05T11:00:00Z',
    });
    board.addConsignment({ id: 'c-1', massKg: 500, originPortId: 'p-a', destinationPortId: 'p-b' });
    const booking = board.book({
      id: 'b-1',
      consignmentId: 'c-1',
      sailingId: 's-1',
      bookedAtUtc: '2030-01-02T08:30:00Z',
    });
    assert.equal(booking.status, 'held');
    assert.equal(booking.massKg, 500);
    assert.equal(board.capacityFor('s-1').remainingKg, 700);
    assert.equal(board.changeBookingStatus('b-1', 'confirmed').status, 'confirmed');
  });
});

// Aggregate import of every suite.
//
