function book(board, spec) {
  const sailing = board.sailings.get(spec?.sailingId);
  if (!sailing) {
    throw new RangeError(`unknown sailing: ${String(spec?.sailingId)}`);
  }
  const consignment = board.consignments.get(spec?.consignmentId);
  if (!consignment) {
    throw new RangeError(`unknown consignment: ${String(spec?.consignmentId)}`);
  }
  const bookingId = assertOpaqueId('booking id', spec?.id);
  if (board.bookings.has(bookingId)) {
    throw new RangeError(`duplicate booking id: ${bookingId}`);
  }
  const booking = createBooking({
