/**
 * Opaque identifiers.
 *
 * Every identifier in Harbor Dispatch is an opaque string. Callers may have
 * generated them from a counter, a UUID, or anything else, but the domain
 * only ever compares them for equality — it never slices, parses, sorts by
 * meaning, or infers a type from their shape.
 */

/**
 * @param {string} label what kind of id is being checked (for messages only)
 * @param {unknown} value
 * @returns {string}
 */
export function assertOpaqueId(label, value) {
  if (typeof value !== 'string') {
    throw new TypeError(`${label} must be an opaque string`);
  }
  if (value.length === 0) {
    throw new RangeError(`${label} must not be empty`);
  }
  // Control characters would break logs and exports; that is a formatting
  // concern, not a parsing one.
  if (/[\u0000-\u001f\u007f]/.test(value)) {
    throw new RangeError(`${label} must not contain control characters`);
  }
  return value;
}

/**
 * Compare two opaque ids for equality.
 *
 * @param {string} a
 * @param {string} b
 * @returns {boolean}
 */
export function sameId(a, b) {
  return a === b;
