/**
 * The vessel registry.
 *
 * The registry is the cooperative's authoritative record of hulls. On top of
 * the plain vessel record it adds three operational facts:
 *
 *  1. **Compartments** — a hull's cargo capacity is split into named holds,
 *     each with an integer-kilogram capacity. The sum of compartment
 *     capacities must equal the vessel's `capacityKg`, so a hull's capacity is
 *     never silently over- or under-stated.
 *  2. **Inspection state** — a hull is `cleared`, `due` for inspection, or
 *     `grounded`. Only `cleared` hulls may be scheduled or carry cargo.
 *  3. **Incompatible cargo classes** — some cargo classes must never share a
 *     sailing (for example, a class that emits heat next to one that is
 *     chilled). Conflicts are symmetric and declared per vessel.
 *
 * Existing invariants are preserved: ids are opaque, masses are integer
 * kilograms, and every timestamp is a caller-supplied UTC value.
 */

import { assertOpaqueId } from './ids.js';
import { assertKilograms, assertPositiveKilograms, sumKilograms } from './capacity.js';
import { instant } from './time.js';
import { createVessel } from './vessels.js';

/* -------------------------------------------------------------------------
 * Cargo classes
 * ---------------------------------------------------------------------- */

/**
 * Cargo classes are opaque tokens. The domain never infers behaviour from
 * their text; it only compares them for equality.
 *
 * @typedef {string} CargoClass
 */

/**
 * @param {string} label
 * @param {unknown} value
 * @returns {CargoClass}
 */
export function assertCargoClass(label, value) {
  return assertOpaqueId(label, value);
}

/* -------------------------------------------------------------------------
 * Compartments
 * ---------------------------------------------------------------------- */

/**
 * @typedef {object} Compartment
 * @property {string} id opaque compartment id, unique within its vessel
 * @property {string} name human label
 * @property {number} capacityKg integer kilograms
 */

/**
 * @param {{ id: string, name?: string, capacityKg: number }} spec
 * @returns {Readonly<Compartment>}
 */
export function createCompartment(spec) {
  if (spec === null || typeof spec !== 'object') {
    throw new TypeError('compartment spec must be an object');
  }
  const id = assertOpaqueId('compartment id', spec.id);
  const capacityKg = assertPositiveKilograms('compartment capacityKg', spec.capacityKg);
  const name = typeof spec.name === 'string' && spec.name.length > 0 ? spec.name : id;
  return Object.freeze({ id, name, capacityKg });
}

/**
 * Build a compartment list, requiring unique ids.
 *
 * @param {Array<{ id: string, name?: string, capacityKg: number }>} specs
 * @returns {ReadonlyArray<Readonly<Compartment>>}
 */
export function createCompartments(specs) {
  if (!Array.isArray(specs) || specs.length === 0) {
    throw new RangeError('a vessel needs at least one compartment');
  }
  const seen = new Set();
  const compartments = specs.map((spec) => {
    const compartment = createCompartment(spec);
    if (seen.has(compartment.id)) {
      throw new RangeError(`duplicate compartment id: ${compartment.id}`);
    }
    seen.add(compartment.id);
    return compartment;
  });
  return Object.freeze(compartments);
}

/* -------------------------------------------------------------------------
 * Inspection state
 * ---------------------------------------------------------------------- */

/** @typedef {'cleared' | 'due' | 'grounded'} InspectionStatus */

const INSPECTION_STATUSES = new Set(['cleared', 'due', 'grounded']);

/**
 * @param {unknown} status
 * @returns {InspectionStatus}
 */
export function assertInspectionStatus(status) {
  if (typeof status !== 'string' || !INSPECTION_STATUSES.has(status)) {
    throw new RangeError(
      `inspection status must be one of ${[...INSPECTION_STATUSES].join(', ')}; got ${String(status)}`,
    );
  }
  return /** @type {InspectionStatus} */ (status);
}

/**
 * @typedef {object} InspectionState
 * @property {InspectionStatus} status
 * @property {Readonly<import('./time.js').Instant>} recordedAt
 * @property {string|null} note
 * @property {Readonly<import('./time.js').Instant>|null} dueBy
 */

/**
 * @param {{
 *   status: InspectionStatus,
 *   recordedAtUtc: string,
 *   note?: string,
 *   dueByUtc?: string,
 * }} spec
 * @returns {Readonly<InspectionState>}
 */
export function createInspectionState(spec) {
  if (spec === null || typeof spec !== 'object') {
    throw new TypeError('inspection state spec must be an object');
  }
  const status = assertInspectionStatus(spec.status);
  const recordedAt = instant(spec.recordedAtUtc);
  const dueBy = spec.dueByUtc === undefined ? null : instant(spec.dueByUtc);
  if (dueBy !== null && dueBy.ms <= recordedAt.ms) {
    throw new RangeError('inspection dueByUtc must be later than recordedAtUtc');
  }
  if (spec.note !== undefined && typeof spec.note !== 'string') {
    throw new TypeError('inspection note must be a string');
  }
  const note = spec.note === undefined || spec.note.length === 0 ? null : spec.note;
  return Object.freeze({ status, recordedAt, note, dueBy });
}

/**
 * Whether a hull in this inspection state may be scheduled or loaded.
 *
 * @param {Readonly<InspectionState>} state
 * @returns {boolean}
 */
export function isClearedForService(state) {
  return state.status === 'cleared';
}

/* -------------------------------------------------------------------------
 * Incompatible cargo classes
 * ---------------------------------------------------------------------- */

/**
 * Normalise a set of cargo classes into a sorted array of unique tokens.
 * Sorting is by string order purely so output is stable; it confers no
 * meaning on the tokens themselves.
 *
 * @param {Iterable<string>} classes
 * @returns {ReadonlyArray<CargoClass>}
 */
export function normaliseCargoClasses(classes) {
  if (classes === null || typeof classes !== 'object') {
    throw new TypeError('cargo classes must be an iterable of class tokens');
  }
  const set = new Set();
  for (const cargoClass of classes) {
    set.add(assertCargoClass('cargo class', cargoClass));
  }
  return Object.freeze([...set].sort());
}

/**
 * @typedef {object} Incompatibility
 * @property {CargoClass} a
 * @property {CargoClass} b
 */

/**
 * Build the incompatibility table. Each entry `[a, b]` means classes `a` and
 * `b` may not travel together on the same sailing. Conflicts are symmetric,
 * so `[a, b]` also forbids `[b, a]`. Self-conflicts are meaningless here
 * (two consignments of the same class are always compatible) and are rejected
 * rather than silently dropped.
 *
 * @param {Iterable<readonly [string, string]>} pairs
 * @returns {ReadonlyArray<Readonly<Incompatibility>>}
 */
export function createIncompatibilities(pairs) {
  if (pairs === null || typeof pairs !== 'object') {
    throw new TypeError('incompatibilities must be an iterable of [a, b] pairs');
  }
  const seen = new Set();
  const result = [];
  for (const pair of pairs) {
    if (!Array.isArray(pair) || pair.length !== 2) {
      throw new TypeError('each incompatibility must be a [classA, classB] pair');
    }
    const a = assertCargoClass('incompatible cargo class', pair[0]);
    const b = assertCargoClass('incompatible cargo class', pair[1]);
    if (a === b) {
      throw new RangeError(`cargo class ${a} cannot be declared incompatible with itself`);
    }
    const key = a < b ? `${a}\u0000${b}` : `${b}\u0000${a}`;
    if (seen.has(key)) continue;
    seen.add(key);
    result.push(Object.freeze({ a, b }));
  }
  return Object.freeze(result);
}

/**
 * Whether two cargo classes conflict under a given table.
 *
 * @param {ReadonlyArray<Readonly<Incompatibility>>} incompatibilities
 * @param {CargoClass} a
 * @param {CargoClass} b
 * @returns {boolean}
 */
export function classesConflict(incompatibilities, a, b) {
  if (a === b) return false;
  return incompatibilities.some(
    (entry) => (entry.a === a && entry.b === b) || (entry.a === b && entry.b === a),
  );
}

/**
 * Find the first conflicting pair between an already-loaded set of classes
 * and a candidate class.
 *
 * @param {ReadonlyArray<Readonly<Incompatibility>>} incompatibilities
 * @param {Iterable<CargoClass>} present
 * @param {CargoClass} candidate
 * @returns {Incompatibility|null}
 */
export function firstConflict(incompatibilities, present, candidate) {
  for (const existing of present) {
    if (classesConflict(incompatibilities, existing, candidate)) {
      return Object.freeze(
        existing < candidate ? { a: existing, b: candidate } : { a: candidate, b: existing },
      );
    }
  }
  return null;
}

/* -------------------------------------------------------------------------
 * Registered vessels
 * ---------------------------------------------------------------------- */

/**
 * @typedef {object} RegisteredVessel
 * @property {string} id
 * @property {string} name
 * @property {number} capacityKg
 * @property {ReadonlyArray<Readonly<Compartment>>} compartments
 * @property {Readonly<InspectionState>} inspection
 * @property {ReadonlyArray<Readonly<Incompatibility>>} incompatibilities
 * @property {ReadonlyArray<CargoClass>} acceptedCargoClasses
 */

/**
 * Register a vessel with its compartments, inspection state and declared
 * cargo incompatibilities.
 *
 * @param {{
 *   id: string,
 *   name?: string,
 *   capacityKg?: number,
 *   compartments: Array<{ id: string, name?: string, capacityKg: number }>,
 *   inspection: { status: InspectionStatus, recordedAtUtc: string, note?: string, dueByUtc?: string },
 *   incompatibilities?: Iterable<readonly [string, string]>,
 *   acceptedCargoClasses?: Iterable<string>,
 * }} spec
 * @returns {Readonly<RegisteredVessel>}
 */
export function registerVessel(spec) {
  if (spec === null || typeof spec !== 'object') {
    throw new TypeError('vessel registration spec must be an object');
  }
  if (spec.inspection === undefined) {
    throw new TypeError('vessel registration requires an inspection state');
  }
  const compartments = createCompartments(spec.compartments);
  const compartmentTotal = sumKilograms(compartments.map((c) => c.capacityKg));

  // The hull capacity is the sum of its compartments. If a capacity is also
  // supplied it must agree exactly — the two must never disagree.
  let capacityKg;
  if (spec.capacityKg === undefined) {
    capacityKg = compartmentTotal;
  } else {
    capacityKg = assertPositiveKilograms('vessel capacityKg', spec.capacityKg);
    if (capacityKg !== compartmentTotal) {
      throw new RangeError(
        `vessel capacityKg (${capacityKg}) must equal the sum of compartment capacities (${compartmentTotal})`,
      );
    }
  }

  const inspection = createInspectionState(spec.inspection);
  const incompatibilities = createIncompatibilities(spec.incompatibilities ?? []);
  const acceptedCargoClasses = normaliseCargoClasses(spec.acceptedCargoClasses ?? []);

  // Every class named in the incompatibility table must be a class the hull
  // accepts, otherwise the declaration is meaningless (or a typo).
  for (const entry of incompatibilities) {
    for (const cargoClass of [entry.a, entry.b]) {
      if (
        acceptedCargoClasses.length > 0 &&
        !acceptedCargoClasses.includes(cargoClass)
      ) {
        throw new RangeError(
          `incompatibility names cargo class ${cargoClass}, which the vessel does not accept`,
        );
      }
    }
  }

  const vessel = createVessel({ id: spec.id, name: spec.name, capacityKg });

  return Object.freeze({
    ...vessel,
    compartments,
    inspection,
    incompatibilities,
    acceptedCargoClasses,
  });
}

/**
 * Look up a compartment on a registered vessel.
 *
 * @param {Readonly<RegisteredVessel>} vessel
 * @param {string} compartmentId
 * @returns {Readonly<Compartment>}
 */
export function requireCompartment(vessel, compartmentId) {
  const compartment = vessel.compartments.find((c) => c.id === compartmentId);
  if (!compartment) {
    throw new RangeError(`unknown compartment ${String(compartmentId)} on vessel ${vessel.id}`);
  }
  return compartment;
}

/* -------------------------------------------------------------------------
 * The registry
 * ---------------------------------------------------------------------- */

/**
 * Create a vessel registry. It exposes the same lookups the planning board
 * relies on, so registered vessels can be handed straight to the board.
 *
 * @returns {Readonly<object>}
 */
export function createVesselRegistry() {
  const vessels = new Map();

  const api = {
    vessels,

    /**
     * Register a vessel.
     *
     * @param {Parameters<typeof registerVessel>[0]} spec
     * @returns {Readonly<RegisteredVessel>}
     */
    register(spec) {
      const vessel = registerVessel(spec);
      if (vessels.has(vessel.id)) {
        throw new RangeError(`duplicate vessel id: ${vessel.id}`);
      }
      vessels.set(vessel.id, vessel);
      return vessel;
    },

    /**
     * @param {string} vesselId
     * @returns {Readonly<RegisteredVessel>|undefined}
     */
    get(vesselId) {
      return vessels.get(vesselId);
    },

    /**
     * @param {string} vesselId
     * @returns {Readonly<RegisteredVessel>}
     */
    require(vesselId) {
      const vessel = vessels.get(vesselId);
      if (!vessel) {
        throw new RangeError(`unknown vessel: ${String(vesselId)}`);
      }
      return vessel;
    },

    /**
     * Replace a hull's inspection state. Returns the updated vessel; the
     * previous record is left untouched.
     *
     * @param {string} vesselId
     * @param {Parameters<typeof createInspectionState>[0]} inspectionSpec
     * @returns {Readonly<RegisteredVessel>}
     */
    setInspection(vesselId, inspectionSpec) {
      const vessel = api.require(vesselId);
      const inspection = createInspectionState(inspectionSpec);
      const updated = Object.freeze({ ...vessel, inspection });
      vessels.set(vesselId, updated);
      return updated;
    },

    /**
     * Whether a hull is cleared to be scheduled or loaded.
     *
     * @param {string} vesselId
     * @returns {boolean}
     */
    isCleared(vesselId) {
      return isClearedForService(api.require(vesselId).inspection);
    },
  };

  return Object.freeze(api);
}

/**
 * Assert that a hull may be scheduled or carry cargo, throwing if not.
 *
 * @param {Readonly<RegisteredVessel>} vessel
 * @returns {void}
 */
export function assertClearedForService(vessel) {
  if (!isClearedForService(vessel.inspection)) {
    throw new RangeError(
      `vessel ${vessel.id} is not cleared for service (inspection: ${vessel.inspection.status})`,
    );
  }
}

/* -------------------------------------------------------------------------
 * Loading checks
 * ---------------------------------------------------------------------- */

/**
 * Plan a set of cargo allocations onto a vessel, checking every boundary:
 *
 *  - the hull must be cleared for service;
 *  - each allocation's compartment must exist;
 *  - no compartment may exceed its capacity;
 *  - the hull total may not exceed `capacityKg` (it cannot, if compartments
 *    are consistent, but the check makes the invariant explicit);
 *  - no two cargo classes may conflict.
 *
 * Allocations are `{ compartmentId, cargoClass, massKg }`. The result is a
 * report, not a mutation — the caller decides whether to persist it.
 *
 * @param {Readonly<RegisteredVessel>} vessel
 * @param {ReadonlyArray<{ compartmentId: string, cargoClass: string, massKg: number }>} allocations
 * @returns {Readonly<{ ok: boolean, vesselId: string, totalKg: number, byCompartment: ReadonlyArray<{ compartmentId: string, loadKg: number, remainingKg: number }> }>}
 */
export function planLoading(vessel, allocations) {
  if (!Array.isArray(allocations)) {
    throw new TypeError('allocations must be an array');
  }
  assertClearedForService(vessel);

  /** @type {Map<string, number>} */
  const loads = new Map(vessel.compartments.map((c) => [c.id, 0]));
  /** @type {string[]} */
  const classes = [];

  for (const allocation of allocations) {
    if (allocation === null || typeof allocation !== 'object') {
      throw new TypeError('each allocation must be an object');
    }
    const compartment = requireCompartment(vessel, allocation.compartmentId);
    const massKg = assertKilograms('allocation massKg', allocation.massKg);
    if (massKg === 0) {
      throw new RangeError('allocation massKg must be greater than zero');
    }
    const cargoClass = assertCargoClass('allocation cargoClass', allocation.cargoClass);

    if (
      vessel.acceptedCargoClasses.length > 0 &&
      !vessel.acceptedCargoClasses.includes(cargoClass)
    ) {
      throw new RangeError(`vessel ${vessel.id} does not accept cargo class ${cargoClass}`);
    }

    const conflict = firstConflict(vessel.incompatibilities, classes, cargoClass);
    if (conflict) {
      throw new RangeError(
        `cargo class ${conflict.b} cannot share vessel ${vessel.id} with class ${conflict.a}`,
      );
    }

    const nextLoad = /** @type {number} */ (loads.get(compartment.id)) + massKg;
    if (nextLoad > compartment.capacityKg) {
      throw new RangeError(
        `compartment ${compartment.id} overloaded: ${nextLoad} kg > ${compartment.capacityKg} kg`,
      );
    }
    loads.set(compartment.id, nextLoad);
    if (!classes.includes(cargoClass)) classes.push(cargoClass);
  }

  const totalKg = sumKilograms([...loads.values()]);
  const byCompartment = vessel.compartments.map((c) => {
    const loadKg = /** @type {number} */ (loads.get(c.id));
    return Object.freeze({
      compartmentId: c.id,
      loadKg,
      remainingKg: c.capacityKg - loadKg,
    });
  });

  return Object.freeze({
    ok: true,
    vesselId: vessel.id,
    totalKg,
    byCompartment: Object.freeze(byCompartment),
  });
}

