import { describe, it, assert } from '../tests/helpers.js';

import {
  assertCargoClass,
  createCompartments,
  assertInspectionStatus,
  createInspectionState,
  isClearedForService,
  createIncompatibilities,
  normaliseCargoClasses,
  classesConflict,
  firstConflict,
  registerVessel,
  requireCompartment,
  createVesselRegistry,
  assertClearedForService,
  planLoading,
} from '../src/domain/vessel-registry.js';
import { createSailing } from '../src/domain/sailings.js';
import { createBoard } from '../src/domain/board.js';

/* ---------------------------------------------------------------------- */

const compartments = [
  { id: 'c-fore', name: 'Fore hold', capacityKg: 400 },
  { id: 'c-aft', name: 'Aft hold', capacityKg: 600 },
];

function vesselSpec(overrides = {}) {
  return {
    id: 'v-1',
    name: 'Harbor Skiff',
    compartments,
    inspection: { status: 'cleared', recordedAtUtc: '2030-01-01T00:00:00Z' },
    incompatibilities: [
      ['class-heat', 'class-chilled'],
    ],
    acceptedCargoClasses: ['class-heat', 'class-chilled', 'class-dry'],
    ...overrides,
  };
}

describe('vessel registry: cargo classes', () => {
  it('treats cargo classes as opaque tokens', () => {
    assert.equal(assertCargoClass('cargo class', 'class-heat'), 'class-heat');
    assert.throws(() => assertCargoClass('cargo class', ''), RangeError, 'empty');
    assert.throws(() => assertCargoClass('cargo class', 7), TypeError, 'non-string');
  });

  it('normalises to a unique, stable list', () => {
    assert.deepEqual(normaliseCargoClasses(['b', 'a', 'b']), ['a', 'b']);
    assert.deepEqual(normaliseCargoClasses([]), []);
    assert.throws(() => normaliseCargoClasses(null), TypeError);
  });
});

describe('vessel registry: compartments', () => {
  it('builds compartments with positive integer kilogram capacity', () => {
    const list = createCompartments(compartments);
    assert.equal(list.length, 2);
    assert.equal(list[0].capacityKg, 400);
    assert.ok(Object.isFrozen(list));
    assert.ok(Object.isFrozen(list[0]));
  });

  it('requires at least one compartment', () => {
    assert.throws(() => createCompartments([]), RangeError);
    assert.throws(() => createCompartments('nope'), RangeError);
  });

  it('rejects zero, fractional and duplicate compartments', () => {
    assert.throws(() => createCompartments([{ id: 'a', capacityKg: 0 }]), RangeError);
    assert.throws(() => createCompartments([{ id: 'a', capacityKg: 1.5 }]), TypeError);
    assert.throws(
      () =>
        createCompartments([
          { id: 'a', capacityKg: 10 },
          { id: 'a', capacityKg: 20 },
        ]),
      RangeError,
      'duplicate compartment id',
    );
  });

  it('accepts a one-kilogram compartment as the lower boundary', () => {
    assert.equal(createCompartments([{ id: 'tiny', capacityKg: 1 }])[0].capacityKg, 1);
  });
});

describe('vessel registry: inspection state', () => {
  it('accepts exactly three statuses', () => {
    for (const status of ['cleared', 'due', 'grounded']) {
      assert.equal(assertInspectionStatus(status), status);
    }
    assert.throws(() => assertInspectionStatus('unknown'), RangeError);
    assert.throws(() => assertInspectionStatus('CLEARED'), RangeError, 'case sensitive');
    assert.throws(() => assertInspectionStatus(undefined), RangeError);
  });

  it('records a caller-supplied UTC time and optional note and due date', () => {
    const state = createInspectionState({
      status: 'due',
      recordedAtUtc: '2030-01-02T08:00:00Z',
      note: 'hull survey booked',
      dueByUtc: '2030-01-20T08:00:00Z',
    });
    assert.equal(state.status, 'due');
    assert.equal(state.recordedAt.utc, '2030-01-02T08:00:00.000Z');
    assert.equal(state.dueBy.utc, '2030-01-20T08:00:00.000Z');
    assert.equal(state.note, 'hull survey booked');
    assert.ok(Object.isFrozen(state));
  });

  it('defaults note and dueBy to null', () => {
    const state = createInspectionState({
      status: 'cleared',
      recordedAtUtc: '2030-01-02T08:00:00Z',
    });
    assert.equal(state.note, null);
    assert.equal(state.dueBy, null);
  });

  it('rejects a due date that is not strictly later than the record time', () => {
    assert.throws(
      () =>
        createInspectionState({
          status: 'due',
          recordedAtUtc: '2030-01-02T08:00:00Z',
          dueByUtc: '2030-01-02T08:00:00Z',
        }),
      RangeError,
      'equal timestamps',
    );
    assert.throws(
      () =>
        createInspectionState({
          status: 'due',
          recordedAtUtc: '2030-01-02T08:00:00Z',
          dueByUtc: '2030-01-01T08:00:00Z',
        }),
      RangeError,
      'earlier',
    );
  });

  it('rejects non-UTC timestamps', () => {
    assert.throws(
      () => createInspectionState({ status: 'cleared', recordedAtUtc: '2030-01-02T08:00:00+01:00' }),
      RangeError,
    );
  });

  it('only cleared hulls are cleared for service', () => {
    const make = (status) =>
      createInspectionState({ status, recordedAtUtc: '2030-01-02T08:00:00Z' });
    assert.equal(isClearedForService(make('cleared')), true);
    assert.equal(isClearedForService(make('due')), false);
    assert.equal(isClearedForService(make('grounded')), false);
  });
});

describe('vessel registry: incompatible cargo classes', () => {
  it('builds a symmetric table', () => {
    const table = createIncompatibilities([['class-heat', 'class-chilled']]);
    assert.equal(classesConflict(table, 'class-heat', 'class-chilled'), true);
    assert.equal(classesConflict(table, 'class-chilled', 'class-heat'), true);
    assert.equal(classesConflict(table, 'class-heat', 'class-dry'), false);
  });

  it('never reports a class as conflicting with itself', () => {
    const table = createIncompatibilities([['class-heat', 'class-chilled']]);
    assert.equal(classesConflict(table, 'class-heat', 'class-heat'), false);
  });

  it('rejects self-incompatibility and malformed pairs', () => {
    assert.throws(() => createIncompatibilities([['class-heat', 'class-heat']]), RangeError);
    assert.throws(() => createIncompatibilities([['class-heat']]), TypeError);
    assert.throws(() => createIncompatibilities(['class-heat']), TypeError);
    assert.throws(() => createIncompatibilities(null), TypeError);
  });

  it('de-duplicates reversed declarations', () => {
    const table = createIncompatibilities([
      ['class-heat', 'class-chilled'],
      ['class-chilled', 'class-heat'],
    ]);
    assert.equal(table.length, 1);
  });

  it('reports the first conflict against already-loaded classes', () => {
    const table = createIncompatibilities([['class-heat', 'class-chilled']]);
    assert.equal(firstConflict(table, [], 'class-heat'), null);
    assert.equal(firstConflict(table, ['class-dry'], 'class-heat'), null);
    const conflict = firstConflict(table, ['class-chilled', 'class-dry'], 'class-heat');
    assert.deepEqual(conflict, { a: 'class-chilled', b: 'class-heat' });
    assert.ok(Object.isFrozen(conflict));
  });
});

describe('vessel registry: registration', () => {
  it('derives hull capacity from compartments when not supplied', () => {
    const vessel = registerVessel(vesselSpec());
    assert.equal(vessel.capacityKg, 1000);
    assert.equal(vessel.compartments.length, 2);
    assert.equal(vessel.inspection.status, 'cleared');
    assert.ok(Object.isFrozen(vessel));
  });

  it('accepts a matching explicit capacity and rejects a mismatch either way', () => {
    assert.equal(registerVessel(vesselSpec({ capacityKg: 1000 })).capacityKg, 1000);
    assert.throws(() => registerVessel(vesselSpec({ capacityKg: 999 })), RangeError, 'too low');
    assert.throws(() => registerVessel(vesselSpec({ capacityKg: 1001 })), RangeError, 'too high');
  });

  it('preserves the base vessel invariants: opaque id, positive capacity', () => {
    assert.throws(() => registerVessel(vesselSpec({ id: '' })), RangeError);
    assert.throws(() => registerVessel(vesselSpec({ id: 3 })), TypeError);
  });

  it('requires an inspection state', () => {
    assert.throws(() => registerVessel(vesselSpec({ inspection: undefined })), TypeError);
    assert.throws(
      () => registerVessel(vesselSpec({ inspection: { status: 'grounded' } })),
      TypeError,
      'missing recordedAtUtc',
    );
  });

  it('rejects incompatibilities naming a class the hull does not accept', () => {
    assert.throws(
      () => registerVessel(vesselSpec({ acceptedCargoClasses: ['class-dry'] })),
      RangeError,
    );
  });

  it('allows incompatibilities when no accepted-class list is declared', () => {
    const vessel = registerVessel(vesselSpec({ acceptedCargoClasses: [] }));
    assert.equal(vessel.incompatibilities.length, 1);
  });

  it('looks up compartments or throws', () => {
    const vessel = registerVessel(vesselSpec());
    assert.equal(requireCompartment(vessel, 'c-aft').capacityKg, 600);
    assert.throws(() => requireCompartment(vessel, 'c-missing'), RangeError);
  });

  it('asserts clearance for service', () => {
    assertClearedForService(registerVessel(vesselSpec()));
    assert.throws(
      () =>
        assertClearedForService(
          registerVessel(
            vesselSpec({
              inspection: { status: 'grounded', recordedAtUtc: '2030-01-01T00:00:00Z' },
            }),
          ),
        ),
      RangeError,
    );
  });
});

describe('vessel registry: the registry', () => {
  it('registers, retrieves and rejects duplicates', () => {
    const registry = createVesselRegistry();
    const vessel = registry.register(vesselSpec());
    assert.equal(registry.get('v-1'), vessel);
    assert.equal(registry.require('v-1'), vessel);
    assert.equal(registry.get('missing'), undefined);
    assert.throws(() => registry.require('missing'), RangeError);
    assert.throws(() => registry.register(vesselSpec()), RangeError, 'duplicate id');
  });

  it('replaces inspection state immutably', () => {
    const registry = createVesselRegistry();
    const before = registry.register(vesselSpec());
    const after = registry.setInspection('v-1', {
      status: 'grounded',
      recordedAtUtc: '2030-01-03T00:00:00Z',
      note: 'shaft inspection',
    });
    assert.equal(before.inspection.status, 'cleared', 'previous record untouched');
    assert.equal(after.inspection.status, 'grounded');
    assert.equal(registry.require('v-1'), after);
    assert.equal(registry.isCleared('v-1'), false);
    assert.throws(() => registry.setInspection('missing', {
      status: 'cleared',
      recordedAtUtc: '2030-01-03T00:00:00Z',
    }), RangeError);
  });

  it('reports clearance per hull', () => {
    const registry = createVesselRegistry();
    registry.register(vesselSpec());
    registry.register(
      vesselSpec({
        id: 'v-2',
        inspection: { status: 'due', recordedAtUtc: '2030-01-01T00:00:00Z' },
      }),
    );
    assert.equal(registry.isCleared('v-1'), true);
    assert.equal(registry.isCleared('v-2'), false);
  });
});

describe('vessel registry: loading plan', () => {
  it('fills compartments exactly to the boundary', () => {
    const vessel = registerVessel(vesselSpec());
    const plan = planLoading(vessel, [
      { compartmentId: 'c-fore', cargoClass: 'class-dry', massKg: 400 },
      { compartmentId: 'c-aft', cargoClass: 'class-dry', massKg: 600 },
    ]);
    assert.equal(plan.ok, true);
    assert.equal(plan.totalKg, 1000);
    assert.deepEqual(plan.byCompartment, [
      { compartmentId: 'c-fore', loadKg: 400, remainingKg: 0 },
      { compartmentId: 'c-aft', loadKg: 600, remainingKg: 0 },
    ]);
  });

  it('rejects one kilogram over a compartment', () => {
    const vessel = registerVessel(vesselSpec());
    assert.throws(
      () => planLoading(vessel, [{ compartmentId: 'c-fore', cargoClass: 'class-dry', massKg: 401 }]),
      RangeError,
    );
  });

  it('accumulates multiple allocations within one compartment', () => {
    const vessel = registerVessel(vesselSpec());
    assert.throws(
      () =>
        planLoading(vessel, [
          { compartmentId: 'c-fore', cargoClass: 'class-dry', massKg: 300 },
          { compartmentId: 'c-fore', cargoClass: 'class-dry', massKg: 101 },
        ]),
      RangeError,
      '300 + 101 > 400',
    );
    const ok = planLoading(vessel, [
      { compartmentId: 'c-fore', cargoClass: 'class-dry', massKg: 300 },
      { compartmentId: 'c-fore', cargoClass: 'class-dry', massKg: 100 },
    ]);
    assert.equal(ok.byCompartment[0].loadKg, 400);
  });

  it('rejects conflicting cargo classes on the same hull', () => {
    const vessel = registerVessel(vesselSpec());
    assert.throws(
      () =>
        planLoading(vessel, [
          { compartmentId: 'c-fore', cargoClass: 'class-chilled', massKg: 10 },
          { compartmentId: 'c-aft', cargoClass: 'class-heat', massKg: 10 },
        ]),
      RangeError,
      'heat vs chilled',
    );
  });

  it('allows repeated cargo of the same class', () => {
    const vessel = registerVessel(vesselSpec());
    const plan = planLoading(vessel, [
      { compartmentId: 'c-fore', cargoClass: 'class-heat', massKg: 10 },
      { compartmentId: 'c-aft', cargoClass: 'class-heat', massKg: 10 },
    ]);
    assert.equal(plan.totalKg, 20);
  });

  it('rejects cargo classes the hull does not accept', () => {
    const vessel = registerVessel(vesselSpec());
    assert.throws(
      () => planLoading(vessel, [{ compartmentId: 'c-fore', cargoClass: 'class-bulk', massKg: 10 }]),
      RangeError,
    );
  });

  it('rejects unknown compartments, zero and fractional mass', () => {
    const vessel = registerVessel(vesselSpec());
    assert.throws(
      () => planLoading(vessel, [{ compartmentId: 'nope', cargoClass: 'class-dry', massKg: 1 }]),
      RangeError,
    );
    assert.throws(
      () => planLoading(vessel, [{ compartmentId: 'c-fore', cargoClass: 'class-dry', massKg: 0 }]),
      RangeError,
    );
    assert.throws(
      () => planLoading(vessel, [{ compartmentId: 'c-fore', cargoClass: 'class-dry', massKg: 1.5 }]),
      TypeError,
    );
  });

  it('refuses to load a hull that is not cleared', () => {
    const vessel = registerVessel(
      vesselSpec({
        inspection: { status: 'due', recordedAtUtc: '2030-01-01T00:00:00Z' },
      }),
    );
    assert.throws(
      () => planLoading(vessel, [{ compartmentId: 'c-fore', cargoClass: 'class-dry', massKg: 1 }]),
      RangeError,
    );
  });

  it('accepts an empty plan', () => {
    const vessel = registerVessel(vesselSpec());
    const plan = planLoading(vessel, []);
    assert.equal(plan.totalKg, 0);
    assert.equal(plan.byCompartment.length, 2);
    assert.throws(() => planLoading(vessel, 'nope'), TypeError);
  });
});

describe('vessel registry: integration with sailings and the board', () => {
  const sailingSpec = (overrides = {}) => ({
    id: 's-1',
    vesselId: 'v-1',
    routeId: 'route-a',
    originPortId: 'p-north',
    destinationPortId: 'p-south',
    departsAtUtc: '2030-01-03T08:00:00Z',
    arrivesAtUtc: '2030-01-03T12:00:00Z',
    ...overrides,
  });

  it('schedules a cleared registered vessel', () => {
    const vessel = registerVessel(vesselSpec());
    const sailing = createSailing(sailingSpec(), { vessel });
    assert.equal(sailing.capacityKg, 1000, 'defaults to the hull total');
    assert.throws(() => createSailing(sailingSpec({ capacityKg: 1001 }), { vessel }), RangeError);
  });

  it('refuses to schedule a vessel that is due or grounded', () => {
    for (const status of ['due', 'grounded']) {
      const vessel = registerVessel(
        vesselSpec({ inspection: { status, recordedAtUtc: '2030-01-01T00:00:00Z' } }),
      );
      assert.throws(() => createSailing(sailingSpec(), { vessel }), RangeError, status);
    }
  });

  it('keeps plain vessels working with no inspection record', () => {
    const plain = { id: 'v-1', name: 'Plain', capacityKg: 500 };
    assert.equal(createSailing(sailingSpec(), { vessel: plain }).capacityKg, 500);
  });

  it('lets the board carry a registered vessel and honour its clearance', () => {
    const registry = createVesselRegistry();
    const cleared = registry.register(vesselSpec());
    const board = createBoard({ startUtc: '2030-01-01T00:00:00Z' });
    board.addVessel(cleared);
    assert.equal(board.vessels.get('v-1'), cleared, 'registered record stored as-is');
    board.addSailing(sailingSpec());
    assert.equal(board.sailings.get('s-1').vesselId, 'v-1');

    // Grounding the hull in the registry does not retroactively cancel the
    // sailing, but a new sailing for that hull is refused.
    registry.setInspection('v-1', { status: 'grounded', recordedAtUtc: '2030-01-02T00:00:00Z' });
    assert.throws(
      () =>
        createBoard({ startUtc: '2030-01-01T00:00:00Z' })
          .addVessel(registry.require('v-1'))
          .addSailing?.(sailingSpec({ id: 's-2' })),
      TypeError,
      'addVessel returns the vessel, not the board',
    );
    const blocked = createBoard({ startUtc: '2030-01-01T00:00:00Z' });
    blocked.addVessel(registry.require('v-1'));
    assert.throws(() => blocked.addSailing(sailingSpec({ id: 's-2' })), RangeError);
  });

  it('rejects duplicate registration on the board', () => {
    const board = createBoard({ startUtc: '2030-01-01T00:00:00Z' });
    board.addVessel(registerVessel(vesselSpec()));
    assert.throws(() => board.addVessel(registerVessel(vesselSpec())), RangeError);
  });

  it('does not confuse a registered vessel with a plain spec', () => {
    const board = createBoard({ startUtc: '2030-01-01T00:00:00Z' });
    board.addVessel({ id: 'v-plain', capacityKg: 250 });
    const stored = board.vessels.get('v-plain');
    assert.equal(stored.compartments, undefined);
    assert.equal(stored.inspection, undefined);
    assert.equal(stored.capacityKg, 250);
  });
});

