 *   acceptedCargoClasses?: Iterable<string>,
 * }} spec
 * @returns {Readonly<RegisteredVessel>}
 */
export function registerVessel(spec) {
  if (spec === null || typeof spec !== 'object') {
    throw new TypeError('vessel registration spec must be an object');
  }
  if (spec.inspection === undefined) {
    throw new TypeError('vessel registration requires an inspection state');
  }
  const compartments = createCompartments(spec.compartments);
  const compartmentTotal = sumKilograms(compartments.map((c) => c.capacityKg));

  // The hull capacity is the sum of its compartments. If a capacity is also
  // supplied it must agree exactly — the two must never disagree.
  let capacityKg;
  if (spec.capacityKg === undefined) {
    capacityKg = compartmentTotal;
  } else {
    capacityKg = assertPositiveKilograms('vessel capacityKg', spec.capacityKg);
    if (capacityKg !== compartmentTotal) {
      throw new RangeError(
        `vessel capacityKg (${capacityKg}) must equal the sum of compartment capacities (${compartmentTotal})`,
      );
    }
  }

  const inspection = createInspectionState(spec.inspection);
  const incompatibilities = createIncompatibilities(spec.incompatibilities ?? []);
  const acceptedCargoClasses = normaliseCargoClasses(spec.acceptedCargoClasses ?? []);

  // Every class named in the incompatibility table must be a class the hull
  // accepts, otherwise the declaration is meaningless (or a typo).
  for (const entry of incompatibilities) {
    for (const cargoClass of [entry.a, entry.b]) {
      if (
        acceptedCargoClasses.length > 0 &&
        !acceptedCargoClasses.includes(cargoClass)
      ) {
        throw new RangeError(
          `incompatibility names cargo class ${cargoClass}, which the vessel does not accept`,
        );
      }
    }
  }

  const vessel = createVessel({ id: spec.id, name: spec.name, capacityKg });

  return Object.freeze({
    ...vessel,
    compartments,
    inspection,
    incompatibilities,
    acceptedCargoClasses,
  });
}

/**
 * Look up a compartment on a registered vessel.
 *
 * @param {Readonly<RegisteredVessel>} vessel
 * @param {string} compartmentId
 * @returns {Readonly<Compartment>}
 */
export function requireCompartment(vessel, compartmentId) {
  const compartment = vessel.compartments.find((c) => c.id === compartmentId);
  if (!compartment) {
    throw new RangeError(`unknown compartment ${String(compartmentId)} on vessel ${vessel.id}`);
  }
  return compartment;
}

