export function planLoading(vessel, allocations) {
  if (!Array.isArray(allocations)) {
    throw new TypeError('allocations must be an array');
  }
  assertClearedForService(vessel);

  /** @type {Map<string, number>} */
  const loads = new Map(vessel.compartments.map((c) => [c.id, 0]));
  /** @type {string[]} */
  const classes = [];

  for (const allocation of allocations) {
    if (allocation === null || typeof allocation !== 'object') {
      throw new TypeError('each allocation must be an object');
    }
    const compartment = requireCompartment(vessel, allocation.compartmentId);
    const massKg = assertKilograms('allocation massKg', allocation.massKg);
    if (massKg === 0) {
      throw new RangeError('allocation massKg must be greater than zero');
    }
    const cargoClass = assertCargoClass('allocation cargoClass', allocation.cargoClass);

    if (
      vessel.acceptedCargoClasses.length > 0 &&
      !vessel.acceptedCargoClasses.includes(cargoClass)
    ) {
      throw new RangeError(`vessel ${vessel.id} does not accept cargo class ${cargoClass}`);
    }

    const conflict = firstConflict(vessel.incompatibilities, classes, cargoClass);
    if (conflict) {
      throw new RangeError(
        `cargo class ${conflict.b} cannot share vessel ${vessel.id} with class ${conflict.a}`,
      );
    }

    const nextLoad = /** @type {number} */ (loads.get(compartment.id)) + massKg;
    if (nextLoad > compartment.capacityKg) {
      throw new RangeError(
        `compartment ${compartment.id} overloaded: ${nextLoad} kg > ${compartment.capacityKg} kg`,
      );
    }
    loads.set(compartment.id, nextLoad);
    if (!classes.includes(cargoClass)) classes.push(cargoClass);
  }

  const totalKg = sumKilograms([...loads.values()]);
  const byCompartment = vessel.compartments.map((c) => {
    const loadKg = /** @type {number} */ (loads.get(c.id));
    return Object.freeze({
      compartmentId: c.id,
      loadKg,
      remainingKg: c.capacityKg - loadKg,
    });
  });

  return Object.freeze({
    ok: true,
    vesselId: vessel.id,
    totalKg,
    byCompartment: Object.freeze(byCompartment),
  });
}

