/**
 * The sailing state machine.
 *
 * A sailing moves through a fixed lifecycle:
 *
 *   draft ──plan──▶ scheduled ──boarding──▶ boarding ──depart──▶ departed
 *     │                 │                       │                    │
 *     │                 │                       │              arrive ▼
 *     └────cancel───────┴───────cancel──────────┘                 arrived
 *                       (not once departed)
 *
 * Strict rules:
 *  - `draft` and `scheduled` may be cancelled; once a sailing has departed it
 *    can no longer be cancelled, boarded or re-planned.
 *  - `boarding` may only be entered from `scheduled`, and only before the
 *    scheduled departure time.
 *  - `departed` may only be entered from `boarding` or `scheduled`, and only
 *    at or after the scheduled departure time.
 *  - `arrived` may only be entered from `departed`, and only at or after the
 *    scheduled arrival time.
 *  - `arrived` and `cancelled` are terminal.
 *
 * Every timestamp comes from the caller as a UTC value; the domain never reads
 * the clock. Time-gated transitions take the "now" instant as an argument, so
 * the same call produces the same result on every run.
 */

/** @typedef {'draft' | 'scheduled' | 'boarding' | 'departed' | 'arrived' | 'cancelled'} SailingStatus */

const STATUSES = Object.freeze([
  'draft',
  'scheduled',
  'boarding',
  'departed',
  'arrived',
  'cancelled',
]);

const STATUS_SET = new Set(STATUSES);

/**
 * Strict transition table. A status maps to the statuses it may move to.
 *
 * @type {Readonly<Record<SailingStatus, ReadonlySet<SailingStatus>>>}
 */
const TRANSITIONS = Object.freeze({
  draft: new Set(['scheduled', 'cancelled']),
  scheduled: new Set(['boarding', 'departed', 'cancelled']),
  boarding: new Set(['departed']),
  departed: new Set(['arrived']),
  arrived: new Set(),
  cancelled: new Set(),
});

/** Statuses in which a sailing may still be cancelled. */
const CANCELLABLE = new Set(['draft', 'scheduled']);

/** Statuses in which a sailing may accept new bookings. */
const BOOKABLE = new Set(['draft', 'scheduled', 'boarding']);

/** Statuses after which the sailing is finished, one way or another. */
const TERMINAL = new Set(['arrived', 'cancelled']);

/**
 * @typedef {object} SailingTransition
 * @property {SailingStatus} from
 * @property {SailingStatus} to
 * @property {Readonly<import('./time.js').Instant>} at
 * @property {string|null} note
 */

/**
 * @param {unknown} status
 * @returns {SailingStatus}
 */
export function assertSailingStatus(status) {
  if (typeof status !== 'string' || !STATUS_SET.has(status)) {
    throw new RangeError(
      `sailing status must be one of ${STATUSES.join(', ')}; got ${String(status)}`,
    );
  }
  return /** @type {SailingStatus} */ (status);
}

/** @returns {ReadonlyArray<SailingStatus>} */
export function sailingStatuses() {
  return STATUSES;
}

/**
 * The statuses a sailing in `from` is allowed to move to. Useful for
 * operator UIs and for asserting the table itself.
 *
 * @param {SailingStatus} from
 * @returns {ReadonlyArray<SailingStatus>}
 */
export function allowedTransitions(from) {
  assertSailingStatus(from);
  return Object.freeze([...TRANSITIONS[from]]);
}

/**
 * @param {SailingStatus} status
 * @returns {boolean}
 */
export function isTerminal(status) {
  assertSailingStatus(status);
  return TERMINAL.has(status);
}

/**
 * Whether bookings may still be made against a sailing in this status.
 *
 * @param {SailingStatus} status
 * @returns {boolean}
 */
export function acceptsBookings(status) {
  assertSailingStatus(status);
  return BOOKABLE.has(status);
}

/**
 * @param {SailingStatus} status
 * @returns {boolean}
 */
export function isCancellable(status) {
  assertSailingStatus(status);
  return CANCELLABLE.has(status);
}

/**
 * Check a proposed transition without performing it.
 *
 * Returns `{ ok: true }` or `{ ok: false, reason }`. The `now` argument is only
 * consulted for time-gated transitions (`boarding`, `departed`, `arrived`).
 *
 * @param {Readonly<import('./sailings.js').Sailing>} sailing
 * @param {SailingStatus} to
 * @param {Readonly<import('./time.js').Instant>|null} now
 * @returns {{ ok: true } | { ok: false, reason: string }}
 */
export function checkSailingTransition(sailing, to, now = null) {
  const from = sailing.status;
  assertSailingStatus(from);
  assertSailingStatus(to);

  if (!TRANSITIONS[from].has(to)) {
    return { ok: false, reason: `cannot move sailing ${sailing.id} from ${from} to ${to}` };
  }

  if (to === 'boarding') {
    requireNow(now, 'boarding');
    if (now.ms >= sailing.departsAt.ms) {
      return { ok: false, reason: `sailing ${sailing.id} cannot board at or after departure` };
    }
  }

  if (to === 'departed') {
    requireNow(now, 'departure');
    if (now.ms < sailing.departsAt.ms) {
      return { ok: false, reason: `sailing ${sailing.id} cannot depart before its departure time` };
    }
  }

  if (to === 'arrived') {
    requireNow(now, 'arrival');
    if (now.ms < sailing.arrivesAt.ms) {
      return { ok: false, reason: `sailing ${sailing.id} cannot arrive before its arrival time` };
    }
  }

  return { ok: true };
}

/**
 * @param {Readonly<import('./time.js').Instant>|null} now
 * @param {string} what
 * @returns {void}
 */
function requireNow(now, what) {
  if (now === null || typeof now !== 'object' || typeof now.ms !== 'number') {
    throw new TypeError(`${what} requires an explicit UTC "now" instant`);
  }
}

/**
 * Apply a transition, returning a new frozen sailing. The input sailing is
 * never mutated. Each applied transition is appended to `history`.
 *
 * @param {Readonly<import('./sailings.js').Sailing>} sailing
 * @param {SailingStatus} to
 * @param {{
 *   at: Readonly<import('./time.js').Instant>,
 *   now?: Readonly<import('./time.js').Instant>|null,
 *   note?: string,
 * }} options `at` records when the transition happened; `now` gates it.
 * @returns {Readonly<import('./sailings.js').Sailing>}
 */
export function applySailingTransition(sailing, to, options) {
  if (options === null || typeof options !== 'object') {
    throw new TypeError('sailing transition requires { at } options');
  }
  const at = options.at;
  if (at === null || typeof at !== 'object' || typeof at.ms !== 'number') {
    throw new TypeError('sailing transition requires an explicit UTC "at" instant');
  }
  // Default the gating instant to the record time; callers may pass an
  // earlier/later `now` to test the gates explicitly.
  const now = options.now === undefined ? at : options.now;
  const check = checkSailingTransition(sailing, to, now);
  if (!check.ok) {
    throw new RangeError(check.reason);
  }
  if (options.note !== undefined && typeof options.note !== 'string') {
    throw new TypeError('sailing transition note must be a string');
  }
  const note = options.note === undefined || options.note.length === 0 ? null : options.note;
  /** @type {ReadonlyArray<SailingTransition>} */
  const history = Object.isFrozen(sailing.history) ? sailing.history : Object.freeze([]);
  const entry = Object.freeze({ from: sailing.status, to, at, note });
  return Object.freeze({
    ...sailing,
    status: to,
    history: Object.freeze([...history, entry]),
  });
}

/**
 * Convenience wrappers, one per transition. Each takes an explicit UTC
 * instant so behaviour is reproducible.
 *
 * @param {Readonly<import('./sailings.js').Sailing>} sailing
 * @param {Readonly<import('./time.js').Instant>} at
 * @param {Readonly<import('./time.js').Instant>|null} [now]
 * @returns {Readonly<import('./sailings.js').Sailing>}
 */
export function planSailing(sailing, at, now) {
  return applySailingTransition(sailing, 'scheduled', { at, now });
}

/**
 * @param {Readonly<import('./sailings.js').Sailing>} sailing
 * @param {Readonly<import('./time.js').Instant>} at
 * @param {Readonly<import('./time.js').Instant>|null} [now]
 * @returns {Readonly<import('./sailings.js').Sailing>}
 */
export function boardSailing(sailing, at, now) {
  return applySailingTransition(sailing, 'boarding', { at, now });
}

/**
 * @param {Readonly<import('./sailings.js').Sailing>} sailing
 * @param {Readonly<import('./time.js').Instant>} at
 * @param {Readonly<import('./time.js').Instant>|null} [now]
 * @returns {Readonly<import('./sailings.js').Sailing>}
 */
export function departSailing(sailing, at, now) {
  return applySailingTransition(sailing, 'departed', { at, now });
}

/**
 * @param {Readonly<import('./sailings.js').Sailing>} sailing
 * @param {Readonly<import('./time.js').Instant>} at
 * @param {Readonly<import('./time.js').Instant>|null} [now]
 * @returns {Readonly<import('./sailings.js').Sailing>}
 */
export function arriveSailing(sailing, at, now) {
  return applySailingTransition(sailing, 'arrived', { at, now });
}

/**
 * @param {Readonly<import('./sailings.js').Sailing>} sailing
 * @param {Readonly<import('./time.js').Instant>} at
 * @param {string} [reason]
 * @returns {Readonly<import('./sailings.js').Sailing>}
 */
export function cancelSailing(sailing, at, reason) {
  return applySailingTransition(sailing, 'cancelled', { at, now: at, note: reason });
}

