import { describe, it, assert } from '../tests/helpers.js';

import {
  assertSailingStatus,
  sailingStatuses,
  allowedTransitions,
  isTerminal,
  acceptsBookings,
  isCancellable,
  checkSailingTransition,
  applySailingTransition,
  planSailing,
  boardSailing,
  departSailing,
  arriveSailing,
  cancelSailing,
} from '../src/domain/sailing-state.js';
import { instant } from '../src/domain/time.js';
import { createSailing } from '../src/domain/sailings.js';
import { createVessel } from '../src/domain/vessels.js';
import { createConsignment } from '../src/domain/consignments.js';
import { createBooking } from '../src/domain/bookings.js';
import { createBoard } from '../src/domain/board.js';

/* ---------------------------------------------------------------------- */

const vessel = createVessel({ id: 'v-1', capacityKg: 5000 });

const TIMES = {
  beforeDeparture: instant('2030-01-03T06:00:00Z'),
  atDeparture: instant('2030-01-03T08:00:00Z'),
  afterDeparture: instant('2030-01-03T09:00:00Z'),
  beforeArrival: instant('2030-01-03T11:00:00Z'),
  atArrival: instant('2030-01-03T12:00:00Z'),
  afterArrival: instant('2030-01-03T13:00:00Z'),
};

function sailingSpec(overrides = {}) {
  return {
    id: 's-1',
    vesselId: 'v-1',
    routeId: 'route-a',
    originPortId: 'p-north',
    destinationPortId: 'p-south',
    departsAtUtc: '2030-01-03T08:00:00Z',
    arrivesAtUtc: '2030-01-03T12:00:00Z',
    ...overrides,
  };
}

function draft(overrides = {}) {
  return createSailing(sailingSpec(overrides), { vessel });
}

/** Walk a sailing to `departed` via the normal path. */
function departed() {
  const scheduled = planSailing(draft(), TIMES.beforeDeparture);
  const boarding = boardSailing(scheduled, TIMES.beforeDeparture);
  return departSailing(boarding, TIMES.atDeparture);
}

/* ---------------------------------------------------------------------- */

describe('sailing state machine: vocabulary', () => {
  it('knows exactly six statuses', () => {
    assert.deepEqual(sailingStatuses(), [
      'draft',
      'scheduled',
      'boarding',
      'departed',
      'arrived',
      'cancelled',
    ]);
    for (const status of sailingStatuses()) assert.equal(assertSailingStatus(status), status);
  });

  it('rejects unknown and non-string statuses', () => {
    assert.throws(() => assertSailingStatus('done'), RangeError);
    assert.throws(() => assertSailingStatus(''), RangeError);
    assert.throws(() => assertSailingStatus(null), RangeError);
    assert.throws(() => assertSailingStatus(3), RangeError);
  });

  it('declares strict allowed transitions', () => {
    assert.deepEqual(allowedTransitions('draft').sort(), ['cancelled', 'scheduled']);
    assert.deepEqual(allowedTransitions('scheduled').sort(), ['boarding', 'cancelled', 'departed']);
    assert.deepEqual(allowedTransitions('boarding'), ['departed']);
    assert.deepEqual(allowedTransitions('departed'), ['arrived']);
    assert.deepEqual(allowedTransitions('arrived'), []);
    assert.deepEqual(allowedTransitions('cancelled'), []);
    assert.throws(() => allowedTransitions('nope'), RangeError);
  });

  it('classifies terminal and bookable states', () => {
    assert.equal(isTerminal('arrived'), true);
    assert.equal(isTerminal('cancelled'), true);
    assert.equal(isTerminal('departed'), false);
    assert.equal(isTerminal('draft'), false);

    assert.equal(acceptsBookings('draft'), true);
    assert.equal(acceptsBookings('scheduled'), true);
    assert.equal(acceptsBookings('boarding'), true);
    assert.equal(acceptsBookings('departed'), false);
    assert.equal(acceptsBookings('arrived'), false);
    assert.equal(acceptsBookings('cancelled'), false);

    assert.equal(isCancellable('draft'), true);
    assert.equal(isCancellable('scheduled'), true);
    assert.equal(isCancellable('boarding'), false);
    assert.equal(isCancellable('departed'), false);
  });
});

describe('sailing state machine: creation', () => {
  it('starts as a draft with empty history', () => {
    const s = draft();
    assert.equal(s.status, 'draft');
    assert.deepEqual(s.history, []);
    assert.ok(Object.isFrozen(s.history));
  });

  it('may start scheduled or cancelled when the caller says so', () => {
    assert.equal(draft({ status: 'scheduled' }).status, 'scheduled');
    assert.equal(draft({ status: 'cancelled' }).status, 'cancelled');
  });

  it('may not start in a post-departure state', () => {
    for (const status of ['boarding', 'departed', 'arrived']) {
      assert.throws(() => draft({ status }), RangeError, status);
    }
    assert.throws(() => draft({ status: 'nonsense' }), RangeError);
  });
});

describe('sailing state machine: happy path', () => {
  it('walks draft -> scheduled -> boarding -> departed -> arrived', () => {
    const s0 = draft();
    const s1 = planSailing(s0, TIMES.beforeDeparture);
    const s2 = boardSailing(s1, TIMES.beforeDeparture);
    const s3 = departSailing(s2, TIMES.atDeparture);
    const s4 = arriveSailing(s3, TIMES.atArrival);

    assert.equal(s1.status, 'scheduled');
    assert.equal(s2.status, 'boarding');
    assert.equal(s3.status, 'departed');
    assert.equal(s4.status, 'arrived');
    assert.equal(s4.history.length, 4);
    assert.deepEqual(
      s4.history.map((h) => `${h.from}->${h.to}`),
      ['draft->scheduled', 'scheduled->boarding', 'boarding->departed', 'departed->arrived'],
    );
  });

  it('never mutates the input sailing', () => {
    const s0 = draft();
    planSailing(s0, TIMES.beforeDeparture);
    assert.equal(s0.status, 'draft');
    assert.deepEqual(s0.history, []);
  });

  it('freezes every produced sailing and history entry', () => {
    const s1 = planSailing(draft(), TIMES.beforeDeparture);
    assert.ok(Object.isFrozen(s1));
    assert.ok(Object.isFrozen(s1.history));
    assert.ok(Object.isFrozen(s1.history[0]));
  });

  it('allows departure straight from scheduled', () => {
    const scheduled = planSailing(draft(), TIMES.beforeDeparture);
    assert.equal(departSailing(scheduled, TIMES.atDeparture).status, 'departed');
  });

  it('records an optional note', () => {
    const s = applySailingTransition(draft(), 'cancelled', {
      at: TIMES.beforeDeparture,
      note: 'weather cancellation',
    });
    assert.equal(s.history[0].note, 'weather cancellation');
    assert.equal(cancelSailing(draft(), TIMES.beforeDeparture).history[0].note, null);
    assert.equal(cancelSailing(draft(), TIMES.beforeDeparture, 'storm').history[0].note, 'storm');
  });
});

describe('sailing state machine: illegal transitions', () => {
  it('refuses skipping ahead from draft', () => {
    const s = draft();
    for (const to of ['boarding', 'departed', 'arrived']) {
      assert.throws(
        () => applySailingTransition(s, to, { at: TIMES.afterArrival }),
        RangeError,
        `draft -> ${to}`,
      );
    }
  });

  it('refuses boarding from draft', () => {
    assert.throws(() => boardSailing(draft(), TIMES.beforeDeparture), RangeError);
  });

  it('refuses going backwards', () => {
    const scheduled = planSailing(draft(), TIMES.beforeDeparture);
    assert.throws(() => planSailing(scheduled, TIMES.beforeDeparture), RangeError, 'scheduled -> scheduled');
    const boarding = boardSailing(scheduled, TIMES.beforeDeparture);
    assert.throws(() => planSailing(boarding, TIMES.beforeDeparture), RangeError, 'boarding -> scheduled');
  });

  it('refuses every transition out of a terminal state', () => {
    const arrived = arriveSailing(departed(), TIMES.atArrival);
    for (const to of sailingStatuses()) {
      assert.throws(
        () => applySailingTransition(arrived, to, { at: TIMES.afterArrival }),
        RangeError,
        `arrived -> ${to}`,
      );
    }
    const cancelled = cancelSailing(draft(), TIMES.beforeDeparture);
    for (const to of sailingStatuses()) {
      assert.throws(
        () => applySailingTransition(cancelled, to, { at: TIMES.beforeDeparture }),
        RangeError,
        `cancelled -> ${to}`,
      );
    }
  });

  it('refuses cancelling once boarding has begun', () => {
    const boarding = boardSailing(planSailing(draft(), TIMES.beforeDeparture), TIMES.beforeDeparture);
    assert.throws(() => cancelSailing(boarding, TIMES.beforeDeparture), RangeError);
  });

  it('refuses cancelling a departed or arrived sailing', () => {
    assert.throws(() => cancelSailing(departed(), TIMES.afterArrival), RangeError);
    const arrived = arriveSailing(departed(), TIMES.atArrival);
    assert.throws(() => cancelSailing(arrived, TIMES.afterArrival), RangeError);
  });
});

describe('sailing state machine: time gates', () => {
  it('boards only strictly before departure', () => {
    const scheduled = planSailing(draft(), TIMES.beforeDeparture);
    assert.equal(boardSailing(scheduled, TIMES.beforeDeparture, TIMES.beforeDeparture).status, 'boarding');
    assert.throws(
      () => boardSailing(scheduled, TIMES.atDeparture, TIMES.atDeparture),
      RangeError,
      'exactly at departure is too late',
    );
    assert.throws(
      () => boardSailing(scheduled, TIMES.afterDeparture, TIMES.afterDeparture),
      RangeError,
      'after departure',
    );
  });

  it('departs only at or after Departure', () => {
    const boarding = boardSailing(planSailing(draft(), TIMES.beforeDeparture), TIMES.beforeDeparture);
    assert.throws(
      () => departSailing(boarding, TIMES.afterDeparture, TIMES.beforeDeparture),
      RangeError,
      'one hour early',
    );
    assert.equal(departSailing(boarding, TIMES.atDeparture, TIMES.atDeparture).status, 'departed');
    assert.equal(
      departSailing(boarding, TIMES.afterDeparture, TIMES.afterDeparture).status,
      'departed',
      'late departure is allowed',
    );
  });

  it('arrives only at or after arrival time', () => {
    const departedSailing = departed();
    assert.throws(
      () => arriveSailing(departedSailing, TIMES.afterArrival, TIMES.beforeArrival),
      RangeError,
      'early',
    );
    assert.equal(
      arriveSailing(departedSailing, TIMES.atArrival, TIMES.atArrival).status,
      'arrived',
      'exactly on arrival',
    );
    assert.equal(
      arriveSailing(departedSailing, TIMES.afterArrival, TIMES.afterArrival).status,
      'arrived',
      'late',
    );
  });

  it('requires an explicit now for time-gated checks', () => {
    const scheduled = planSailing(draft(), TIMES.beforeDeparture);
    assert.throws(() => checkSailingTransition(scheduled, 'boarding', null), TypeError);
    const boarded = boardSailing(scheduled, TIMES.beforeDeparture);
    assert.throws(() => checkSailingTransition(boarded, 'departed', null), TypeError);
    const gone = departSailing(boarded, TIMES.atDeparture);
    assert.throws(() => checkSailingTransition(gone, 'arrived', null), TypeError);
  });

  it('checks transitions without performing them', () => {
    const scheduled = planSailing(draft(), TIMES.beforeDeparture);
    assert.deepEqual(checkSailingTransition(scheduled, 'boarding', TIMES.beforeDeparture), { ok: true });
    const blocked = checkSailingTransition(scheduled, 'boarding', TIMES.atDeparture);
    assert.equal(blocked.ok, false);
    assert.equal(typeof blocked.reason, 'string');
    assert.equal(checkSailingTransition(scheduled, 'arrived', TIMES.afterArrival).ok, false);
  });

  it('requires explicit instants for record time and options', () => {
    assert.throws(() => applySailingTransition(draft(), 'scheduled', undefined), TypeError);
    assert.throws(() => applySailingTransition(draft(), 'scheduled', { at: null }), TypeError);
    assert.throws(
      () => applySailingTransition(draft(), 'scheduled', { at: TIMES.beforeDeparture, note: 5 }),
      TypeError,
    );
  });
});

