/**
 * Operator example: moving a sailing through its lifecycle.
 *
 * Fictional data only. Run with: node examples/sailing-lifecycle-example.js
 *
 * Deterministic: every timestamp is supplied here, so the output is identical
 * on every run.
 */

import { createBoard, allowedTransitions } from '../src/index.js';

const board = createBoard({ startUtc: '2030-01-01T00:00:00Z' });

board.addVessel({ id: 'v-skiff', name: 'Harbor Skiff', capacityKg: 1000 });
board.addSailing({
  id: 's-morning',
  vesselId: 'v-skiff',
  routeId: 'route-north-south',
  originPortId: 'p-north',
  destinationPortId: 'p-south',
  departsAtUtc: '2030-01-03T08:00:00Z',
  arrivesAtUtc: '2030-01-03T12:00:00Z',
});
board.addConsignment({
  id: 'c-produce',
  massKg: 250,
  originPortId: 'p-north',
  destinationPortId: 'p-south',
});

const sailing = () => board.sailings.get('s-morning');
console.log(`new sailing status: ${sailing().status}`);
console.log(`allowed from ${sailing().status}: ${allowedTransitions(sailing().status).join(', ')}`);

// --- Plan it the day before. ---------------------------------------------
board.transitionSailing('s-morning', 'scheduled', { atUtc: '2030-01-02T09:00:00Z' });
console.log(`\nafter planning: ${sailing().status}`);

// Book cargo while the sailing is still accepting it.
board.book({
  id: 'b-1',
  consignmentId: 'c-produce',
  sailingId: 's-morning',
  bookedAtUtc: '2030-01-02T09:15:00Z',
});
console.log(`booked ${board.loadFor('s-morning')} kg of ${sailing().capacityKg} kg`);

// --- Board two hours before departure. -----------------------------------
board.transitionSailing('s-morning', 'boarding', {
  atUtc: '2030-01-03T06:00:00Z',
  nowUtc: '2030-01-03T06:00:00Z',
});
console.log(`\nat the quay: ${sailing().status}`);

// Boarding closes at the departure time, so a late boarding is refused.
try {
  board.transitionSailing('s-morning', 'arrived', { atUtc: '2030-01-03T07:00:00Z' });
} catch (error) {
  console.log(`refused: ${error.message}`);
}

// --- Depart on schedule. -------------------------------------------------
board.transitionSailing('s-morning', 'departed', {
  atUtc: '2030-01-03T08:00:00Z',
  nowUtc: '2030-01-03T08:00:00Z',
});
console.log(`\nunderway: ${sailing().status}`);

// Once departed, no more cargo.
try {
  board.book({
    id: 'b-2',
    consignmentId: 'c-produce',
    sailingId: 's-morning',
    bookedAtUtc: '2030-01-03T08:30:00Z',
  });
} catch (error) {
  console.log(`refused booking: ${error.message}`);
}

// Cannot cancel once it has sailed.
try {
  board.transitionSailing('s-morning', 'cancelled', { atUtc: '2030-01-03T09:00:00Z' });
} catch (error) {
  console.log(`refused cancellation: ${error.message}`);
}

// --- Arrive. -------------------------------------------------------------
board.transitionSailing('s-morning', 'arrived', {
  atUtc: '2030-01-03T12:00:00Z',
  nowUtc: '2030-01-03T12:00:00Z',
});
console.log(`\nat the far quay: ${sailing().status}`);
console.log(`allowed from ${sailing().status}: ${allowedTransitions(sailing().status).length} (terminal)`);

console.log('\nhistory:');
for (const step of sailing().history) {
  console.log(`  ${step.from} -> ${step.to} at ${step.at.utc}${step.note ? ` (${step.note})` : ''}`);
}

