/**
 * The booking allocator.
 *
 * The allocator turns a booking request into concrete compartment assignments
 * on a vessel, or puts the request on a stable waitlist when the cargo cannot
 * fit right now.
 *
 * Three rules shape it:
 *
 *  1. **Integer kilograms only.** Every capacity, load and reservation is a
 *     non-negative safe integer. Fractional or negative masses are rejected
 *     before anything is changed.
 *  2. **Atomic reservations.** A reservation spanning several compartments is
 *     all-or-nothing. Either every requested line is placed, or none is, and
 *     the ledger is left exactly as it was. No partial placement can ever be
 *     observed.
 *  3. **Stable waitlists.** Waiters are served strictly in the order they
 *     joined (FIFO), and equal positions never swap. A waiter's ticket is
 *     monotonic, so the order is reproducible and does not depend on map
 *     iteration, ids or wall-clock time.
 *
 * The allocator is a pure, in-memory ledger over a vessel's compartments. It
 * does not mutate vessels, sailings or bookings; callers wire it into those
 * records themselves, so existing invariants stay in one place.
 */

import { assertOpaqueId } from './ids.js';
import {
  assertKilograms,
  assertPositiveKilograms,
  sumKilograms,
  capacityReport,
} from './capacity.js';
import { assertCargoClass } from './vessel-registry.js';

/**
 * @typedef {object} CompartmentLedger
 * @property {string} compartmentId
 * @property {number} capacityKg
 * @property {number} usedKg
 */

/**
 * A single line of a reservation request: how much of which cargo class goes
 * into which compartment.
 *
 * @typedef {object} AllocationLine
 * @property {string} compartmentId
 * @property {string} cargoClass
 * @property {number} massKg
 */

/**
 * @typedef {object} Reservation
 * @property {string} id opaque reservation id
 * @property {string} bookingId
 * @property {string} vesselId
 * @property {ReadonlyArray<AllocationLine>} lines
 * @property {number} totalKg
 */

/**
 * @typedef {object} Waiter
 * @property {string} bookingId
 * @property {number} ticket monotonic service position; lower is served first
 * @property {ReadonlyArray<AllocationLine>} lines
 * @property {number} totalKg
 * @property {Readonly<import('./time.js').Instant>} enqueuedAt
 */

/**
 * Validate and normalise a reservation request into immutable lines.
 *
 * Duplicate `compartmentId` lines are merged so that a request naming the same
 * hold twice behaves exactly like a single combined line — this keeps the
 * "does it fit?" question unambiguous.
 *
 * @param {ReadonlyArray<{ compartmentId: string, cargoClass: string, massKg: number }>} lines
 * @returns {ReadonlyArray<AllocationLine>}
 */
export function normaliseAllocationLines(lines) {
  if (!Array.isArray(lines) || lines.length === 0) {
    throw new RangeError('a reservation needs at least one allocation line');
  }
  /** @type {Map<string, { compartmentId: string, cargoClass: string, mass: number }>} */
  const merged = new Map();
  const order = [];
  for (const line of lines) {
    if (line === null || typeof line !== 'object') {
      throw new TypeError('each allocation line must be an object');
    }
    const compartmentId = assertOpaqueId('compartment id', line.compartmentId);
    const cargoClass = assertCargoClass('cargo class', line.cargoClass);
    const massKg = assertPositiveKilograms('allocation line massKg', line.massKg);

    const existing = merged.get(compartmentId);
    if (existing === undefined) {
      merged.set(compartmentId, { compartmentId, cargoClass, mass: massKg });
      order.push(compartmentId);
    } else {
      if (existing.cargoClass !== cargoClass) {
        throw new RangeError(
          `compartment ${compartmentId} may not mix cargo classes ` +
            `${existing.cargoClass} and ${cargoClass} in one reservation`,
        );
      }
      existing.mass += massKg;
      if (!Number.isSafeInteger(existing.mass)) {
        throw new RangeError('allocation line mass exceeds the safe integer range');
      }
    }
  }
  return Object.freeze(
    order.map((compartmentId) => {
      const entry = /** @type {{ compartmentId: string, cargoClass: string, mass: number }} */ (
        merged.get(compartmentId)
      );
      return Object.freeze({
        compartmentId,
        cargoClass: entry.cargoClass,
        massKg: entry.mass,
      });
    }),
