/**
 * Create a booking allocator over a fixed window of compartments.
 *
 * `rooms` is a list of `{ compartmentId, capacityKg }`. The allocator copies
 * them into a private ledger; the caller's objects are never mutated.
 *
 * @param {{ vesselId: string, compartments: ReadonlyArray<{ id: string, capacityKg: number }> }} spec
 * @returns {Readonly<object>}
 */
export function createBookingAllocator(spec) {
  if (spec === null || typeof spec !== 'object') {
    throw new TypeError('allocator spec must be an object');
  }
