    throw new RangeError('an allocator needs at least one compartment');
  }

  /** @type {Map<string, number>} capacity per compartment, in fixed order */
  const capacities = new Map();
  for (const compartment of spec.compartments) {
    const id = assertOpaqueId('compartment id', compartment?.id);
    if (capacities.has(id)) {
      throw new RangeError(`duplicate compartment id: ${id}`);
    }
    capacities.set(id, assertPositiveKilograms('compartment capacityKg', compartment.capacityKg));
