      const normalised = normaliseAllocationLines(lines);
      return checkFit(capacities, used, normalised);
    },

    /**
     * Reserve capacity atomically.
     *
     * @param {{ id: string, bookingId: string, lines: ReadonlyArray<AllocationLine> }} request
     * @returns {Readonly<Reservation>}
     */
    reserve(request) {
      if (request === null || typeof request !== 'object') {
        throw new TypeError('reservation request must be an object');
      }
      const id = assertOpaqueId('reservation id', request.id);
      const bookingId = assertOpaqueId('booking id', request.bookingId);
      if (reservations.has(id)) {
