    },

    /**
     * Release a reservation's capacity, if it exists. Releasing an unknown id
     * is a no-op so cancellation is idempotent.
     *
     * @param {string} reservationId
     * @returns {boolean} whether anything was released
     */
    release(reservationId) {
      const reservation = reservations.get(reservationId);
      if (!reservation) return false;
      for (const line of reservation.lines) {
        const remaining = /** @type {number} */ (used.get(line.compartmentId)) - line.massKg;
        if (remaining < 0) {
          throw new RangeError(`ledger underflow on compartment ${line.compartmentId}`);
        }
        used.set(line.compartmentId, remaining);
      }
      reservations.delete(reservationId);
      return true;
    },

    /**
     * @param {string} reservationId
     * @returns {Readonly<Reservation>|undefined}
     */
