      return reservations.get(reservationId);
    },

    /** @returns {ReadonlyArray<Readonly<Reservation>>} */
    reservations() {
      return Object.freeze([...reservations.values()]);
    },

    /**
     * Add a request to the waitlist. The ticket is assigned on arrival and
     * never changes, so positions are stable.
     *
     * @param {{ bookingId: string, lines: ReadonlyArray<AllocationLine> }} request
     * @param {Readonly<import('./time.js').Instant>} enqueuedAt caller-supplied UTC instant
     * @returns {Readonly<Waiter>}
     */
