  for (const [compartmentId, massKg] of demand) {
    const capacityKg = /** @type {number} */ (capacities.get(compartmentId));
    const nextUsed = /** @type {number} */ (used.get(compartmentId)) + massKg;
    if (nextUsed > capacityKg) {
      return {
        ok: false,
        reason:
          `compartment ${compartmentId} cannot take ${massKg} kg: ` +
          `${nextUsed} kg > ${capacityKg} kg capacity`,
        compartmentId,
      };
    }
  }
  return { ok: true };
}

/**
 * @param {Map<string, number>} map
 * @param {string} key
 * @param {string} what
 * @returns {number}
 */
function requireKnown(map, key, what) {
  const value = map.get(key);
  if (value === undefined) {
    throw new RangeError(`unknown ${what}: ${String(key)}`);
  }
  return value;
}

export { assertKilograms, capacityReport };

