 * and the waiter's own stable ticket, so they stay unique even if the same
 * booking is enqueued and promoted more than once.
 */
const makeReservationId = (bookingId, ticket) => `r:${bookingId}:${ticket}`;

/**
 * Build an allocator for a registered vessel's compartments.
 *
 * The vessel must be cleared for service: a hull that is due for inspection
 * or grounded cannot take reservations. This keeps the allocator consistent
 * with the sailing and loading rules in the vessel registry.
 *
 * @param {Readonly<import('./vessel-registry.js').RegisteredVessel>} vessel
 * @returns {Readonly<object>}
 */
export function createAllocatorForVessel(vessel) {
  if (vessel === null || typeof vessel !== 'object' || !Array.isArray(vessel.compartments)) {
    throw new TypeError('createAllocatorForVessel requires a registered vessel');
