import { describe, it, assert } from '../tests/helpers.js';

import {
  normaliseAllocationLines,
  createBookingAllocator,
  createAllocatorForVessel,
} from '../src/domain/allocator.js';
import { registerVessel } from '../src/domain/vessel-registry.js';
import { instant } from '../src/domain/time.js';

/* ---------------------------------------------------------------------- */

const COMPARTMENTS = [
  { id: 'c-fore', capacityKg: 400 },
  { id: 'c-aft', capacityKg: 600 },
];

function allocator() {
  return createBookingAllocator({ vesselId: 'v-1', compartments: COMPARTMENTS });
}

let seq = 0;
function reserve(a, lines, bookingId = `b-${++seq}`) {
  return a.reserve({ id: `r-${++seq}`, bookingId, lines });
}

const t = (utc) => instant(utc);

/* ---------------------------------------------------------------------- */

describe('allocator: allocation lines', () => {
  it('normalises lines into frozen records', () => {
    const lines = normaliseAllocationLines([
      { compartmentId: 'c-fore', cargoClass: 'class-dry', massKg: 10 },
    ]);
    assert.equal(lines.length, 1);
    assert.deepEqual(lines[0], { compartmentId: 'c-fore', cargoClass: 'class-dry', massKg: 10 });
    assert.ok(Object.isFrozen(lines));
    assert.ok(Object.isFrozen(lines[0]));
  });

  it('merges repeated lines for the same compartment', () => {
    const lines = normaliseAllocationLines([
      { compartmentId: 'c-fore', cargoClass: 'class-dry', massKg: 10 },
      { compartmentId: 'c-fore', cargoClass: 'class-dry', massKg: 5 },
    ]);
    assert.equal(lines.length, 1);
    assert.equal(lines[0].massKg, 15);
  });

  it('rejects mixing cargo classes within one compartment line', () => {
    assert.throws(
      () =>
        normaliseAllocationLines([
          { compartmentId: 'c-fore', cargoClass: 'class-dry', massKg: 10 },
          { compartmentId: 'c-fore', cargoClass: 'class-heat', massKg: 5 },
        ]),
      RangeError,
    );
  });

  it('requires at least one line', () => {
    assert.throws(() => normaliseAllocationLines([]), RangeError);
    assert.throws(() => normaliseAllocationLines('nope'), RangeError);
  });

  it('requires positive integer kilograms and opaque ids', () => {
    assert.throws(
      () => normaliseAllocationLines([{ compartmentId: 'c-fore', cargoClass: 'x', massKg: 0 }]),
      RangeError,
    );
    assert.throws(
      () => normaliseAllocationLines([{ compartmentId: 'c-fore', cargoClass: 'x', massKg: 1.5 }]),
      TypeError,
    );
    assert.throws(
      () => normaliseAllocationLines([{ compartmentId: '', cargoClass: 'x', massKg: 1 }]),
      RangeError,
    );
    assert.throws(
      () => normaliseAllocationLines([{ compartmentId: 'c-fore', cargoClass: '', massKg: 1 }]),
      RangeError,
    );
  });
});

describe('allocator: construction', () => {
  it('starts with every compartment empty', () => {
    const a = allocator();
    assert.deepEqual(a.ledgers(), [
      { compartmentId: 'c-fore', capacityKg: 400, usedKg: 0 },
      { compartmentId: 'c-aft', capacityKg: 600, usedKg: 0 },
    ]);
    assert.deepEqual(a.totals(), { capacityKg: 1000, usedKg: 0, remainingKg: 1000 });
  });

  it('rejects duplicate and invalid compartments', () => {
    assert.throws(
      () =>
        createBookingAllocator({
          vesselId: 'v',
          compartments: [
            { id: 'c', capacityKg: 1 },
            { id: 'c', capacityKg: 2 },
          ],
        }),
      RangeError,
    );
    assert.throws(() => createBookingAllocator({ vesselId: 'v', compartments: [] }), RangeError);
    assert.throws(
      () => createBookingAllocator({ vesselId: 'v', compartments: [{ id: 'c', capacityKg: 0 }] }),
      RangeError,
    );
  });

  it('does not mutate the caller’s compartment list', () => {
    const compartments = [{ id: 'c-1', capacityKg: 100 }];
    const a = createBookingAllocator({ vesselId: 'v', compartments });
    reserve(a, [{ compartmentId: 'c-1', cargoClass: 'class-dry', massKg: 50 }]);
    assert.equal(compartments[0].capacityKg, 100);
  });
});

describe('allocator: reservations', () => {
  it('reserves within a single compartment', () => {
    const a = allocator();
    const r = reserve(a, [{ compartmentId: 'c-fore', cargoClass: 'class-dry', massKg: 150 }]);
    assert.equal(r.totalKg, 150);
    assert.deepEqual(a.capacityOf('c-fore'), { capacityKg: 400, usedKg: 150, remainingKg: 250 });
  });

  it('fills a compartment exactly to its boundary', () => {
    const a = allocator();
    reserve(a, [{ compartmentId: 'c-fore', cargoClass: 'class-dry', massKg: 400 }]);
    assert.equal(a.capacityOf('c-fore').remainingKg, 0);
    // One more kilogram does not fit.
    assert.throws(
      () => reserve(a, [{ compartmentId: 'c-fore', cargoClass: 'class-dry', massKg: 1 }]),
      RangeError,
    );
  });

  it('accumulates several reservations in one compartment', () => {
    const a = allocator();
    reserve(a, [{ compartmentId: 'c-aft', cargoClass: 'class-dry', massKg: 300 }]);
    reserve(a, [{ compartmentId: 'c-aft', cargoClass: 'class-dry', massKg: 300 }]);
    assert.equal(a.capacityOf('c-aft').remainingKg, 0);
    assert.equal(a.totals().usedKg, 600);
  });

  it('rejects duplicate reservation ids', () => {
    const a = allocator();
    a.reserve({ id: 'r-1', bookingId: 'b-1', lines: [{ compartmentId: 'c-fore', cargoClass: 'x', massKg: 1 }] });
    assert.throws(
      () =>
        a.reserve({ id: 'r-1', bookingId: 'b-2', lines: [{ compartmentId: 'c-fore', cargoClass: 'x', massKg: 1 }] }),
      RangeError,
    );
  });

  it('rejects unknown compartments', () => {
    const a = allocator();
    assert.throws(
      () => reserve(a, [{ compartmentId: 'c-nope', cargoClass: 'class-dry', massKg: 1 }]),
      RangeError,
    );
    assert.throws(() => a.capacityOf('c-nope'), RangeError);
  });
});

describe('allocator: atomic multi-compartment reservations', () => {
  it('places a reservation spanning two compartments', () => {
    const a = allocator();
    const r = reserve(a, [
      { compartmentId: 'c-fore', cargoClass: 'class-dry', massKg: 100 },
      { compartmentId: 'c-aft', cargoClass: 'class-dry', massKg: 200 },
    ]);
    assert.equal(r.totalKg, 300);
    assert.equal(a.capacityOf('c-fore').usedKg, 100);
    assert.equal(a.capacityOf('c-aft').usedKg, 200);
  });

  it('changes nothing when one line does not fit', () => {
    const a = allocator();
    reserve(a, [{ compartmentId: 'c-aft', cargoClass: 'class-dry', massKg: 500 }]);

    // Fore would fit, aft would not: the whole request must be refused.
    assert.throws(
      () =>
        reserve(a, [
          { compartmentId: 'c-fore', cargoClass: 'class-dry', massKg: 100 },
          { compartmentId: 'c-aft', cargoClass: 'class-dry', massKg: 200 },
        ]),
      RangeError,
    );

    assert.deepEqual(a.ledgers(), [
      { compartmentId: 'c-fore', capacityKg: 400, usedKg: 0, },
      { compartmentId: 'c-aft', capacityKg: 600, usedKg: 500 },
    ]);
    assert.equal(a.reservations().length, 1, 'the refused reservation was not recorded');
  });

  it('is atomic even when the failing line comes first', () => {
    const a = allocator();
    reserve(a, [{ compartmentId: 'c-fore', cargoClass: 'class-dry', massKg: 400 }]);
    assert.throws(
      () =>
        reserve(a, [
          { compartmentId: 'c-fore', cargoClass: 'class-dry', massKg: 10 },
          { compartmentId: 'c-aft', cargoClass: 'class-dry', massKg: 10 },
        ]),
      RangeError,
    );
    assert.equal(a.capacityOf('c-aft').usedKg, 0);
    assert.equal(a.capacityOf('c-fore').usedKg, 400);
  });

  it('fits() reports without reserving', () => {
    const a = allocator();
    assert.deepEqual(a.fits([{ compartmentId: 'c-fore', cargoClass: 'x', massKg: 400 }]), { ok: true });
    assert.equal(
      a.fits([{ compartmentId: 'c-fore', cargoClass: 'x', massKg: 401 }]).ok,
      false,
    );
    assert.equal(a.capacityOf('c-fore').usedKg, 0, 'fits() reserved nothing');
  });

  it('names the blocking compartment when it does not fit', () => {
    const a = allocator();
    const result = a.fits([{ compartmentId: 'c-aft', cargoClass: 'x', massKg: 601 }]);
    assert.equal(result.ok, false);
    assert.equal(result.compartmentId, 'c-aft');
    assert.equal(typeof result.reason, 'string');
  });
});

describe('allocator: releasing', () => {
  it('releases a reservation and frees capacity', () => {
    const a = allocator();
    const r = reserve(a, [
      { compartmentId: 'c-fore', cargoClass: 'class-dry', massKg: 100 },
      { compartmentId: 'c-aft', cargoClass: 'class-dry', massKg: 200 },
    ]);
    assert.equal(a.release(r.id), true);
    assert.equal(a.totals().usedKg, 0);
    assert.equal(a.reservation(r.id), undefined);
  });

  it('releasing an unknown reservation is a no-op', () => {
    const a = allocator();
    assert.equal(a.release('r-missing'), false);
  });

  it('releasing twice is a no-op the second time', () => {
    const a = allocator();
    const r = reserve(a, [{ compartmentId: 'c-fore', cargoClass: 'class-dry', massKg: 10 }]);
    assert.equal(a.release(r.id), true);
    assert.equal(a.release(r.id), false);
    assert.equal(a.capacityOf('c-fore').usedKg, 0);
  });
});

describe('allocator: stable waitlists', () => {
  it('assigns monotonic tickets in arrival order', () => {
    const a = allocator();
    const w1 = a.enqueue({ bookingId: 'b-1', lines: [{ compartmentId: 'c-fore', cargoClass: 'x', massKg: 1 }] }, t('2030-01-01T00:00:00Z'));
    const w2 = a.enqueue({ bookingId: 'b-2', lines: [{ compartmentId: 'c-fore', cargoClass: 'x', massKg: 1 }] }, t('2030-01-01T00:00:01Z'));
    const w3 = a.enqueue({ bookingId: 'b-3', lines: [{ compartmentId: 'c-fore', cargoClass: 'x', massKg: 1 }] }, t('2030-01-01T00:00:02Z'));
    assert.deepEqual([w1.ticket, w2.ticket, w3.ticket], [1, 2, 3]);
    assert.deepEqual(a.waitlist().map((w) => w.bookingId), ['b-1', 'b-2', 'b-3']);
  });

  it('tickets do not depend on timestamp ordering', () => {
    const a = allocator();
    // The third arrival has the earliest timestamp; tickets still follow arrival.
    a.enqueue({ bookingId: 'b-1', lines: [{ compartmentId: 'c-fore', cargoClass: 'x', massKg: 1 }] }, t('2030-01-01T05:00:00Z'));
    a.enqueue({ bookingId: 'b-2', lines: [{ compartmentId: 'c-fore', cargoClass: 'x', massKg: 1 }] }, t('2030-01-01T03:00:00Z'));
    const third = a.enqueue({ bookingId: 'b-3', lines: [{ compartmentId: 'c-fore', cargoClass: 'x', massKg: 1 }] }, t('2030-01-01T01:00:00Z'));
    assert.equal(third.ticket, 3);
    assert.deepEqual(a.waitlist().map((w) => w.bookingId), ['b-1', 'b-2', 'b-3']);
  });

  it('rejects duplicate waiters and requires an explicit enqueue time', () => {
    const a = allocator();
    const lines = [{ compartmentId: 'c-fore', cargoClass: 'x', massKg: 1 }];
    a.enqueue({ bookingId: 'b-1', lines }, t('2030-01-01T00:00:00Z'));
    assert.throws(() => a.enqueue({ bookingId: 'b-1', lines }, t('2030-01-01T00:00:00Z')), RangeError);
    assert.throws(() => a.enqueue({ bookingId: 'b-2', lines }, null), TypeError);
  });

  it('withdraws a waiter and preserves the others’ order', () => {
    const a = allocator();
    const lines = [{ compartmentId: 'c-fore', cargoClass: 'x', massKg: 1 }];
    for (const id of ['b-1', 'b-2', 'b-3']) {
      a.enqueue({ bookingId: id, lines }, t('2030-01-01T00:00:00Z'));
    }
    assert.equal(a.withdraw('b-2'), true);
    assert.deepEqual(a.waitlist().map((w) => w.bookingId), ['b-1', 'b-3']);
    assert.equal(a.withdraw('b-2'), false);
  });
});

describe('allocator: draining the waitlist', () => {
  const linesFor = (compartmentId, massKg) => [{ compartmentId, cargoClass: 'x', massKg }];

  it('serves waiters strictly in ticket order', () => {
    const a = allocator();
    // Room for exactly two of the three 200 kg waiters in the fore hold.
    a.enqueue({ bookingId: 'b-1', lines: linesFor('c-fore', 200) }, t('2030-01-01T00:00:00Z'));
    a.enqueue({ bookingId: 'b-2', lines: linesFor('c-fore', 200) }, t('2030-01-01T00:00:00Z'));
    a.enqueue({ bookingId: 'b-3', lines: linesFor('c-fore', 200) }, t('2030-01-01T00:00:00Z'));

    const result = a.drain();
    assert.deepEqual(result.booked.map((r) => r.bookingId), ['b-1', 'b-2']);
    assert.deepEqual(result.waiting.map((w) => w.bookingId), ['b-3']);
    assert.equal(a.capacityOf('c-fore').remainingKg, 0);
  });

  it('keeps an unfittable head waiter in place and still serves later ones', () => {
    const a = allocator();
    // b-1 wants the whole aft hold; b-2 wants a small slot in the fore hold.
    a.enqueue({ bookingId: 'b-1', lines: linesFor('c-aft', 600) }, t('2030-01-01T00:00:00Z'));
    a.enqueue({ bookingId: 'b-2', lines: linesFor('c-fore', 50) }, t('2030-01-01T00:00:00Z'));
    reserve(a, linesFor('c-aft', 1));

    const result = a.drain();
    assert.deepEqual(result.booked.map((r) => r.bookingId), ['b-2']);
    assert.deepEqual(result.waiting.map((w) => w.bookingId), ['b-1']);
    assert.equal(a.waitlist()[0].bookingId, 'b-1', 'head of queue keeps its place');
    assert.equal(a.waitlist()[0].ticket, 1, 'ticket is stable across drains');
  });

  it('repeated drains are idempotent once the queue is empty', () => {
    const a = allocator();
    a.enqueue({ bookingId: 'b-1', lines: linesFor('c-fore', 100) }, t('2030-01-01T00:00:00Z'));
    a.drain();
    const second = a.drain();
    assert.equal(second.booked.length, 0);
    assert.equal(second.waiting.length, 0);
    assert.equal(a.capacityOf('c-fore').usedKg, 100);
  });

  it('promotes waiters again after capacity is released', () => {
    const a = allocator();
    reserve(a, linesFor('c-fore', 400));
    a.enqueue({ bookingId: 'b-1', lines: linesFor('c-fore', 400) }, t('2030-01-01T00:00:00Z'));
    assert.equal(a.drain().booked.length, 0);

    const held = a.reservations()[0];
    a.release(held.id);
    const result = a.drain();
    assert.deepEqual(result.booked.map((r) => r.bookingId), ['b-1']);
  });

  it('gives promoted reservations unique ids across promotions', () => {
    const a = allocator();
    reserve(a, linesFor('c-fore', 400));
    a.enqueue({ bookingId: 'b-1', lines: linesFor('c-fore', 400) }, t('2030-01-01T00:00:00Z'));
    a.drain();
    const first = a.reservations()[0];
    a.release(first.id);

    // The same booking waits again, with a new ticket.
    a.enqueue({ bookingId: 'b-1', lines: linesFor('c-fore', 400) }, t('2030-01-01T00:00:00Z'));
    const second = a.drain();
    assert.equal(second.booked.length, 1);
    assert.notEqual(second.booked[0].id, first.id);
    assert.equal(a.reservations().length, 1);
  });

  it('treats a multi-compartment waiter atomically', () => {
    const a = allocator();
    reserve(a, linesFor('c-aft', 500));
    a.enqueue(
      {
        bookingId: 'b-1',
        lines: [
          { compartmentId: 'c-fore', cargoClass: 'x', massKg: 100 },
          { compartmentId: 'c-aft', cargoClass: 'x', massKg: 200 },
        ],
      },
      t('2030-01-01T00:00:00Z'),
    );
    const result = a.drain();
    assert.equal(result.booked.length, 0, 'aft has only 100 kg left');
    assert.equal(a.capacityOf('c-fore').usedKg, 0, 'fore was not touched');
  });

  it('returns an immutable report', () => {
    const a = allocator();
    a.enqueue({ bookingId: 'b-1', lines: linesFor('c-fore', 10) }, t('2030-01-01T00:00:00Z'));
    const result = a.drain();
    assert.ok(Object.isFrozen(result));
    assert.ok(Object.isFrozen(result.booked));
    assert.ok(Object.isFrozen(result.waiting));
  });
});

describe('allocator: integration with the vessel registry', () => {
  const vesselSpec = (overrides = {}) => ({
    id: 'v-1',
    compartments: COMPARTMENTS,
    inspection: { status: 'cleared', recordedAtUtc: '2030-01-01T00:00:00Z' },
    ...overrides,
  });

  it('builds an allocator from a cleared registered vessel', () => {
    const vessel = registerVessel(vesselSpec());
    const a = createAllocatorForVessel(vessel);
    assert.equal(a.vesselId, 'v-1');
    assert.deepEqual(a.totals(), { capacityKg: 1000, usedKg: 0, remainingKg: 1000 });
    assert.deepEqual(
      a.ledgers().map((l) => l.compartmentId),
      ['c-fore', 'c-aft'],
      'compartment order follows the vessel',
    );
  });

  it('refuses a hull that is due or grounded', () => {
    for (const status of ['due', 'grounded']) {
      const vessel = registerVessel(
        vesselSpec({ inspection: { status, recordedAtUtc: '2030-01-01T00:00:00Z' } }),
      );
      assert.throws(() => createAllocatorForVessel(vessel), RangeError, status);
    }
  });

  it('rejects non-vessel input', () => {
    assert.throws(() => createAllocatorForVessel(null), TypeError);
    assert.throws(() => createAllocatorForVessel({ id: 'v-1' }), TypeError);
  });
});

