  const makeReservationId = (bookingId, ticket) => `r:${bookingId}:${ticket}`;

  const api = {
    vesselId,

    /** @returns {ReadonlyArray<CompartmentLedger>} */
    ledgers() {
      return Object.freeze(
        [...capacities.entries()].map(([compartmentId, capacityKg]) =>
          Object.freeze({ compartmentId, capacityKg, usedKg: /** @type {number} */ (used.get(compartmentId)) }),
        ),
      );
    },

    /**
     * @param {string} compartmentId
     * @returns {{ capacityKg: number, usedKg: number, remainingKg: number }}
     */
    capacityOf(compartmentId) {
      const capacityKg = requireKnown(capacities, compartmentId, 'compartment');
      const usedKg = /** @type {number} */ (used.get(compartmentId));
      return { capacityKg, usedKg, remainingKg: capacityKg - usedKg };
    },

    /** @returns {{ capacityKg: number, usedKg: number, remainingKg: number }} */
    totals() {
      const capacityKg = sumKilograms([...capacities.values()]);
      const usedKg = sumKilograms([...used.values()]);
      return { capacityKg, usedKg, remainingKg: capacityKg - usedKg };
    },

    /**
     * Whether a set of lines would fit right now, without reserving.
     *
     * @param {ReadonlyArray<AllocationLine>} lines
     * @returns {{ ok: true } | { ok: false, reason: string, compartmentId?: string }}
     */
    fits(lines) {
      const normalised = normaliseAllocationLines(lines);
      return checkFit(capacities, used, normalised);
