/**
 * Operator example: allocating bookings into compartments, with a waitlist.
 *
 * Fictional data only. Run with: node examples/allocator-example.js
 *
 * Deterministic: every timestamp is supplied here, so the output is identical
 * on every run.
 */

import { createAllocatorForVessel, registerVessel } from '../src/index.js';

const vessel = registerVessel({
  id: 'v-skiff',
  name: 'Harbor Skiff',
  compartments: [
    { id: 'c-fore', name: 'Fore hold', capacityKg: 400 },
    { id: 'c-aft', name: 'Aft hold', capacityKg: 600 },
  ],
  inspection: { status: 'cleared', recordedAtUtc: '2030-01-01T06:00:00Z' },
});

const allocator = createAllocatorForVessel(vessel);

function showLedger(label) {
  const totals = allocator.totals();
  console.log(`\n${label}: ${totals.usedKg} kg used of ${totals.capacityKg} kg`);
  for (const line of allocator.ledgers()) {
    console.log(
      `  ${line.compartmentId}: ${line.usedKg} / ${line.capacityKg} kg ` +
        `(${line.capacityKg - line.usedKg} kg free)`,
    );
  }
}

showLedger('empty hull');

// --- 1. One booking spread across both holds, atomically. ---------------
allocator.reserve({
  id: 'r-1',
  bookingId: 'b-1',
  lines: [
    { compartmentId: 'c-fore', cargoClass: 'class-dry', massKg: 250 },
    { compartmentId: 'c-aft', cargoClass: 'class-dry', massKg: 300 },
  ],
});
showLedger('after b-1');

// --- 2. A booking that cannot fit is refused as a whole. ----------------
try {
  allocator.reserve({
    id: 'r-2',
    bookingId: 'b-2',
    lines: [
      { compartmentId: 'c-fore', cargoClass: 'class-dry', massKg: 200 },
      { compartmentId: 'c-aft', cargoClass: 'class-dry', massKg: 400 },
    ],
  });
} catch (error) {
  console.log(`\nrefused b-2: ${error.message}`);
}
showLedger('after the refused b-2 (nothing changed)');

// --- 3. Bookings that do not fit join a stable waitlist. ----------------
allocator.enqueue(
  { bookingId: 'b-3', lines: [{ compartmentId: 'c-aft', cargoClass: 'class-dry', massKg: 500 }] },
  { ms: Date.parse('2030-01-01T07:00:00Z'), utc: '2030-01-01T07:00:00.000Z' },
);
allocator.enqueue(
  { bookingId: 'b-4', lines: [{ compartmentId: 'c-aft', cargoClass: 'class-dry', massKg: 200 }] },
  { ms: Date.parse('2030-01-01T07:05:00Z'), utc: '2030-01-01T07:05:00.000Z' },
);
console.log('\nwaitlist:');
for (const waiter of allocator.waitlist()) {
  console.log(`  #${waiter.ticket} ${waiter.bookingId} wants ${waiter.totalKg} kg in the aft hold`);
}

// Only b-4 fits right now; b-3 keeps its place at the head.
const first = allocator.drain();
console.log(`\nfirst drain booked: ${first.booked.map((r) => r.bookingId).join(', ') || 'none'}`);
console.log(`still waiting: ${first.waiting.map((w) => `${w.bookingId} (ticket #${w.ticket})`).join(', ')}`);
showLedger('after first drain');

// --- 4. Cancelling b-1 frees both holds and promotes b-3. ---------------
allocator.release('r-1');
console.log('\nreleased b-1');

const second = allocator.drain();
console.log(`second drain booked: ${second.booked.map((r) => r.bookingId).join(', ') || 'none'}`);
showLedger('after second drain');

