/**
 * The route graph.
 *
 * The cooperative's network is a directed graph of ports joined by legs. A
 * leg is one hop from an origin port to a destination port with an explicit
 * transit time. Legs are directed: a leg from A to B says nothing about B to
 * A. Callers that need both directions add two legs.
 *
 * On top of the graph:
 *
 *  - **Closures** suspend a leg for a half-open UTC window `[from, to)`. A leg
 *    is usable for a departure only if that departure falls outside every
 *    closure on it.
 *  - **Itineraries** are shortest feasible paths from an origin to a
 *    destination, measured in total transit milliseconds. Ties are broken
 *    deterministically by port visitation order, never by insertion order or
 *    by anything inferred from opaque ids.
 *
 * Existing invariants are preserved: port ids and leg ids are opaque, times are
 * caller-supplied UTC instants, and transit durations are non-negative safe
 * integers (never floats, never wall-clock derived).
 */

import { assertOpaqueId } from './ids.js';
import { assertPortId } from '../ports.js';
import { instant } from './time.js';

/**
 * @typedef {object} Leg
 * @property {string} id opaque leg id
 * @property {string} fromPortId
 * @property {string} toPortId
 * @property {number} transitMs explicit transit time in integer milliseconds
 */

/**
 * @typedef {object} Closure
 * @property {string} id opaque closure id
 * @property {string} legId
 * @property {Readonly<import('./time.js').Instant>} from
 * @property {Readonly<import('./time.js').Instant>} to
 * @property {string|null} reason
 */

const MS_PER_MINUTE = 60_000;
const MS_PER_HOUR = 60 * MS_PER_MINUTE;
const MS_PER_DAY = 24 * MS_PER_HOUR;

/**
 * Assert a transit duration is a non-negative safe integer number of
 * milliseconds. A zero transit time is allowed (a single quay moved along),
 * but negative or fractional durations are not.
 *
 * @param {string} label
 * @param {unknown} value
 * @returns {number}
 */
export function assertTransitMs(label, value) {
  if (typeof value !== 'number' || !Number.isInteger(value)) {
    throw new TypeError(`${label} must be an integer number of milliseconds`);
  }
  if (!Number.isSafeInteger(value)) {
    throw new RangeError(`${label} is not a safe integer`);
  }
  if (value < 0) {
    throw new RangeError(`${label} must not be negative`);
  }
  return value;
}

/**
 * Build a transit duration from whole minutes, hours or days. These are the
 * units operators actually quote; the graph stores integer milliseconds.
 *
 * @param {{ minutes?: number, hours?: number, days?: number }} parts
 * @returns {number}
 */
export function transit(parts) {
  if (parts === null || typeof parts !== 'object') {
    throw new TypeError('transit parts must be an object');
  }
  const { minutes = 0, hours = 0, days = 0 } = parts;
  for (const [label, value] of [
    ['transit minutes', minutes],
    ['transit hours', hours],
    ['transit days', days],
  ]) {
    if (!Number.isInteger(value) || value < 0) {
      throw new RangeError(`${label} must be a non-negative integer`);
    }
  }
  return minutes * MS_PER_MINUTE + hours * MS_PER_HOUR + days * MS_PER_DAY;
}

/**
 * Define a directed leg.
 *
 * @param {{ id: string, fromPortId: string, toPortId: string, transitMs: number }} spec
 * @returns {Readonly<Leg>}
 */
export function defineLeg(spec) {
  if (spec === null || typeof spec !== 'object') {
    throw new TypeError('leg spec must be an object');
  }
  const id = assertOpaqueId('leg id', spec.id);
  const fromPortId = assertPortId(spec.fromPortId);
  const toPortId = assertPortId(spec.toPortId);
  if (fromPortId === toPortId) {
    throw new RangeError(`leg ${id} must connect two different ports`);
  }
  const transitMs = assertTransitMs('leg transitMs', spec.transitMs);
  return Object.freeze({ id, fromPortId, toPortId, transitMs });
}

/**
 * Define a closure over a leg for the half-open UTC window `[fromUtc, toUtc)`.
 *
 * @param {{ id: string, legId: string, fromUtc: string, toUtc: string, reason?: string }} spec
 * @returns {Readonly<Closure>}
 */
export function defineClosure(spec) {
  if (spec === null || typeof spec !== 'object') {
    throw new TypeError('closure spec must be an object');
  }
  const id = assertOpaqueId('closure id', spec.id);
  const legId = assertOpaqueId('leg id', spec.legId);
  const from = instant(spec.fromUtc);
  const to = instant(spec.toUtc);
  if (to.ms <= from.ms) {
    throw new RangeError(`closure ${id} must end after it starts`);
  }
  if (spec.reason !== undefined && typeof spec.reason !== 'string') {
    throw new TypeError('closure reason must be a string');
  }
  const reason = spec.reason === undefined || spec.reason.length === 0 ? null : spec.reason;
  return Object.freeze({ id, legId, from, to, reason });
}

/**
 * Whether a UTC instant falls inside a closure window. Half-open: a
 * departure exactly at `from` is blocked; a departure exactly at `to` is not.
 *
 * @param {Readonly<Closure>} closure
 * @param {Readonly<import('./time.js').Instant>} departure
 * @returns {boolean}
 */
export function closureBlocks(closure, departure) {
  return departure.ms >= closure.from.ms && departure.ms < closure.to.ms;
}

/**
 * Create a route graph from directed legs and optional closures.
 *
 * @param {{
 *   legs: ReadonlyArray<{ id: string, fromPortId: string, toPortId: string, transitMs: number }>,
 *   closures?: ReadonlyArray<{ id: string, legId: string, fromUtc: string, toUtc: string, reason?: string }>,
 * }} spec
 * @returns {Readonly<object>}
 */
export function createRouteGraph(spec) {
  if (spec === null || typeof spec !== 'object') {
    throw new TypeError('route graph spec must be an object');
  }
  if (!Array.isArray(spec.legs)) {
    throw new TypeError('route graph legs must be an array');
  }

  /** @type {Map<string, Readonly<Leg>>} */
  const legs = new Map();
  /** @type {Map<string, Leg[]>} outgoing legs by origin port */
  const outgoing = new Map();

  for (const legSpec of spec.legs) {
    const leg = defineLeg(legSpec);
    if (legs.has(leg.id)) {
      throw new RangeError(`duplicate leg id: ${leg.id}`);
    }
    legs.set(leg.id, leg);
    const list = outgoing.get(leg.fromPortId);
    if (list === undefined) {
      outgoing.set(leg.fromPortId, [leg]);
    } else {
      list.push(leg);
    }
  }

  // Deterministic adjacency: sort each port's legs by (destination, id) so the
  // search never depends on declaration order.
  for (const list of outgoing.values()) {
    list.sort(compareLegs);
  }

  /** @type {Map<string, Closure[]>} closures by leg id */
  const closures = new Map();
  for (const closureSpec of spec.closures ?? []) {
    const closure = defineClosure(closureSpec);
    if (!legs.has(closure.legId)) {
      throw new RangeError(`closure ${closure.id} names an unknown leg: ${closure.legId}`);
    }
    const list = closures.get(closure.legId);
    if (list === undefined) {
      closures.set(closure.legId, [closure]);
    } else {
      list.push(closure);
    }
  }
  for (const list of closures.values()) {
    list.sort((a, b) => a.from.ms - b.from.ms || compareStrings(a.id, b.id));
  }

  const api = {
    /** @returns {ReadonlyArray<Readonly<Leg>>} */
    legs() {
      return Object.freeze([...legs.values()]);
    },

    /**
     * @param {string} legId
     * @returns {Readonly<Leg>}
     */
    requireLeg(legId) {
      const leg = legs.get(legId);
      if (!leg) {
        throw new RangeError(`unknown leg: ${String(legId)}`);
      }
      return leg;
    },

    /** @returns {ReadonlyArray<Readonly<Closure>>} */
    closures() {
      const all = [];
      for (const list of closures.values()) all.push(...list);
      all.sort((a, b) => compareStrings(a.legId, b.legId) || a.from.ms - b.from.ms);
      return Object.freeze(all);
    },

    /**
     * Closures recorded against a leg.
     *
     * @param {string} legId
     * @returns {ReadonlyArray<Readonly<Closure>>}
     */
    closuresFor(legId) {
      api.requireLeg(legId);
      return Object.freeze([...(closures.get(legId) ?? [])]);
    },

    /**
     * Whether a leg may be used for a departure at the given instant.
     *
     * @param {string} legId
     * @param {Readonly<import('./time.js').Instant>} departure
     * @returns {boolean}
     */
    isLegOpen(legId, departure) {
      requireInstant(departure, 'isLegOpen');
      const leg = api.requireLeg(legId);
      return !isBlocked(leg, closures.get(leg.id) ?? [], departure);
    },

    /**
     * All ports that appear on either end of at least one leg.
     *
     * @returns {ReadonlyArray<string>}
     */
    ports() {
      const seen = new Set();
      for (const leg of legs.values()) {
        seen.add(leg.fromPortId);
        seen.add(leg.toPortId);
      }
      return Object.freeze([...seen].sort(compareStrings));
    },

    /**
     * Find the shortest feasible itinerary from one port to another.
     *
     * Feasibility: the whole trip begins at `departAtUtc`, and each leg must
     * be taken at a moment when that leg is not closed. Transit time is
     * accumulated along the way; after a leg the traveller is at the next port
     * at `departure + transitMs`, which is when the following leg departs.
     *
     * Shortest means the smallest total transit time (including any waiting
     * time forced by a closure). Ties are broken by comparing the sequence of
     * port ids lexicographically, so the answer is deterministic.
     *
     * Returns `{ found: false, reason }` when no feasible itinerary exists.
     *
     * @param {{ fromPortId: string, toPortId: string, departAtUtc: string }} request
     * @returns {
     *   | { found: false, reason: string, fromPortId: string, toPortId: string }
     *   | {
     *       found: true,
     *       fromPortId: string,
     *       toPortId: string,
     *       totalTransitMs: number,
     *       legIds: ReadonlyArray<string>,
     *       portIds: ReadonlyArray<string>,
     *       legs: ReadonlyArray<{ legId: string, fromPortId: string, toPortId: string, departsAtUtc: string, arrivesAtUtc: string, transitMs: number }>,
     *     }
     * }
     */
    shortestItinerary(request) {
      return search(api, request, { outgoing, closures });
    },
  };

  return Object.freeze(api);
}

/**
 * @param {Readonly<Leg>} a
 * @param {Readonly<Leg>} b
 * @returns {number}
 */
function compareLegs(a, b) {
  return compareStrings(a.toPortId, b.toPortId) || compareStrings(a.id, b.id);
}

/**
 * Compare two opaque id strings for deterministic ordering. This is a total
 * order used only to make results stable; it assigns no meaning to the ids.
 *
 * @param {string} a
 * @param {string} b
 * @returns {number}
 */
function compareStrings(a, b) {
  if (a < b) return -1;
  if (a > b) return 1;
  return 0;
}

/**
 * @param {Readonly<Leg>} leg
 * @param {ReadonlyArray<Readonly<Closure>>} legClosures
 * @param {Readonly<import('./time.js').Instant>} departure
 * @returns {boolean}
 */
function isBlocked(leg, legClosures, departure) {
  for (const closure of legClosures) {
    if (closureBlocks(closure, departure)) return true;
  }
  return false;
}

/**
 * @param {unknown} value
 * @param {string} what
 * @returns {void}
 */
function requireInstant(value, what) {
  if (value === null || typeof value !== 'object' || typeof value.ms !== 'number') {
    throw new TypeError(`${what} requires an explicit UTC instant`);
  }
}

/**
 * Deterministic label-setting search.
 *
 * Rather than a binary heap keyed on mutable state, this keeps a sorted
 * frontier and always expands the entry with the best (lowest cost, then
 * lexicographically smallest port path) label. Frontier entries are compared
 * with the same total order used for tie-breaking, so the algorithm is
 * deterministic regardless of insertion order.
 *
 * Because waiting is allowed (you simply take the leg later), a closure never
 * makes a leg permanently unusable: the cost function is monotone in time, so
 * the first time we settle a port with a given cost we have the best label.
 *
 * @param {any} api
 * @param {{ fromPortId: string, toPortId: string, departAtUtc: string }} request
 * @param {{ outgoing: Map<string, Leg[]>, closures: Map<string, Closure[]> }} index
 */
function search(api, request, index) {
  if (request === null || typeof request !== 'object') {
    throw new TypeError('itinerary request must be an object');
  }
  const fromPortId = assertPortId(request.fromPortId);
  const toPortId = assertPortId(request.toPortId);
  const start = instant(request.departAtUtc);

  if (fromPortId === toPortId) {
    return Object.freeze({
      found: false,
      reason: 'origin and destination are the same port',
      fromPortId,
      toPortId,
    });
  }

  /** @type {Map<string, number>} best cost settled for a port */
  const settled = new Map();
  /** @type {Array<{ portId: string, arriveMs: number, path: string[], legIds: string[], departures: number[] }>} */
  const frontier = [
    { portId: fromPortId, arriveMs: start.ms, path: [fromPortId], legIds: [], departures: [] },
  ];

  while (frontier.length > 0) {
    frontier.sort(compareLabels);
    const label = /** @type {typeof frontier[number]} */ (frontier.shift());
    if (label.portId === toPortId) {
      return finalise(label, start, fromPortId, toPortId, index);
    }
    const known = settled.get(label.portId);
    if (known !== undefined && known <= label.arriveMs) {
      continue;
    }
    settled.set(label.portId, label.arriveMs);

    for (const leg of index.outgoing.get(label.portId) ?? []) {
      const departure = label.arriveMs;
      if (isBlocked(leg, index.closures.get(leg.id) ?? [], { ms: departure })) {
        // Waiting: take the same leg after the last closure on it ends.
        const reopen = nextOpening(index.closures.get(leg.id) ?? [], departure);
        if (reopen === null) continue;
        const waitMs = reopen - departure;
        if (!Number.isSafeInteger(label.arriveMs + waitMs)) continue;
        push(
          frontier,
          label,
          leg,
          reopen,
          label.arriveMs + waitMs + leg.transitMs,
          waitMs,
        );
        continue;
      }
      push(frontier, label, leg, departure, departure + leg.transitMs, 0);
    }
  }

  return Object.freeze({
    found: false,
    reason: `no feasible route from ${fromPortId} to ${toPortId}`,
    fromPortId,
    toPortId,
  });
}

/**
 * @param {Array<any>} frontier
 * @param {any} label
 * @param {Readonly<Leg>} leg
 * @param {number} departureMs
 * @param {number} arrivalMs
 * @param {number} waitedMs
 * @returns {void}
 */
function push(frontier, label, leg, departureMs, arrivalMs, waitedMs) {
  if (!Number.isSafeInteger(departureMs) || !Number.isSafeInteger(arrivalMs)) {
    return;
  }
  frontier.push({
    portId: leg.toPortId,
    arriveMs: arrivalMs,
    path: [...label.path, leg.toPortId],
    legIds: [...label.legIds, leg.id],
    departures: [...label.departures, { departsMs: departureMs, waitedMs }],
    costMs: arrivalMs,
  });
}

/**
 * The instant at which a leg becomes usable again after `fromMs`, or `null`
 * if no closure on it is relevant.
 *
 * @param {ReadonlyArray<Readonly<Closure>>} legClosures
 * @param {number} fromMs
 * @returns {number|null}
 */
function nextOpening(legClosures, fromMs) {
  let opening = null;
  for (const closure of legClosures) {
    if (fromMs >= closure.from.ms && fromMs < closure.to.ms) {
      if (opening === null || closure.to.ms > opening) opening = closure.to.ms;
    }
  }
  return opening;
}

/**
 * Total order for frontier labels: cost first (arrival instant), then the
 * port path lexicographically.
 *
 * @param {any} a
 * @param {any} b
 * @returns {number}
 */
function compareLabels(a, b) {
  if (a.arriveMs !== b.arriveMs) return a.arriveMs - b.arriveMs;
  const length = Math.min(a.path.length, b.path.length);
  for (let i = 0; i < length; i += 1) {
    const order = compareStrings(a.path[i], b.path[i]);
    if (order !== 0) return order;
  }
  if (a.path.length !== b.path.length) return a.path.length - b.path.length;
  return compareStrings(a.legIds.join('\u0000'), b.legIds.join('\u0000'));
}

/**
 * @param {any} label
 * @param {Readonly<import('./time.js').Instant>} start
 * @param {string} fromPortId
 * @param {string} toPortId
 * @param {{ closures: Map<string, Closure[]> }} index
 */
function finalise(label, start, fromPortId, toPortId, index) {
  const legs = [];
  for (let i = 0; i < label.legIds.length; i += 1) {
    const legId = label.legIds[i];
    const step = label.departures[i];
    const leg = index.legsById ? index.legsById.get(legId) : null;
    const resolved = leg ?? resolveLeg(index, legId);
    legs.push(
      Object.freeze({
        legId,
        fromPortId: resolved.fromPortId,
        toPortId: resolved.toPortId,
        departsAtUtc: new Date(step.departsMs).toISOString(),
        arrivesAtUtc: new Date(step.departsMs + resolved.transitMs).toISOString(),
        transitMs: resolved.transitMs,
        waitedMs: step.waitedMs,
      }),
    );
  }
  const totalTransitMs = label.arriveMs - start.ms;
  return Object.freeze({
    found: true,
    fromPortId,
    toPortId,
    totalTransitMs,
    legIds: Object.freeze([...label.legIds]),
    portIds: Object.freeze([...label.path]),
    legs: Object.freeze(legs),
  });
}

/**
 * @param {{ legs?: () => ReadonlyArray<Readonly<Leg>> }} index
 * @param {string} legId
 * @returns {Readonly<Leg>}
 */
function resolveLeg(index, legId) {
  const leg = /** @type {any} */ (index).legsById?.get(legId);
  if (leg) return leg;
  throw new RangeError(`unknown leg during finalisation: ${legId}`);
}

