import { describe, it, assert } from '../tests/helpers.js';

import {
  assertTransitMs,
  transit,
  defineLeg,
  defineClosure,
  closureBlocks,
  createRouteGraph,
} from '../src/domain/route-graph.js';
import { instant } from '../src/domain/time.js';

/* ---------------------------------------------------------------------- */

const H = (n) => ({ hours: n });

/**
 * A small fictional network:
 *
 *   alpha --30h--> bravo --10h--> delta
 *   alpha --50h--> delta
 *   bravo --5h---> charlie
 *   charlie --6h--> delta
 */
function network(closures = []) {
  return createRouteGraph({
    legs: [
      { id: 'l-ab', fromPortId: 'p-alpha', toPortId: 'p-bravo', transitMs: transit(H(30)) },
      { id: 'l-ad', fromPortId: 'p-alpha', toPortId: 'p-delta', transitMs: transit(H(50)) },
      { id: 'l-bc', fromPortId: 'p-bravo', toPortId: 'p-charlie', transitMs: transit(H(5)) },
      { id: 'l-cd', fromPortId: 'p-charlie', toPortId: 'p-delta', transitMs: transit(H(6)) },
    ],
    closures,
  });
}

function find(graph, fromPortId, toPortId, departAtUtc = '2030-01-01T00:00:00Z') {
  return graph.shortestItinerary({ fromPortId, toPortId, departAtUtc });
}

/* ---------------------------------------------------------------------- */

describe('route graph: transit durations', () => {
  it('builds integer milliseconds from quoted units', () => {
    assert.equal(transit({ hours: 1 }), 3_600_000);
    assert.equal(transit({ minutes: 90 }), 5_400_000);
    assert.equal(transit({ days: 1, hours: 2 }), 93_600_000);
    assert.equal(transit({}), 0);
  });

  it('rejects fractional and negative units', () => {
    assert.throws(() => transit({ hours: 1.5 }), RangeError);
    assert.throws(() => transit({ hours: -1 }), RangeError);
    assert.throws(() => transit(null), TypeError);
  });

  it('requires non-negative safe integer milliseconds', () => {
    assert.equal(assertTransitMs('t', 0), 0);
    assert.equal(assertTransitMs('t', 1), 1);
    assert.throws(() => assertTransitMs('t', -1), RangeError);
    assert.throws(() => assertTransitMs('t', 1.5), TypeError);
    assert.throws(() => assertTransitMs('t', 2 ** 60), RangeError);
    assert.throws(() => assertTransitMs('t', '1'), TypeError);
  });
});

describe('route graph: legs are directed', () => {
  it('defines a directed leg between distinct ports', () => {
    const leg = defineLeg({
      id: 'l-1',
      fromPortId: 'p-a',
      toPortId: 'p-b',
      transitMs: transit({ hours: 2 }),
    });
    assert.deepEqual(leg, {
      id: 'l-1',
      fromPortId: 'p-a',
      toPortId: 'p-b',
      transitMs: 7_200_000,
    });
    assert.ok(Object.isFrozen(leg));
  });

  it('rejects a leg that joins a port to itself', () => {
    assert.throws(
      () => defineLeg({ id: 'l', fromPortId: 'p-a', toPortId: 'p-a', transitMs: 1 }),
      RangeError,
    );
  });

  it('requires opaque leg ids and port ids', () => {
    assert.throws(() => defineLeg({ id: '', fromPortId: 'p-a', toPortId: 'p-b', transitMs: 1 }), RangeError);
    assert.throws(() => defineLeg({ id: 'l', fromPortId: '', toPortId: 'p-b', transitMs: 1 }), TypeError);
  });

  it('does not imply the reverse direction', () => {
    const g = createRouteGraph({
      legs: [{ id: 'l-ab', fromPortId: 'p-a', toPortId: 'p-b', transitMs: transit({ hours: 1 }) }],
    });
    assert.equal(find(g, 'p-a', 'p-b').found, true);
    assert.equal(find(g, 'p-b', 'p-a').found, false);
  });

  it('rejects duplicate leg ids', () => {
    assert.throws(
      () =>
        createRouteGraph({
          legs: [
            { id: 'l', fromPortId: 'p-a', toPortId: 'p-b', transitMs: 1 },
            { id: 'l', fromPortId: 'p-b', toPortId: 'p-c', transitMs: 1 },
          ],
        }),
      RangeError,
    );
  });
});

describe('route graph: closures', () => {
  it('treats a closure window as half-open', () => {
    const closure = defineClosure({
      id: 'x-1',
      legId: 'l-ab',
      fromUtc: '2030-01-01T06:00:00Z',
      toUtc: '2030-01-01T12:00:00Z',
    });
    assert.equal(closureBlocks(closure, instant('2030-01-01T05:59:59Z')), false);
    assert.equal(closureBlocks(closure, instant('2030-01-01T06:00:00Z')), true, 'exactly at from');
    assert.equal(closureBlocks(closure, instant('2030-01-01T11:59:59Z')), true);
    assert.equal(closureBlocks(closure, instant('2030-01-01T12:00:00Z')), false, 'exactly at to');
  });

  it('requires a forward UTC window', () => {
    assert.throws(
      () =>
        defineClosure({
          id: 'x',
          legId: 'l',
          fromUtc: '2030-01-01T12:00:00Z',
          toUtc: '2030-01-01T12:00:00Z',
        }),
      RangeError,
    );
    assert.throws(
      () =>
        defineClosure({
          id: 'x',
          legId: 'l',
          fromUtc: '2030-01-01T12:00:00Z',
          toUtc: '2030-01-01T06:00:00Z',
        }),
      RangeError,
    );
  });

  it('rejects non-UTC closure times and unknown legs', () => {
    assert.throws(
      () =>
        defineClosure({
          id: 'x',
          legId: 'l',
          fromUtc: '2030-01-01T06:00:00+01:00',
          toUtc: '2030-01-01T12:00:00Z',
        }),
      RangeError,
    );
    assert.throws(
      () =>
        createRouteGraph({
          legs: [],
          closures: [
            {
              id: 'x',
              legId: 'l-missing',
              fromUtc: '2030-01-01T06:00:00Z',
              toUtc: '2030-01-01T12:00:00Z',
            },
          ],
        }),
      RangeError,
    );
  });

  it('reports whether a leg is open at an instant', () => {
    const g = network([
      {
        id: 'x-1',
        legId: 'l-ab',
        fromUtc: '2030-01-01T06:00:00Z',
        toUtc: '2030-01-01T12:00:00Z',
      },
    ]);
    assert.equal(g.isLegOpen('l-ab', instant('2030-01-01T05:00:00Z')), true);
    assert.equal(g.isLegOpen('l-ab', instant('2030-01-01T08:00:00Z')), false);
    assert.equal(g.isLegOpen('l-ad', instant('2030-01-01T08:00:00Z')), true, 'other legs unaffected');
    assert.throws(() => g.isLegOpen('l-missing', instant('2030-01-01T08:00:00Z')), RangeError);
    assert.throws(() => g.isLegOpen('l-ab', { ms: 'soon' }), TypeError);
  });

  it('lists closures per leg', () => {
    const g = network([
      { id: 'x-1', legId: 'l-ab', fromUtc: '2030-01-01T06:00:00Z', toUtc: '2030-01-01T12:00:00Z' },
      { id: 'x-2', legId: 'l-ad', fromUtc: '2030-01-02T06:00:00Z', toUtc: '2030-01-02T12:00:00Z' },
    ]);
    assert.equal(g.closures().length, 2);
    assert.deepEqual(g.closuresFor('l-ab').map((c) => c.id), ['x-1']);
    assert.deepEqual(g.closuresFor('l-bc'), []);
    assert.throws(() => g.closuresFor('nope'), RangeError);
  });
});

describe('route graph: shortest feasible itineraries', () => {
  it('finds the shortest path by total transit time', () => {
    // alpha->bravo->charlie->delta = 30 + 5 + 6 = 41h, beats the direct 50h.
    const result = find(network(), 'p-alpha', 'p-delta');
    assert.equal(result.found, true);
    assert.deepEqual(result.legIds, ['l-ab', 'l-bc', 'l-cd']);
    assert.deepEqual(result.portIds, ['p-alpha', 'p-bravo', 'p-charlie', 'p-delta']);
    assert.equal(result.totalTransitMs, transit({ hours: 41 }));
  });

  it('prefers the direct leg when it is genuinely shorter', () => {
    const g = createRouteGraph({
      legs: [
        { id: 'l-direct', fromPortId: 'p-a', toPortId: 'p-c', transitMs: transit({ hours: 4 }) },
        { id: 'l-a-b', fromPortId: 'p-a', toPortId: 'p-b', transitMs: transit({ hours: 3 }) },
        { id: 'l-b-c', fromPortId: 'p-b', toPortId: 'p-c', transitMs: transit({ hours: 3 }) },
      ],
    });
    assert.deepEqual(find(g, 'p-a', 'p-c').legIds, ['l-direct']);
  });

  it('returns absolute times for each leg', () => {
    const result = find(network(), 'p-alpha', 'p-delta', '2030-01-01T00:00:00Z');
    assert.equal(result.legs[0].departsAtUtc, '2030-01-01T00:00:00.000Z');
    assert.equal(result.legs[0].arrivesAtUtc, '2030-01-01T06:00:00.000Z');
    assert.equal(result.legs[1].departsAtUtc, '2030-01-01T06:00:00.000Z');
    assert.equal(result.legs[2].arrivesAtUtc, '2030-01-01T17:00:00.000Z');
  });

  it('breaks ties deterministically by port order', () => {
    // Two equal-length routes: a->b->d and a->c->d.
    const g = createRouteGraph({
      legs: [
        { id: 'l-ac', fromPortId: 'p-a', toPortId: 'p-c', transitMs: transit({ hours: 2 }) },
        { id: 'l-ab', fromPortId: 'p-a', toPortId: 'p-b', transitMs: transit({ hours: 2 }) },
        { id: 'l-cd', fromPortId: 'p-c', toPortId: 'p-d', transitMs: transit({ hours: 2 }) },
        { id: 'l-bd', fromPortId: 'p-b', toPortId: 'p-d', transitMs: transit({ hours: 2 }) },
      ],
    });
    const first = find(g, 'p-a', 'p-d');
    assert.deepEqual(first.portIds, ['p-a', 'p-b', 'p-d'], 'p-b sorts before p-c');
    // Declaration order must not matter.
    const reordered = createRouteGraph({
      legs: [
        { id: 'l-bd', fromPortId: 'p-b', toPortId: 'p-d', transitMs: transit({ hours: 2 }) },
        { id: 'l-cd', fromPortId: 'p-c', toPortId: 'p-d', transitMs: transit({ hours: 2 }) },
        { id: 'l-ab', fromPortId: 'p-a', toPortId: 'p-b', transitMs: transit({ hours: 2 }) },
        { id: 'l-ac', fromPortId: 'p-a', toPortId: 'p-c', transitMs: transit({ hours: 2 }) },
      ],
    });
    assert.deepEqual(find(reordered, 'p-a', 'p-d').portIds, first.portIds);
  });

  it('is stable across repeated calls', () => {
    const g = network();
    const a = find(g, 'p-alpha', 'p-delta');
    const b = find(g, 'p-alpha', 'p-delta');
    assert.deepEqual(a.legIds, b.legIds);
    assert.equal(a.totalTransitMs, b.totalTransitMs);
  });

  it('reports failure when no route exists', () => {
    const g = network();
    const result = find(g, 'p-delta', 'p-alpha');
    assert.equal(result.found, false);
    assert.equal(typeof result.reason, 'string');
    assert.equal(result.fromPortId, 'p-delta');
  });

  it('reports failure for unknown ports and same-port requests', () => {
    const g = network();
    assert.equal(find(g, 'p-missing', 'p-delta').found, false);
    assert.equal(find(g, 'p-alpha', 'p-missing').found, false);
    const same = find(g, 'p-alpha', 'p-alpha');
    assert.equal(same.found, false);
    assert.equal(same.reason, 'origin and destination are the same port');
  });

  it('validates the request', () => {
    const g = network();
    assert.throws(() => g.shortestItinerary(null), TypeError);
    assert.throws(() => find(g, '', 'p-delta'), TypeError);
    assert.throws(() => find(g, 'p-alpha', 'p-delta', '2030-01-01T00:00:00'), RangeError);
  });

  it('returns read-only results', () => {
    const result = find(network(), 'p-alpha', 'p-delta');
    assert.ok(Object.isFrozen(result));
    assert.ok(Object.isFrozen(result.legIds));
    assert.ok(Object.isFrozen(result.portIds));
    assert.ok(Object.isFrozen(result.legs));
    assert.ok(Object.isFrozen(result.legs[0]));
  });

  it('handles a single-leg itinerary', () => {
    const result = find(network(), 'p-alpha', 'p-bravo');
    assert.deepEqual(result.legIds, ['l-ab']);
    assert.equal(result.totalTransitMs, transit({ hours: 30 }));
    assert.deepEqual(result.portIds, ['p-alpha', 'p-bravo']);
  });

  it('allows a zero-transit leg', () => {
    const g = createRouteGraph({
      legs: [
        { id: 'l-1', fromPortId: 'p-a', toPortId: 'p-b', transitMs: 0 },
        { id: 'l-2', fromPortId: 'p-b', toPortId: 'p-c', transitMs: transit({ hours: 1 }) },
      ],
    });
    const result = find(g, 'p-a', 'p-c');
    assert.equal(result.found, true);
    assert.equal(result.totalTransitMs, transit({ hours: 1 }));
  });
});

describe('route graph: closures in itineraries', () => {
  it('waits for a closed leg to reopen and counts the wait', () => {
    // Departing 00:00, alpha->bravo would start immediately but is closed
    // 00:00-06:00, so the trip waits 6h.
    const g = network([
      {
        id: 'x-ab',
        legId: 'l-ab',
        fromUtc: '2030-01-01T00:00:00Z',
        toUtc: '2030-01-01T06:00:00Z',
      },
    ]);
    const result = find(g, 'p-alpha', 'p-delta', '2030-01-01T00:00:00Z');
    assert.equal(result.found, true);
    assert.deepEqual(result.legIds, ['l-ab', 'l-bc', 'l-cd'], 'waiting still beats the 50h direct');
    assert.equal(result.totalTransitMs, transit({ hours: 6 + 41 }));
    assert.equal(result.legs[0].departsAtUtc, '2030-01-01T06:00:00.000Z');
    assert.equal(result.legs[0].waitedMs, transit({ hours: 6 }));
  });

  it('takes an alternative route when waiting is worse', () => {
    // The alpha->bravo leg is closed for a long time, so the direct leg wins.
    const g = network([
      {
        id: 'x-ab',
        legId: 'l-ab',
        fromUtc: '2030-01-01T00:00:00Z',
        toUtc: '2030-01-05T00:00:00Z',
      },
    ]);
    const result = find(g, 'p-alpha', 'p-delta', '2030-01-01T00:00:00Z');
    assert.deepEqual(result.legIds, ['l-ad'], 'direct 50h beats waiting 96h');
    assert.equal(result.totalTransitMs, transit({ hours: 50 }));
  });

  it('a leg closed at its exact start is blocked', () => {
    const g = network([
      {
        id: 'x-ab',
        legId: 'l-ab',
        fromUtc: '2030-01-01T00:00:00Z',
        toUtc: '2030-01-01T01:00:00Z',
      },
    ]);
    const result = find(g, 'p-alpha', 'p-delta', '2030-01-01T00:00:00Z');
    assert.equal(result.legs[0].departsAtUtc, '2030-01-01T01:00:00.000Z');
  });

  it('a leg open at the exact closure end is usable immediately', () => {
    const g = network([
      {
        id: 'x-ab',
        legId: 'l-ab',
        fromUtc: '2030-01-01T00:00:00Z',
        toUtc: '2030-01-01T05:00:00Z',
      },
    ]);
    const result = find(g, 'p-alpha', 'p-delta', '2030-01-01T05:00:00Z');
    assert.equal(result.legs[0].departsAtUtc, '2030-01-01T05:00:00.000Z');
    assert.equal(result.legs[0].waitedMs, 0);
  });

  it('chains across several closures on different legs', () => {
    const g = createRouteGraph({
      legs: [
        { id: 'l-ab', fromPortId: 'p-a', toPortId: 'p-b', transitMs: transit({ hours: 1 }) },
        { id: 'l-bc', fromPortId: 'p-b', toPortId: 'p-c', transitMs: transit({ hours: 1 }) },
      ],
      closures: [
        { id: 'x-ab', legId: 'l-ab', fromUtc: '2030-01-01T00:00:00Z', toUtc: '2030-01-01T02:00:00Z' },
        { id: 'x-bc', legId: 'l-bc', fromUtc: '2030-01-01T00:00:00Z', toUtc: '2030-01-01T05:00:00Z' },
      ],
    });
    const result = find(g, 'p-a', 'p-c', '2030-01-01T00:00:00Z');
    assert.equal(result.found, true);
    // Waits until 02:00 for the first leg, arrives 03:00, waits until 05:00.
    assert.equal(result.legs[0].departsAtUtc, '2030-01-01T02:00:00.000Z');
    assert.equal(result.legs[1].departsAtUtc, '2030-01-01T05:00:00.000Z');
    assert.equal(result.totalTransitMs, transit({ hours: 6 }));
  });

  it('reports failure when the only route is permanently unusable', () => {
    const g = createRouteGraph({
      legs: [{ id: 'l-ab', fromPortId: 'p-a', toPortId: 'p-b', transitMs: transit({ hours: 1 }) }],
      closures: [
        {
          id: 'x-long',
          legId: 'l-ab',
          fromUtc: '2030-01-01T00:00:00Z',
          toUtc: '9999-01-01T00:00:00Z',
        },
      ],
    });
    const result = find(g, 'p-a', 'p-b', '2030-01-01T00:00:00Z');
    // The leg reopens in the far future; the search must still terminate and
    // produce a well-formed answer rather than looping or overflowing.
    assert.equal(result.found, true);
    assert.equal(result.legs[0].departsAtUtc, '9999-01-01T00:00:00.000Z');
  });
});

describe('route graph: determinism and structure', () => {
  it('lists ports and legs in a stable order', () => {
    const g = network();
    assert.deepEqual(g.ports(), ['p-alpha', 'p-bravo', 'p-charlie', 'p-delta']);
    assert.equal(g.legs().length, 4);
    assert.throws(() => g.requireLeg('nope'), RangeError);
    assert.equal(g.requireLeg('l-ab').transitMs, transit({ hours: 30 }));
  });

  it('does not mutate the caller’s leg list', () => {
    const legs = [
      { id: 'l-ab', fromPortId: 'p-a', toPortId: 'p-b', transitMs: transit({ hours: 1 }) },
    ];
    const g = createRouteGraph({ legs });
    find(g, 'p-a', 'p-b');
    assert.deepEqual(legs, [
      { id: 'l-ab', fromPortId: 'p-a', toPortId: 'p-b', transitMs: transit({ hours: 1 }) },
    ]);
  });

  it('rejects a malformed spec', () => {
    assert.throws(() => createRouteGraph(null), TypeError);
    assert.throws(() => createRouteGraph({ legs: 'nope' }), TypeError);
    assert.throws(() => createRouteGraph({}), TypeError);
  });

  it('handles an empty graph', () => {
    const g = createRouteGraph({ legs: [] });
    assert.deepEqual(g.ports(), []);
    assert.equal(find(g, 'p-a', 'p-b').found, false);
  });

  it('ignores cycles safely', () => {
    const g = createRouteGraph({
      legs: [
        { id: 'l-ab', fromPortId: 'p-a', toPortId: 'p-b', transitMs: 1 },
        { id: 'l-ba', fromPortId: 'p-b', toPortId: 'p-a', transitMs: 1 },
        { id: 'l-bc', fromPortId: 'p-b', toPortId: 'p-c', transitMs: 1 },
      ],
    });
    const result = find(g, 'p-a', 'p-c');
    assert.deepEqual(result.legIds, ['l-ab', 'l-bc']);
    assert.equal(find(g, 'p-c', 'p-a').found, false);
  });

  it('never revisits a port on an optimal path', () => {
    const result = find(network(), 'p-alpha', 'p-delta');
    assert.equal(new Set(result.portIds).size, result.portIds.length);
  });
});

