/**
 * Operator example: finding the shortest feasible itinerary.
 *
 * Fictional data only. Run with: node examples/route-graph-example.js
 *
 * Deterministic: the departure time is supplied here, so the output is
 * identical on every run.
 */

import { createRouteGraph, transit } from '../src/index.js';

const graph = createRouteGraph({
  legs: [
    { id: 'l-north-bravo', fromPortId: 'p-north', toPortId: 'p-bravo', transitMs: transit({ hours: 8 }) },
    { id: 'l-bravo-south', fromPortId: 'p-bravo', toPortId: 'p-south', transitMs: transit({ hours: 5 }) },
    { id: 'l-north-south', fromPortId: 'p-north', toPortId: 'p-south', transitMs: transit({ hours: 20 }) },
    // A one-way leg: there is no south -> north leg in this network.
    { id: 'l-south-east', fromPortId: 'p-south', toPortId: 'p-east', transitMs: transit({ hours: 3 }) },
  ],
  closures: [
    {
      id: 'x-bravo-dredge',
      legId: 'l-bravo-south',
      fromUtc: '2030-01-01T00:00:00Z',
      toUtc: '2030-01-01T04:00:00Z',
      reason: 'dredging',
    },
  ],
});

function describeItinerary(result) {
  if (!result.found) {
    console.log(`  no route: ${result.reason}`);
    return;
  }
  const hours = result.totalTransitMs / 3_600_000;
  console.log(`  total ${hours} h via ${result.portIds.join(' -> ')}`);
  for (const leg of result.legs) {
    const wait = leg.waitedMs > 0 ? ` (waited ${leg.waitedMs / 3_600_000} h)` : '';
    console.log(`    ${leg.legId}: ${leg.departsAtUtc} -> ${leg.arrivesAtUtc}${wait}`);
  }
}

console.log('north -> south, departing 2030-01-01T00:00Z:');
describeItinerary(
  graph.shortestItinerary({
    fromPortId: 'p-north',
    toPortId: 'p-south',
    departAtUtc: '2030-01-01T00:00:00Z',
  }),
);

// Departing after the dredging closes, the short route needs no wait.
console.log('\nnorth -> south, departing 2030-01-01T06:00Z:');
describeItinerary(
  graph.shortestItinerary({
    fromPortId: 'p-north',
    toPortId: 'p-south',
    departAtUtc: '2030-01-01T06:00:00Z',
  }),
);

console.log('\nsouth -> north (no such directed leg):');
describeItinerary(
  graph.shortestItinerary({
    fromPortId: 'p-south',
    toPortId: 'p-north',
    departAtUtc: '2030-01-01T06:00:00Z',
  }),
);

console.log(`\nports in the network: ${graph.ports().join(', ')}`);

