/**
 * Cargo manifests.
 *
 * A manifest is the loading document for one sailing: an ordered list of
 * lines, each describing cargo to be carried. Manifests sit between
 * consignments (what the cargo is) and the vessel (where it goes), and they
 * add the two safety dimensions freight cannot do without:
 *
 *  1. **Dangerous goods.** A line may declare a dangerous-goods entry with an
 *     opaque hazard class (for example a UN class token like `dg-3`) and an
 *     optional packing group. Hazard classes that may not travel together are
 *     declared as a symmetric table; packing groups must be plausible for the
 *     class (`allowedPackingGroups`).
 *  2. **Cold chain.** A line may require a cold chain with an explicit
 *     temperature range in whole degrees Celsius. Conflicting ranges on the
 *     same sailing are detected, and the manifest records the tightest
 *     working range.
 *
 * Line identity is **stable**: every line carries an opaque line id supplied
 * by the caller, unique within the manifest, and the manifest never renumbers
 * or reorders its lines. Line order is the order the caller declared.
 *
 * Weights are integer kilograms throughout, exactly as everywhere else in
 * Harbor Dispatch: per line, per manifest, and per compartment assignment.
 *
 * Existing invariants are preserved: opaque ids, integer kilograms, and
 * caller-supplied UTC values only (none are generated here).
 */

import { assertOpaqueId } from './ids.js';
import {
  assertKilograms,
  assertPositiveKilograms,
  sumKilograms,
} from './capacity.js';
import {
  assertCargoClass,
  createIncompatibilities,
  classesConflict,
  firstConflict,
} from './vessel-registry.js';

/* -------------------------------------------------------------------------
 * Dangerous goods
 * ---------------------------------------------------------------------- */

/**
 * @typedef {object} DangerousGoods
 * @property {string} hazardClass opaque hazard class token
 * @property {string} packingGroup opaque packing group token
 * @property {string|null} properName operator-facing description
 */

/**
 * Packing groups are opaque tokens too; the domain never infers severity from
 * their text.
 *
 * @param {unknown} value
 * @returns {string}
 */
export function assertPackingGroup(value) {
  return assertOpaqueId('packing group', value);
}

/**
 * Define a dangerous-goods entry for a manifest line.
 *
 * @param {{
 *   hazardClass: string,
 *   packingGroup: string,
 *   properName?: string,
 * }} spec
 * @returns {Readonly<DangerousGoods>}
 */
export function defineDangerousGoods(spec) {
  if (spec === null || typeof spec !== 'object') {
    throw new TypeError('dangerous goods spec must be an object');
  }
  const hazardClass = assertCargoClass('hazard class', spec.hazardClass);
  const packingGroup = assertPackingGroup(spec.packingGroup);
  if (spec.properName !== undefined && typeof spec.properName !== 'string') {
    throw new TypeError('dangerous goods properName must be a string');
  }
  const properName =
    spec.properName === undefined || spec.properName.length === 0 ? null : spec.properName;
  return Object.freeze({ hazardClass, packingGroup, properName });
}

/**
 * Whether a hazard class permits a packing group under a policy table.
 * A policy maps a hazard class to the packing groups it allows. A class with
 * no policy entry imposes no restriction.
 *
 * @param {Readonly<Record<string, ReadonlyArray<string>>>} policy
 * @param {Readonly<DangerousGoods>} goods
 * @returns {boolean}
 */
export function packingGroupAllowed(policy, goods) {
  const allowed = policy[goods.hazardClass];
  if (allowed === undefined) return true;
  return allowed.includes(goods.packingGroup);
}

/**
 * @typedef {object} ManifestPolicy
 * @property {ReadonlyArray<Readonly<{a: string, b: string}>>} hazardIncompatibilities
 * @property {Readonly<Record<string, ReadonlyArray<string>>>} packingGroups
 */

/**
 * Build the compatibility policy for a manifest.
 *
 * @param {{
 *   incompatibilities?: Iterable<readonly [string, string]>,
 *   packingGroups?: Record<string, Iterable<string>>,
 * }} [spec]
 * @returns {Readonly<ManifestPolicy>}
 */
export function createManifestPolicy(spec = {}) {
  if (spec === null || typeof spec !== 'object') {
    throw new TypeError('manifest policy spec must be an object');
  }
  const hazardIncompatibilities = createIncompatibilities(spec.incompatibilities ?? []);

  /** @type {Record<string, ReadonlyArray<string>>} */
  const packingGroups = {};
  const source = spec.packingGroups ?? {};
  if (source === null || typeof source !== 'object') {
    throw new TypeError('packingGroups must be an object of class -> groups');
  }
  for (const hazardClass of Object.keys(source)) {
    const cls = assertCargoClass('hazard class', hazardClass);
    const groups = [...source[hazardClass]].map((g) => assertPackingGroup(g));
    if (groups.length === 0) {
      throw new RangeError(`packing group policy for ${cls} must list at least one group`);
    }
    packingGroups[cls] = Object.freeze([...new Set(groups)]);
  }

  return Object.freeze({
    hazardIncompatibilities,
    packingGroups: Object.freeze(packingGroups),
  });
}

/* -------------------------------------------------------------------------
 * Cold chain
 * ---------------------------------------------------------------------- */

/**
 * @typedef {object} TemperatureRange
 * @property {number} minC inclusive lower bound in whole degrees Celsius
 * @property {number} maxC inclusive upper bound in whole degrees Celsius
 */

/**
 * Whole degrees Celsius. Negative values are legitimate (frozen cargo), but
 * fractions are not: this domain deals in integers.
 *
 * @param {string} label
 * @param {unknown} value
 * @returns {number}
 */
export function assertCelsius(label, value) {
  if (typeof value !== 'number' || !Number.isInteger(value)) {
    throw new TypeError(`${label} must be a whole number of degrees Celsius`);
  }
  if (!Number.isSafeInteger(value)) {
    throw new RangeError(`${label} is not a safe integer`);
  }
  return value;
}

/**
 * Define an inclusive temperature range.
 *
 * @param {{ minC: number, maxC: number }} spec
 * @returns {Readonly<TemperatureRange>}
 */
export function defineTemperatureRange(spec) {
  if (spec === null || typeof spec !== 'object') {
    throw new TypeError('temperature range spec must be an object');
  }
  const minC = assertCelsius('range minC', spec.minC);
  const maxC = assertCelsius('range maxC', spec.maxC);
  if (minC > maxC) {
    throw new RangeError(`temperature range minimum ${minC} exceeds maximum ${maxC}`);
  }
  return Object.freeze({ minC, maxC });
}

/**
 * @typedef {object} ColdChain
 * @property {Readonly<TemperatureRange>} range
 * @property {boolean} monitored whether continuous monitoring is required
 */

/**
 * @param {{ minC: number, maxC: number, monitored?: boolean }} spec
 * @returns {Readonly<ColdChain>}
 */
export function defineColdChain(spec) {
  if (spec === null || typeof spec !== 'object') {
    throw new TypeError('cold chain spec must be an object');
  }
  const range = defineTemperatureRange(spec);
  if (spec.monitored !== undefined && typeof spec.monitored !== 'boolean') {
    throw new TypeError('cold chain monitored must be a boolean');
  }
  return Object.freeze({ range, monitored: spec.monitored === true });
}

/**
 * The overlap of two inclusive ranges, or `null` when they are disjoint.
 * Ranges that merely touch (`[0,2]` and `[2,6]`) do overlap at 2.
 *
 * @param {Readonly<TemperatureRange>} a
 * @param {Readonly<TemperatureRange>} b
 * @returns {Readonly<TemperatureRange>|null}
 */
export function intersectRanges(a, b) {
  const minC = Math.max(a.minC, b.minC);
  const maxC = Math.min(a.maxC, b.maxC);
  if (minC > maxC) return null;
  return Object.freeze({ minC, maxC });
}

/* -------------------------------------------------------------------------
 * Manifest lines
 * ---------------------------------------------------------------------- */

/**
 * @typedef {object} ManifestLine
 * @property {string} id stable opaque line id
 * @property {string} consignmentId
 * @property {string} description
 * @property {number} massKg integer kilograms, strictly positive
 * @property {string} cargoClass
 * @property {Readonly<DangerousGoods>|null} dangerousGoods
 * @property {Readonly<ColdChain>|null} coldChain
 */

/**
 * @param {{
 *   id: string,
 *   consignmentId: string,
 *   description?: string,
 *   massKg: number,
 *   cargoClass?: string,
 *   dangerousGoods?: {
 *     hazardClass: string,
 *     packingGroup: string,
 *     properName?: string,
 *   } | null,
 *   coldChain?: { minC: number, maxC: number, monitored?: boolean } | null,
 * }} spec
 * @returns {Readonly<ManifestLine>}
 */
export function createManifestLine(spec) {
  if (spec === null || typeof spec !== 'object') {
    throw new TypeError('manifest line spec must be an object');
  }
  const id = assertOpaqueId('manifest line id', spec.id);
  const consignmentId = assertOpaqueId('consignment id', spec.consignmentId);
  const massKg = assertPositiveKilograms('manifest line massKg', spec.massKg);
  const cargoClass =
    spec.cargoClass === undefined ? 'class-general' : assertCargoClass('cargo class', spec.cargoClass);

  const dangerousGoods =
    spec.dangerousGoods === undefined || spec.dangerousGoods === null
      ? null
      : defineDangerousGoods(spec.dangerousGoods);
  const coldChain =
    spec.coldChain === undefined || spec.coldChain === null
      ? null
      : defineColdChain(spec.coldChain);

  const description =
    typeof spec.description === 'string' && spec.description.length > 0
      ? spec.description
      : id;

  return Object.freeze({
    id,
    consignmentId,
    description,
    massKg,
    cargoClass,
    dangerousGoods,
    coldChain,
  });
}

/* -------------------------------------------------------------------------
 * Manifests
 * ---------------------------------------------------------------------- */

/**
 * @typedef {object} Manifest
 * @property {string} id opaque manifest id
 * @property {string} sailingId
 * @property {string} vesselId
 * @property {ReadonlyArray<Readonly<ManifestLine>>} lines declaration order
 * @property {number} totalMassKg integer kilograms
 */

/**
 * Create a manifest and check every cross-line rule.
 *
 * All checks run before the manifest is built, so a rejected manifest never
 * exists in a half-formed state. Rules:
 *
 *  - line ids are unique within the manifest (and stable once created);
 *  - no two lines declare hazard classes that may not travel together;
 *  - every declared packing group is permitted for its hazard class;
 *  - every cold-chain line's range overlaps every other cold-chain line's
 *    range, so a single hold temperature can serve them all.
 *
 * @param {{
 *   id: string,
 *   sailingId: string,
 *   vesselId: string,
 *   lines: ReadonlyArray<Parameters<typeof createManifestLine>[0]>,
 *   policy?: Readonly<ManifestPolicy>,
 * }} spec
 * @returns {Readonly<Manifest>}
 */
export function createManifest(spec) {
  if (spec === null || typeof spec !== 'object') {
    throw new TypeError('manifest spec must be an object');
  }
  const id = assertOpaqueId('manifest id', spec.id);
  const sailingId = assertOpaqueId('sailing id', spec.sailingId);
  const vesselId = assertOpaqueId('vessel id', spec.vesselId);
  if (!Array.isArray(spec.lines)) {
    throw new TypeError('manifest lines must be an array');
  }
  const policy = spec.policy ?? createManifestPolicy();

  const seen = new Set();
  const lines = spec.lines.map((lineSpec) => {
    const line = createManifestLine(lineSpec);
    if (seen.has(line.id)) {
      throw new RangeError(`duplicate manifest line id: ${line.id}`);
    }
    seen.add(line.id);
    return line;
  });

  const issues = inspectManifestRules(lines, policy);
  if (issues.length > 0) {
    throw new RangeError(issues[0]);
  }

  return Object.freeze({
    id,
    sailingId,
    vesselId,
    lines: Object.freeze(lines),
    totalMassKg: sumKilograms(lines.map((line) => line.massKg)),
  });
}

/**
 * Report every rule violation in a set of lines. Used both by
 * `createManifest` (which throws the first) and by operators previewing a
 * draft manifest.
 *
 * @param {ReadonlyArray<Readonly<ManifestLine>>} lines
 * @param {Readonly<ManifestPolicy>} policy
 * @returns {ReadonlyArray<string>}
 */
export function inspectManifestRules(lines, policy) {
  /** @type {string[]} */
  const issues = [];

  // Dangerous goods: symmetric hazard-class conflicts across any two lines.
  const hazardClasses = [];
  for (const line of lines) {
    if (line.dangerousGoods === null) continue;
    const candidate = line.dangerousGoods.hazardClass;
    const conflict = firstConflict(policy.hazardIncompatibilities, hazardClasses, candidate);
    if (conflict) {
      issues.push(
        `hazard classes ${conflict.a} and ${conflict.b} may not share a manifest`,
      );
    }
    if (!hazardClasses.includes(candidate)) hazardClasses.push(candidate);
  }

  // Packing groups must be permitted for their class.
  for (const line of lines) {
    if (line.dangerousGoods === null) continue;
    if (!packingGroupAllowed(policy.packingGroups, line.dangerousGoods)) {
      issues.push(
        `packing group ${line.dangerousGoods.packingGroup} is not permitted for ` +
          `hazard class ${line.dangerousGoods.hazardClass}`,
      );
    }
  }

  // Cold chain: every pair of ranges must overlap.
  const chilled = lines.filter((line) => line.coldChain !== null);
  for (let i = 0; i < chilled.length; i += 1) {
    for (let j = i + 1; j < chilled.length; j += 1) {
      const a = /** @type {Readonly<ColdChain>} */ (chilled[i].coldChain);
      const b = /** @type {Readonly<ColdChain>} */ (chilled[j].coldChain);
      if (intersectRanges(a.range, b.range) === null) {
        issues.push(
          `cold chain ranges on lines ${chilled[i].id} and ${chilled[j].id} do not overlap: ` +
            `${formatRange(a.range)} vs ${formatRange(b.range)}`,
        );
      }
    }
  }

  return Object.freeze(issues);
}

/**
 * @param {Readonly<TemperatureRange>} range
 * @returns {string}
 */
export function formatRange(range) {
  return `${range.minC}..${range.maxC} C`;
}

/**
 * The tightest temperature range that satisfies every cold-chain line, or
 * `null` when the manifest has no cold-chain lines.
 *
 * @param {Readonly<Manifest>} manifest
 * @returns {Readonly<TemperatureRange>|null}
 */
export function workingTemperatureRange(manifest) {
  /** @type {Readonly<TemperatureRange>|null} */
  let working = null;
  for (const line of manifest.lines) {
    if (line.coldChain === null) continue;
    working = working === null ? line.coldChain.range : intersectRanges(working, line.coldChain.range);
    if (working === null) {
      throw new RangeError('manifest cold chain ranges do not overlap');
    }
  }
  return working;
}

/**
 * Lines requiring continuous monitoring.
 *
 * @param {Readonly<Manifest>} manifest
 * @returns {ReadonlyArray<Readonly<ManifestLine>>}
 */
export function monitoredLines(manifest) {
  return Object.freeze(manifest.lines.filter((line) => line.coldChain?.monitored === true));
}

/**
 * @param {Readonly<Manifest>} manifest
 * @returns {ReadonlyArray<Readonly<ManifestLine>>}
 */
export function dangerousLines(manifest) {
  return Object.freeze(manifest.lines.filter((line) => line.dangerousGoods !== null));
}

/**
 * Look up a line by its stable id.
 *
 * @param {Readonly<Manifest>} manifest
 * @param {string} lineId
 * @returns {Readonly<ManifestLine>}
 */
export function requireLine(manifest, lineId) {
  const line = manifest.lines.find((candidate) => candidate.id === lineId);
  if (!line) {
    throw new RangeError(`unknown manifest line: ${String(lineId)}`);
  }
  return line;
}

/**
 * Total mass per compartment assignment. `assignments` maps a compartment id
 * to the line ids loaded into it. This is the bridge to the vessel registry's
 * compartment model.
 *
 * @param {Readonly<Manifest>} manifest
 * @param {Record<string, ReadonlyArray<string>>} assignments
 * @returns {Readonly<Record<string, number>>}
 */
export function massByCompartment(manifest, assignments) {
  if (assignments === null || typeof assignments !== 'object' || Array.isArray(assignments)) {
    throw new TypeError('assignments must be an object of compartment id -> line ids');
  }
  /** @type {Record<string, number>} */
  const result = {};
  for (const compartmentId of Object.keys(assignments)) {
    assertOpaqueId('compartment id', compartmentId);
    const lineIds = assignments[compartmentId];
    if (!Array.isArray(lineIds)) {
      throw new TypeError(`assignment for compartment ${compartmentId} must be an array of line ids`);
    }
    const masses = lineIds.map((lineId) => requireLine(manifest, lineId).massKg);
    result[compartmentId] = sumKilograms(masses);
  }
  return Object.freeze(result);
}

/**
 * Assert that a manifest's per-compartment masses fit the compartments given
 * by `{ id, capacityKg }`.
 *
 * @param {Readonly<Manifest>} manifest
 * @param {Record<string, ReadonlyArray<string>>} assignments
 * @param {ReadonlyArray<{ id: string, capacityKg: number }>} compartments
 * @returns {Readonly<Record<string, number>>}
 */
export function assertCompartmentsFit(manifest, assignments, compartments) {
  const masses = massByCompartment(manifest, assignments);
  for (const compartment of compartments) {
    const capacityKg = assertKilograms('compartment capacityKg', compartment?.capacityKg);
    const massKg = masses[compartment.id] ?? 0;
    if (massKg > capacityKg) {
      throw new RangeError(
        `compartment ${compartment.id} overloaded: ${massKg} kg > ${capacityKg} kg`,
      );
    }
  }
  return masses;
}

/**
 * A stable identity for a line: its id plus the manifest it belongs to. Two
 * manifests may reuse a line id, so pairs are what identify a line globally.
 *
 * @param {Readonly<Manifest>} manifest
 * @param {Readonly<ManifestLine>} line
 * @returns {string}
 */
export function lineKey(manifest, line) {
  return `${manifest.id}\u0000${line.id}`;
}

