/**
 * Attach a cargo manifest to a sailing already on the board.
 *
 * The manifest's `sailingId` and `vesselId` are taken from the sailing, so a
 * manifest can never be bound to the wrong hull. If the spec supplies
 * `assignments` (compartment id -> line ids), the per-compartment masses are
 * checked against the vessel's registered compartments when it has them.
 *
 * @param {Board} board
 * @param {{
 *   id: string,
 *   sailingId: string,
 *   lines: ReadonlyArray<any>,
 *   policy?: any,
 *   assignments?: Record<string, ReadonlyArray<string>>,
 * }} spec
 */
function addManifest(board, spec) {
  const sailing = board.sailings.get(spec?.sailingId);
  if (!sailing) {
    throw new RangeError(`unknown sailing: ${String(spec?.sailingId)}`);
  }
  if (board.manifests.has(spec?.id)) {
    throw new RangeError(`duplicate manifest id: ${String(spec?.id)}`);
  }
  const manifest = createManifest({
    id: spec.id,
    sailingId: sailing.id,
    vesselId: sailing.vesselId,
    lines: spec.lines,
    policy: spec.policy,
  });

  const vessel = board.vessels.get(sailing.vesselId);
  if (spec.assignments !== undefined) {
    if (vessel && Array.isArray(vessel.compartments)) {
      assertCompartmentsFit(manifest, spec.assignments, vessel.compartments);
    } else {
      // Without registered compartments there is nothing to check against,
      // but the assignments must still be well-formed.
      assertCompartmentsFit(manifest, spec.assignments, []);
    }
  }

  board.manifests.set(manifest.id, manifest);
  return manifest;
}

