import { describe, it, assert } from '../tests/helpers.js';

import {
  assertPackingGroup,
  defineDangerousGoods,
  packingGroupAllowed,
  createManifestPolicy,
  assertCelsius,
  defineTemperatureRange,
  defineColdChain,
  intersectRanges,
  createManifestLine,
  createManifest,
  inspectManifestRules,
  formatRange,
  workingTemperatureRange,
  monitoredLines,
  dangerousLines,
  requireLine,
  massByCompartment,
  assertCompartmentsFit,
  lineKey,
} from '../src/domain/manifests.js';
import { registerVessel } from '../src/domain/vessel-registry.js';
import { createBoard } from '../src/domain/board.js';

/* ---------------------------------------------------------------------- */

function policy() {
  return createManifestPolicy({
    incompatibilities: [['dg-3', 'dg-5']],
    packingGroups: {
      'dg-3': ['pg-ii', 'pg-iii'],
      'dg-5': ['pg-i', 'pg-ii'],
    },
  });
}

function line(overrides = {}) {
  return {
    id: 'l-1',
    consignmentId: 'c-1',
    massKg: 100,
    ...overrides,
  };
}

function manifest(lines, extra = {}) {
  return createManifest({
    id: 'm-1',
    sailingId: 's-1',
    vesselId: 'v-1',
    lines,
    policy: policy(),
    ...extra,
  });
}

/* ---------------------------------------------------------------------- */

describe('manifests: dangerous goods basics', () => {
  it('defines a dangerous-goods entry with opaque tokens', () => {
    const dg = defineDangerousGoods({ hazardClass: 'dg-3', packingGroup: 'pg-ii', properName: 'Flammable liquid' });
    assert.deepEqual(dg, { hazardClass: 'dg-3', packingGroup: 'pg-ii', properName: 'Flammable liquid' });
    assert.ok(Object.isFrozen(dg));
  });

  it('defaults properName to null', () => {
    assert.equal(defineDangerousGoods({ hazardClass: 'dg-3', packingGroup: 'pg-ii' }).properName, null);
  });

  it('rejects empty or non-string tokens', () => {
    assert.throws(() => assertPackingGroup(''), RangeError);
    assert.throws(() => assertPackingGroup(3), TypeError);
    assert.throws(() => defineDangerousGoods({ hazardClass: '', packingGroup: 'pg-ii' }), RangeError);
    assert.throws(() => defineDangerousGoods({ hazardClass: 'dg-3', packingGroup: '' }), RangeError);
    assert.throws(
      () => defineDangerousGoods({ hazardClass: 'dg-3', packingGroup: 'pg-ii', properName: 5 }),
      TypeError,
    );
  });

  it('checks packing groups against the policy', () => {
    const p = policy();
    assert.equal(packingGroupAllowed(p, defineDangerousGoods({ hazardClass: 'dg-3', packingGroup: 'pg-ii' })), true);
    assert.equal(packingGroupAllowed(p, defineDangerousGoods({ hazardClass: 'dg-3', packingGroup: 'pg-i' })), false);
    // A class with no policy is unrestricted.
    assert.equal(packingGroupAllowed(p, defineDangerousGoods({ hazardClass: 'dg-9', packingGroup: 'pg-x' })), true);
  });

  it('builds a policy with symmetric hazards and de-duplicated groups', () => {
    const p = createManifestPolicy({
      incompatibilities: [['a', 'b'], ['b', 'a']],
      packingGroups: { a: ['g1', 'g1', 'g2'] },
    });
    assert.equal(p.hazardIncompatibilities.length, 1);
    assert.deepEqual(p.packingGroups.a, ['g1', 'g2']);
    assert.ok(Object.isFrozen(p));
  });

  it('rejects malformed policy input', () => {
    assert.throws(() => createManifestPolicy(null), TypeError);
    assert.throws(() => createManifestPolicy({ incompatibilities: [['a', 'a']] }), RangeError);
    assert.throws(() => createManifestPolicy({ packingGroups: { a: [] } }), RangeError);
    assert.throws(() => createManifestPolicy({ packingGroups: 'nope' }), TypeError);
  });
});

describe('manifests: cold chain basics', () => {
  it('accepts whole degrees, including negative', () => {
    assert.equal(assertCelsius('t', -18), -18);
    assert.equal(assertCelsius('t', 0), 0);
    assert.throws(() => assertCelsius('t', 1.5), TypeError);
    assert.throws(() => assertCelsius('t', '2'), TypeError);
    assert.throws(() => assertCelsius('t', 2 ** 60), RangeError);
  });

  it('defines an inclusive range', () => {
    const r = defineTemperatureRange({ minC: -2, maxC: 4 });
    assert.deepEqual(r, { minC: -2, maxC: 4 });
    assert.deepEqual(defineTemperatureRange({ minC: 3, maxC: 3 }), { minC: 3, maxC: 3 }, 'single degree');
  });

  it('rejects inverted ranges', () => {
    assert.throws(() => defineTemperatureRange({ minC: 5, maxC: 4 }), RangeError);
  });

  it('defines a cold chain with monitoring', () => {
    assert.deepEqual(defineColdChain({ minC: 0, maxC: 4 }), {
      range: { minC: 0, maxC: 4 },
      monitored: false,
    });
    assert.equal(defineColdChain({ minC: 0, maxC: 4, monitored: true }).monitored, true);
    assert.throws(() => defineColdChain({ minC: 0, maxC: 4, monitored: 'yes' }), TypeError);
    assert.throws(() => defineColdChain(null), TypeError);
  });

  it('intersects inclusive ranges, with touching ranges overlapping', () => {
    const a = defineTemperatureRange({ minC: -2, maxC: 2 });
    const b = defineTemperatureRange({ minC: 2, maxC: 6 });
    assert.deepEqual(intersectRanges(a, b), { minC: 2, maxC: 2 });
    assert.deepEqual(intersectRanges(a, defineTemperatureRange({ minC: 0, maxC: 1 })), { minC: 0, maxC: 1 });
    assert.equal(intersectRanges(a, defineTemperatureRange({ minC: 3, maxC: 6 })), null);
    assert.throws(() => intersectRanges(a, null), TypeError);
  });

  it('formats ranges for operators', () => {
    assert.equal(formatRange({ minC: -2, maxC: 4 }), '-2..4 C');
  });
});

describe('manifests: lines', () => {
  it('creates a line with defaults', () => {
    const l = createManifestLine(line());
    assert.equal(l.cargoClass, 'class-general');
    assert.equal(l.dangerousGoods, null);
    assert.equal(l.coldChain, null);
    assert.equal(l.description, 'l-1');
    assert.ok(Object.isFrozen(l));
  });

  it('keeps the caller’s stable line id', () => {
    const l = createManifestLine(line({ id: 'line-xyz' }));
    assert.equal(l.id, 'line-xyz');
  });

  it('requires positive integer kilograms', () => {
    assert.throws(() => createManifestLine(line({ massKg: 0 })), RangeError);
    assert.throws(() => createManifestLine(line({ massKg: 1.5 })), TypeError);
    assert.throws(() => createManifestLine(line({ massKg: -1 })), RangeError);
    assert.equal(createManifestLine(line({ massKg: 1 })).massKg, 1, 'one kilogram');
  });

  it('requires opaque ids', () => {
    assert.throws(() => createManifestLine(line({ id: '' })), RangeError);
    assert.throws(() => createManifestLine(line({ consignmentId: '' })), RangeError);
  });

  it('nests dangerous goods and cold chain', () => {
    const l = createManifestLine(
      line({
        dangerousGoods: { hazardClass: 'dg-3', packingGroup: 'pg-ii' },
        coldChain: { minC: -2, maxC: 2, monitored: true },
      }),
    );
    assert.equal(l.dangerousGoods.hazardClass, 'dg-3');
    assert.equal(l.coldChain.range.minC, -2);
    assert.equal(l.coldChain.monitored, true);
  });
});

describe('manifests: construction', () => {
  it('preserves declaration order and sums integer weight', () => {
    const m = manifest([
      line({ id: 'l-a', massKg: 100 }),
      line({ id: 'l-b', massKg: 250 }),
      line({ id: 'l-c', massKg: 3 }),
    ]);
    assert.deepEqual(m.lines.map((l) => l.id), ['l-a', 'l-b', 'l-c']);
    assert.equal(m.totalMassKg, 353);
    assert.ok(Object.isFrozen(m));
    assert.ok(Object.isFrozen(m.lines));
  });

  it('accepts an empty manifest', () => {
    const m = manifest([]);
    assert.deepEqual(m.lines, []);
    assert.equal(m.totalMassKg, 0);
  });

  it('rejects duplicate line ids', () => {
    assert.throws(
      () => manifest([line({ id: 'l-a' }), line({ id: 'l-a' })]),
      RangeError,
      'duplicate line id',
    );
  });

  it('requires array lines and opaque manifest ids', () => {
    assert.throws(() => createManifest({ id: 'm', sailingId: 's', vesselId: 'v', lines: 'nope' }), TypeError);
    assert.throws(() => createManifest(null), TypeError);
    assert.throws(() => manifest([], { id: '' }), RangeError);
    assert.throws(() => manifest([], { sailingId: '' }), RangeError);
  });

  it('binds the manifest to its sailing and vessel', () => {
    const m = manifest([line()]);
    assert.equal(m.sailingId, 's-1');
    assert.equal(m.vesselId, 'v-1');
  });
});

describe('manifests: dangerous goods compatibility', () => {
  it('allows compatible hazard classes', () => {
    const m = manifest([
      line({ id: 'l-a', dangerousGoods: { hazardClass: 'dg-3', packingGroup: 'pg-ii' } }),
      line({ id: 'l-b', dangerousGoods: { hazardClass: 'dg-9', packingGroup: 'pg-x' } }),
    ]);
    assert.equal(dangerousLines(m).length, 2);
  });

  it('rejects incompatible hazard classes in either declaration order', () => {
    assert.throws(
      () =>
        manifest([
          line({ id: 'l-a', dangerousGoods: { hazardClass: 'dg-3', packingGroup: 'pg-ii' } }),
          line({ id: 'l-b', dangerousGoods: { hazardClass: 'dg-5', packingGroup: 'pg-ii' } }),
        ]),
      RangeError,
    );
    assert.throws(
      () =>
        manifest([
          line({ id: 'l-a', dangerousGoods: { hazardClass: 'dg-5', packingGroup: 'pg-ii' } }),
          line({ id: 'l-b', dangerousGoods: { hazardClass: 'dg-3', packingGroup: 'pg-ii' } }),
        ]),
      RangeError,
    );
  });

  it('allows two lines of the same hazard class', () => {
    const m = manifest([
      line({ id: 'l-a', dangerousGoods: { hazardClass: 'dg-3', packingGroup: 'pg-ii' } }),
      line({ id: 'l-b', dangerousGoods: { hazardClass: 'dg-3', packingGroup: 'pg-iii' } }),
    ]);
    assert.equal(dangerousLines(m).length, 2);
  });

  it('rejects a packing group not permitted for its class', () => {
    assert.throws(
      () => manifest([line({ id: 'l-a', dangerousGoods: { hazardClass: 'dg-3', packingGroup: 'pg-i' } })]),
      RangeError,
    );
  });

  it('permits policy-free hazard classes', () => {
    const m = manifest([line({ id: 'l-a', dangerousGoods: { hazardClass: 'dg-9', packingGroup: 'pg-zzz' } })]);
    assert.equal(dangerousLines(m)[0].dangerousGoods.packingGroup, 'pg-zzz');
  });
});

describe('manifests: cold chain compatibility', () => {
  it('allows overlapping cold chains and reports the tightest range', () => {
    const m = manifest([
      line({ id: 'l-a', coldChain: { minC: 0, maxC: 6 } }),
      line({ id: 'l-b', coldChain: { minC: 2, maxC: 8 } }),
      line({ id: 'l-c', massKg: 50 }),
    ]);
    assert.deepEqual(workingTemperatureRange(m), { minC: 2, maxC: 6 });
  });

  it('allows ranges that merely touch', () => {
    const m = manifest([
      line({ id: 'l-a', coldChain: { minC: 0, maxC: 2 } }),
      line({ id: 'l-b', coldChain: { minC: 2, maxC: 6 } }),
    ]);
    assert.deepEqual(workingTemperatureRange(m), { minC: 2, maxC: 2 });
  });

  it('rejects disjoint ranges', () => {
    assert.throws(
      () =>
        manifest([
          line({ id: 'l-a', coldChain: { minC: -2, maxC: 2 } }),
          line({ id: 'l-b', coldChain: { minC: 5, maxC: 8 } }),
        ]),
      RangeError,
    );
  });

  it('detects a three-way conflict only in the conflicting pair', () => {
    // a and b overlap, b and c overlap, but a and c do not.
    assert.throws(
      () =>
        manifest([
          line({ id: 'l-a', coldChain: { minC: 0, maxC: 4 } }),
          line({ id: 'l-b', coldChain: { minC: 3, maxC: 7 } }),
          line({ id: 'l-c', coldChain: { minC: 6, maxC: 9 } }),
        ]),
      RangeError,
    );
  });

  it('returns null when nothing is chilled', () => {
    assert.equal(workingTemperatureRange(manifest([line()])), null);
  });

  it('lists monitored lines', () => {
    const m = manifest([
      line({ id: 'l-a', coldChain: { minC: 0, maxC: 4, monitored: true } }),
      line({ id: 'l-b', coldChain: { minC: 0, maxC: 4 } }),
      line({ id: 'l-c' }),
    ]);
    assert.deepEqual(monitoredLines(m).map((l) => l.id), ['l-a']);
  });
});

describe('manifests: inspection reports every issue', () => {
  it('collects hazard, packing and cold-chain problems together', () => {
    const lines = [
      createManifestLine(line({ id: 'l-a', dangerousGoods: { hazardClass: 'dg-3', packingGroup: 'pg-i' } })),
      createManifestLine(line({ id: 'l-b', dangerousGoods: { hazardClass: 'dg-5', packingGroup: 'pg-ii' } })),
      createManifestLine(line({ id: 'l-c', coldChain: { minC: 0, maxC: 1 } })),
      createManifestLine(line({ id: 'l-d', coldChain: { minC: 8, maxC: 9 } })),
    ];
    const issues = inspectManifestRules(lines, policy());
    assert.equal(issues.length, 3, issues.join('; '));
    assert.ok(issues.some((i) => i.includes('may not share a manifest')));
    assert.ok(issues.some((i) => i.includes('packing group')));
    assert.ok(issues.some((i) => i.includes('do not overlap')));
    assert.ok(Object.isFrozen(issues));
  });

  it('reports nothing for a clean set of lines', () => {
    assert.deepEqual(inspectManifestRules([createManifestLine(line())], policy()), []);
  });
});

describe('manifests: line lookup and weights', () => {
  const m = manifest([
    line({ id: 'l-a', massKg: 100 }),
    line({ id: 'l-b', massKg: 250 }),
    line({ id: 'l-c', massKg: 3 }),
  ]);

  it('finds lines by stable id', () => {
    assert.equal(requireLine(m, 'l-b').massKg, 250);
    assert.throws(() => requireLine(m, 'missing'), RangeError);
  });

  it('builds stable line keys across manifests', () => {
    const other = manifest([line({ id: 'l-a' })], { id: 'm-2' });
    assert.notEqual(lineKey(m, m.lines[0]), lineKey(other, other.lines[0]));
    assert.equal(lineKey(m, m.lines[0]), lineKey(m, m.lines[0]));
  });

  it('totals mass per compartment', () => {
    const masses = massByCompartment(m, { 'c-fore': ['l-a', 'l-b'], 'c-aft': ['l-c'] });
    assert.deepEqual(masses, { 'c-fore': 350, 'c-aft': 3 });
    assert.ok(Object.isFrozen(masses));
  });

  it('rejects unknown lines and malformed assignments', () => {
    assert.throws(() => massByCompartment(m, { 'c-1': ['missing'] }), RangeError);
    assert.throws(() => massByCompartment(m, { 'c-1': 'l-a' }), TypeError);
    assert.throws(() => massByCompartment(m, null), TypeError);
  });

  it('checks compartment capacities, at the boundary and one kilogram over', () => {
    const compartments = [
      { id: 'c-fore', capacityKg: 350 },
      { id: 'c-aft', capacityKg: 2 },
    ];
    assert.throws(
      () => assertCompartmentsFit(m, { 'c-fore': ['l-a', 'l-b'], 'c-aft': ['l-c'] }, compartments),
      RangeError,
      'aft holds 3 kg in a 2 kg hold',
    );
    assert.deepEqual(
      assertCompartmentsFit(m, { 'c-fore': ['l-a', 'l-b'], 'c-aft': [] }, compartments),
      { 'c-fore': 350, 'c-aft': 0 },
    );
  });

  it('ignores compartments with no assignment', () => {
    const m2 = manifest([line({ id: 'l-a', massKg: 10 })]);
    assert.deepEqual(
      assertCompartmentsFit(m2, { 'c-1': ['l-a'] }, [
        { id: 'c-1', capacityKg: 10 },
        { id: 'c-2', capacityKg: 1 },
      ]),
      { 'c-1': 10 },
    );
  });
});

describe('manifests: integration with the vessel registry and board', () => {
  const vesselSpec = {
    id: 'v-1',
    compartments: [
      { id: 'c-fore', capacityKg: 400 },
      { id: 'c-aft', capacityKg: 600 },
    ],
