/**
 * Port tide windows.
 *
 * Some ports can only be entered or left on a rising or falling tide, and some
 * hulls need extra water under them to clear a sill or bar. Harbor Dispatch
 * does **not** predict tides. There is no lunar model, no harmonic series, no
 * astronomical table and no interpolation: that would be fabricated science
 * dressed up as data.
 *
 * Instead, an operator (or an upstream tide service, outside this codebase)
 * supplies **explicit, precomputed UTC intervals** with the depth available in
 * each. The domain only does what it can do honestly:
 *
 *  - store those intervals and reject malformed ones;
 *  - report whether a given moment falls inside a navigable window;
 *  - report whether a required clearance (in integer centimetres) is met;
 *  - report whether a whole passage — a departure from one port and an
 *    arrival at another — is feasible end to end.
 *
 * Depth is stored in integer centimetres so that clearances like 1.4 m are
 * exact; there are no floats anywhere in this module.
 *
 * Existing invariants are preserved: port ids and window ids are opaque,
 * timestamps are caller-supplied UTC values, and intervals are half-open
 * `[from, to)` exactly like closures and planning horizons.
 */

import { assertOpaqueId } from './ids.js';
import { assertKilograms } from './capacity.js';
import { assertPortId } from '../ports.js';
import { instant } from './time.js';

/**
 * @typedef {object} TideWindow
 * @property {string} id opaque window id
 * @property {string} portId
 * @property {Readonly<import('./time.js').Instant>} from inclusive start
 * @property {Readonly<import('./time.js').Instant>} to exclusive end
 * @property {number} depthCm integer centimetres available throughout
 * @property {string|null} note
 */

/**
 * Depth in integer centimetres. Non-negative safe integer.
 *
 * @param {string} label
 * @param {unknown} value
 * @returns {number}
 */
export function assertCentimetres(label, value) {
  if (typeof value !== 'number' || !Number.isInteger(value)) {
    throw new TypeError(`${label} must be an integer number of centimetres`);
  }
  if (!Number.isSafeInteger(value)) {
    throw new RangeError(`${label} is not a safe integer`);
  }
  if (value < 0) {
    throw new RangeError(`${label} must not be negative`);
  }
  return value;
}

/**
 * Convert whole metres to centimetres. This is a unit conversion of an
 * operator-supplied number, not a measurement; the result is an integer.
 *
 * @param {number} metres
 * @returns {number}
 */
export function metresToCm(metres) {
  if (typeof metres !== 'number' || !Number.isInteger(metres)) {
    throw new TypeError('metres must be a whole number');
  }
  return metres * 100;
}

/**
 * Define one precomputed tide window for a port.
 *
 * @param {{
 *   id: string,
 *   portId: string,
 *   fromUtc: string,
 *   toUtc: string,
 *   depthCm: number,
 *   note?: string,
 * }} spec
 * @returns {Readonly<TideWindow>}
 */
export function defineTideWindow(spec) {
  if (spec === null || typeof spec !== 'object') {
    throw new TypeError('tide window spec must be an object');
  }
  const id = assertOpaqueId('tide window id', spec.id);
  const portId = assertPortId(spec.portId);
  const from = instant(spec.fromUtc);
  const to = instant(spec.toUtc);
  if (to.ms <= from.ms) {
    throw new RangeError(`tide window ${id} must end after it starts`);
  }
  const depthCm = assertCentimetres('tide window depthCm', spec.depthCm);
  if (spec.note !== undefined && typeof spec.note !== 'string') {
    throw new TypeError('tide window note must be a string');
  }
  const note = spec.note === undefined || spec.note.length === 0 ? null : spec.note;
  return Object.freeze({ id, portId, from, to, depthCm, note });
}

/**
 * Whether an instant falls inside a window. Half-open `[from, to)`: an instant
 * exactly at `from` is inside, exactly at `to` is not.
 *
 * @param {Readonly<TideWindow>} window
 * @param {Readonly<import('./time.js').Instant>} at
 * @returns {boolean}
 */
export function windowContains(window, at) {
  return at.ms >= window.from.ms && at.ms < window.to.ms;
}

/**
 * Whether a window meets a required clearance. Clearance is inclusive: a
 * window with exactly the required depth is usable.
 *
 * @param {Readonly<TideWindow>} window
 * @param {number} requiredCm
 * @returns {boolean}
 */
export function windowMeetsClearance(window, requiredCm) {
  assertCentimetres('required clearance', requiredCm);
  return window.depthCm >= requiredCm;
}

/**
 * Why a window is unusable at a moment, or `null` when it is usable.
 *
 * @param {Readonly<TideWindow>} window
 * @param {Readonly<import('./time.js').Instant>} at
 * @param {number} requiredCm
 * @returns {string|null}
 */
export function windowBlocker(window, at, requiredCm) {
  assertCentimetres('required clearance', requiredCm);
  if (!windowContains(window, at)) {
    return `window ${window.id} does not cover that time`;
  }
  if (!windowMeetsClearance(window, requiredCm)) {
    return (
      `window ${window.id} has ${window.depthCm} cm depth, ` +
      `under the required ${requiredCm} cm clearance`
    );
  }
  return null;
}

/**
 * A port's tide table: its precomputed windows, checked for consistency.
 *
 * Windows on the same port may abut (one ends exactly when the next starts)
 * but may not overlap, because overlapping depths would be ambiguous.
 *
 * @param {{
 *   portId: string,
 *   windows: ReadonlyArray<{
 *     id: string,
 *     portId?: string,
 *     fromUtc: string,
 *     toUtc: string,
 *     depthCm: number,
 *     note?: string,
 *   }>,
 * }} spec
 * @returns {Readonly<object>}
 */
export function createTideTable(spec) {
  if (spec === null || typeof spec !== 'object') {
    throw new TypeError('tide table spec must be an object');
  }
  const portId = assertPortId(spec.portId);
  if (!Array.isArray(spec.windows)) {
    throw new TypeError('tide table windows must be an array');
  }

  /** @type {Map<string, Readonly<TideWindow>>} */
  const byId = new Map();
  /** @type {TideWindow[]} */
  const windows = [];

  for (const windowSpec of spec.windows) {
    if (windowSpec !== null && typeof windowSpec === 'object' && windowSpec.portId !== undefined) {
      if (windowSpec.portId !== portId) {
        throw new RangeError(
          `window ${String(windowSpec.id)} names port ${String(windowSpec.portId)}, ` +
            `not ${portId}`,
        );
      }
    }
    const window = defineTideWindow({ ...windowSpec, portId });
    if (byId.has(window.id)) {
      throw new RangeError(`duplicate tide window id: ${window.id}`);
    }
    byId.set(window.id, window);
    windows.push(window);
  }

  // Stable order: by start, then id. Order confers no meaning on the ids; it
  // exists only so reports and lookups are deterministic.
  windows.sort((a, b) => a.from.ms - b.from.ms || compareStrings(a.id, b.id));

  for (let i = 1; i < windows.length; i += 1) {
    const previous = windows[i - 1];
    const current = windows[i];
    if (current.from.ms < previous.to.ms) {
      throw new RangeError(
        `tide windows ${previous.id} and ${current.id} overlap on port ${portId}`,
      );
    }
  }

  const api = {
    portId,

    /** @returns {ReadonlyArray<Readonly<TideWindow>>} */
    windows() {
      return Object.freeze([...windows]);
    },

    /**
     * @param {string} windowId
     * @returns {Readonly<TideWindow>}
     */
    requireWindow(windowId) {
      const window = byId.get(windowId);
      if (!window) {
        throw new RangeError(`unknown tide window: ${String(windowId)}`);
      }
      return window;
    },

    /**
     * Every window covering `at`.
     *
     * @param {Readonly<import('./time.js').Instant>} at
     * @returns {ReadonlyArray<Readonly<TideWindow>>}
     */
    windowsAt(at) {
      requireInstant(at, 'windowsAt');
      return Object.freeze(windows.filter((window) => windowContains(window, at)));
    },

    /**
     * The usable window covering `at`, or `null`. Because windows never
     * overlap, at most one can match.
     *
     * @param {Readonly<import('./time.js').Instant>} at
     * @param {number} requiredCm
     * @returns {Readonly<TideWindow>|null}
     */
    usableWindowAt(at, requiredCm) {
      requireInstant(at, 'usableWindowAt');
      assertCentimetres('required clearance', requiredCm);
      for (const window of windows) {
        if (windowContains(window, at) && windowMeetsClearance(window, requiredCm)) {
          return window;
        }
      }
      return null;
    },

    /**
     * Whether a passage is possible at a moment: usable window at that instant.
     *
     * @param {Readonly<import('./time.js').Instant>} at
     * @param {number} requiredCm
     * @returns {{ ok: true, windowId: string } | { ok: false, reason: string }}
     */
    check(at, requiredCm) {
      requireInstant(at, 'check');
      assertCentimetres('required clearance', requiredCm);
      const covering = windows.filter((window) => windowContains(window, at));
      if (covering.length === 0) {
        return { ok: false, reason: `no tide window covers that time at port ${portId}` };
      }
      const window = covering[0];
      const blocker = windowBlocker(window, at, requiredCm);
      if (blocker !== null) {
        return { ok: false, reason: blocker };
      }
      return { ok: true, windowId: window.id };
    },

    /**
     * The next instant at or after `from` at which a usable window begins.
     * This scans the precomputed windows; it never extrapolates.
     *
     * Returns `null` when no such window is recorded.
     *
     * @param {Readonly<import('./time.js').Instant>} from
     * @param {number} requiredCm
     * @returns {{ windowId: string, atMs: number } | null}
     */
    nextOpening(from, requiredCm) {
      requireInstant(from, 'nextOpening');
      assertCentimetres('required clearance', requiredCm);
      for (const window of windows) {
        if (!windowMeetsClearance(window, requiredCm)) continue;
        if (window.to.ms <= from.ms) continue;
        const atMs = Math.max(window.from.ms, from.ms);
        return Object.freeze({ windowId: window.id, atMs });
      }
      return null;
    },
  };

  return Object.freeze(api);
}

/**
 * Check a whole passage: departure from one port, arrival at another, each
 * with its own required clearance.
 *
 * Both ends must be covered by a usable window at the relevant instant. The
 * ports may be the same or different; identical ports simply require the same
 * table to be usable twice.
 *
 * @param {{
 *   departure: Readonly<object>,
 *   arrival: Readonly<object>,
 * }} tables
 * @param {{
 *   departsAt: Readonly<import('./time.js').Instant>,
 *   arrivesAt: Readonly<import('./time.js').Instant>,
 *   departureClearanceCm: number,
 *   arrivalClearanceCm: number,
 * }} passage
 * @returns {
 *   | { ok: true, departureWindowId: string, arrivalWindowId: string }
 *   | { ok: false, reason: string, end: 'departure'|'arrival' }
 * }
 */
export function checkPassage(tables, passage) {
  if (tables === null || typeof tables !== 'object') {
    throw new TypeError('checkPassage requires a departure and arrival table');
  }
  if (passage === null || typeof passage !== 'object') {
    throw new TypeError('checkPassage requires a passage description');
  }
  requireInstant(passage.departsAt, 'checkPassage');
  requireInstant(passage.arrivesAt, 'checkPassage');
  assertCentimetres('departure clearance', passage.departureClearanceCm);
  assertCentimetres('arrival clearance', passage.arrivalClearanceCm);

  const departure = tables.departure.check(passage.departsAt, passage.departureClearanceCm);
  if (!departure.ok) {
    return Object.freeze({ ok: false, reason: `departure: ${departure.reason}`, end: 'departure' });
  }
  const arrival = tables.arrival.check(passage.arrivesAt, passage.arrivalClearanceCm);
  if (!arrival.ok) {
    return Object.freeze({ ok: false, reason: `arrival: ${arrival.reason}`, end: 'arrival' });
  }
  return Object.freeze({
    ok: true,
    departureWindowId: departure.windowId,
    arrivalWindowId: arrival.windowId,
  });
}

/**
 * Check that a sailing's departure and arrival both fall in usable windows.
 * The sailing supplies the instants; the caller supplies the clearances.
 *
 * @param {{
 *   departure: Readonly<object>,
 *   arrival: Readonly<object>,
 * }} tables
 * @param {Readonly<import('./sailings.js').Sailing>} sailing
 * @param {{ departureClearanceCm: number, arrivalClearanceCm: number }} clearances
 * @returns {ReturnType<typeof checkPassage>}
 */
export function checkSailingTides(tables, sailing, clearances) {
  if (sailing === null || typeof sailing !== 'object') {
    throw new TypeError('checkSailingTides requires a sailing');
  }
  if (clearances === null || typeof clearances !== 'object') {
    throw new TypeError('checkSailingTides requires clearances');
  }
  return checkPassage(tables, {
    departsAt: sailing.departsAt,
    arrivesAt: sailing.arrivesAt,
    departureClearanceCm: clearances.departureClearanceCm,
    arrivalClearanceCm: clearances.arrivalClearanceCm,
  });
}

/**
 * @param {unknown} value
 * @param {string} what
 * @returns {void}
 */
function requireInstant(value, what) {
  if (value === null || typeof value !== 'object' || typeof value.ms !== 'number') {
    throw new TypeError(`${what} requires an explicit UTC instant`);
  }
}

/**
 * @param {string} a
 * @param {string} b
 * @returns {number}
 */
function compareStrings(a, b) {
  if (a < b) return -1;
  if (a > b) return 1;
  return 0;
}

export { assertKilograms };

