import { describe, it, assert } from '../tests/helpers.js';

import {
  assertCentimetres,
  metresToCm,
  defineTideWindow,
  windowContains,
  windowMeetsClearance,
  windowBlocker,
  createTideTable,
  checkPassage,
  checkSailingTides,
} from '../src/domain/tides.js';
import { instant } from '../src/domain/time.js';
import { createSailing } from '../src/domain/sailings.js';
import { createVessel } from '../src/domain/vessels.js';
import { createBoard } from '../src/domain/board.js';

/* ---------------------------------------------------------------------- */

const t = (utc) => instant(utc);

function window(overrides = {}) {
  return defineTideWindow({
    id: 'w-1',
    portId: 'p-north',
    fromUtc: '2030-01-01T00:00:00Z',
    toUtc: '2030-01-01T06:00:00Z',
    depthCm: 400,
    ...overrides,
  });
}

function table(windows, portId = 'p-north') {
  return createTideTable({ portId, windows });
}

/* ---------------------------------------------------------------------- */

describe('tides: depths and conversions', () => {
  it('requires non-negative integer centimetres', () => {
    assert.equal(assertCentimetres('d', 0), 0);
    assert.equal(assertCentimetres('d', 450), 450);
    assert.throws(() => assertCentimetres('d', 1.5), TypeError);
    assert.throws(() => assertCentimetres('d', '400'), TypeError);
    assert.throws(() => assertCentimetres('d', -1), RangeError);
    assert.throws(() => assertCentimetres('d', 2 ** 60), RangeError);
  });

  it('converts whole metres to exact centimetres', () => {
    assert.equal(metresToCm(0), 0);
    assert.equal(metresToCm(4), 400);
    assert.equal(metresToCm(12), 1200);
  });

  it('rejects fractional, negative and oversized metres', () => {
    assert.throws(() => metresToCm(1.5), TypeError);
    assert.throws(() => metresToCm(-1), RangeError);
    assert.throws(() => metresToCm(2 ** 60), RangeError);
    assert.throws(() => metresToCm('4'), TypeError);
  });
});

describe('tides: window definition', () => {
  it('defines a precomputed window with opaque ids and UTC bounds', () => {
    const w = window();
    assert.equal(w.id, 'w-1');
    assert.equal(w.portId, 'p-north');
    assert.equal(w.from.utc, '2030-01-01T00:00:00.000Z');
    assert.equal(w.to.utc, '2030-01-01T06:00:00.000Z');
    assert.equal(w.depthCm, 400);
    assert.equal(w.note, null);
    assert.ok(Object.isFrozen(w));
  });

  it('keeps an optional note', () => {
    assert.equal(window({ note: 'high water' }).note, 'high water');
    assert.throws(() => window({ note: 5 }), TypeError);
  });

  it('requires a forward window', () => {
    assert.throws(() => window({ toUtc: '2030-01-01T00:00:00Z' }), RangeError, 'zero length');
    assert.throws(() => window({ toUtc: '2029-12-31T00:00:00Z' }), RangeError, 'backwards');
  });

  it('requires UTC and opaque ids', () => {
    assert.throws(() => window({ fromUtc: '2030-01-01T00:00:00+01:00' }), RangeError);
    assert.throws(() => window({ fromUtc: '2030-01-01' }), RangeError);
    assert.throws(() => window({ id: '' }), RangeError);
    assert.throws(() => window({ portId: '' }), TypeError);
    assert.throws(() => defineTideWindow(null), TypeError);
  });

  it('accepts a one-minute window as the lower boundary', () => {
    const w = window({ toUtc: '2030-01-01T00:01:00Z' });
    assert.equal(w.to.ms - w.from.ms, 60_000);
  });
});

describe('tides: half-open containment', () => {
  const w = window();

  it('includes the start instant', () => {
    assert.equal(windowContains(w, t('2030-01-01T00:00:00Z')), true);
  });

  it('includes the last instant before the end', () => {
    assert.equal(windowContains(w, t('2030-01-01T05:59:59Z')), true);
  });

  it('excludes the end instant', () => {
    assert.equal(windowContains(w, t('2030-01-01T06:00:00Z')), false);
  });

  it('excludes instants outside on both sides', () => {
    assert.equal(windowContains(w, t('2029-12-31T23:59:59Z')), false);
    assert.equal(windowContains(w, t('2030-01-01T06:00:01Z')), false);
  });
});

describe('tides: minimum clearance', () => {
  const w = window({ depthCm: 400 });

  it('meets a clearance exactly equal to the depth', () => {
    assert.equal(windowMeetsClearance(w, 400), true);
  });

  it('meets a smaller clearance and a zero clearance', () => {
    assert.equal(windowMeetsClearance(w, 399), true);
    assert.equal(windowMeetsClearance(w, 0), true);
  });

  it('fails one centimetre over the depth', () => {
    assert.equal(windowMeetsClearance(w, 401), false);
  });

  it('rejects an invalid clearance', () => {
    assert.throws(() => windowMeetsClearance(w, -1), RangeError);
    assert.throws(() => windowMeetsClearance(w, 1.5), TypeError);
  });

  it('explains why a window is unusable', () => {
    assert.equal(windowBlocker(w, t('2030-01-01T01:00:00Z'), 400), null);
    const outside = windowBlocker(w, t('2030-01-01T07:00:00Z'), 400);
    assert.ok(outside.includes('does not cover'));
    const shallow = windowBlocker(w, t('2030-01-01T01:00:00Z'), 500);
    assert.ok(shallow.includes('400 cm'));
    assert.ok(shallow.includes('500 cm'));
  });
});

describe('tides: tables', () => {
  it('sorts windows by start and lists them', () => {
    const tb = table([
      { id: 'w-late', fromUtc: '2030-01-01T12:00:00Z', toUtc: '2030-01-01T18:00:00Z', depthCm: 300 },
      { id: 'w-early', fromUtc: '2030-01-01T00:00:00Z', toUtc: '2030-01-01T06:00:00Z', depthCm: 400 },
    ]);
    assert.deepEqual(tb.windows().map((w) => w.id), ['w-early', 'w-late']);
    assert.ok(Object.isFrozen(tb.windows()));
  });

  it('accepts abutting windows', () => {
    const tb = table([
      { id: 'w-1', fromUtc: '2030-01-01T00:00:00Z', toUtc: '2030-01-01T06:00:00Z', depthCm: 400 },
      { id: 'w-2', fromUtc: '2030-01-01T06:00:00Z', toUtc: '2030-01-01T12:00:00Z', depthCm: 200 },
    ]);
    assert.equal(tb.windows().length, 2);
  });

  it('rejects overlapping windows', () => {
    assert.throws(
      () =>
        table([
          { id: 'w-1', fromUtc: '2030-01-01T00:00:00Z', toUtc: '2030-01-01T06:00:00Z', depthCm: 400 },
          { id: 'w-2', fromUtc: '2030-01-01T05:00:00Z', toUtc: '2030-01-01T09:00:00Z', depthCm: 200 },
        ]),
      RangeError,
      'overlap',
    );
  });

  it('rejects duplicate window ids and foreign ports', () => {
    assert.throws(
      () =>
        table([
          { id: 'w-1', fromUtc: '2030-01-01T00:00:00Z', toUtc: '2030-01-01T06:00:00Z', depthCm: 400 },
          { id: 'w-1', fromUtc: '2030-01-01T06:00:00Z', toUtc: '2030-01-01T12:00:00Z', depthCm: 400 },
        ]),
      RangeError,
      'duplicate id',
    );
    assert.throws(
      () =>
        table([
          {
            id: 'w-1',
            portId: 'p-elsewhere',
            fromUtc: '2030-01-01T00:00:00Z',
            toUtc: '2030-01-01T06:00:00Z',
            depthCm: 400,
          },
        ]),
      RangeError,
      'wrong port',
    );
  });

  it('allows an empty table', () => {
    const tb = table([]);
    assert.deepEqual(tb.windows(), []);
    assert.equal(tb.check(t('2030-01-01T01:00:00Z'), 0).ok, false);
  });

  it('finds windows covering an instant, at most one', () => {
    const tb = table([
      { id: 'w-1', fromUtc: '2030-01-01T00:00:00Z', toUtc: '2030-01-01T06:00:00Z', depthCm: 400 },
    ]);
    assert.deepEqual(tb.windowsAt(t('2030-01-01T06:00:00Z')), []);
    assert.deepEqual(tb.windowsAt(t('2030-01-01T05:59:59Z')).map((w) => w.id), ['w-1']);
    assert.equal(tb.usableWindowAt(t('2030-01-01T01:00:00Z'), 400).id, 'w-1');
    assert.equal(tb.usableWindowAt(t('2030-01-01T01:00:00Z'), 401), null);
  });

  it('requires explicit instants', () => {
    const tb = table([]);
    assert.throws(() => tb.windowsAt(null), TypeError);
    assert.throws(() => tb.usableWindowAt({ ms: 'x' }, 0), TypeError);
    assert.throws(() => tb.check(null, 0), TypeError);
    assert.throws(() => tb.nextOpening(undefined, 0), TypeError);
  });

  it('looks up windows by id', () => {
    const tb = table([
      { id: 'w-1', fromUtc: '2030-01-01T00:00:00Z', toUtc: '2030-01-01T06:00:00Z', depthCm: 400 },
    ]);
    assert.equal(tb.requireWindow('w-1').depthCm, 400);
    assert.throws(() => tb.requireWindow('w-nope'), RangeError);
  });

  it('rejects malformed specs', () => {
    assert.throws(() => createTideTable(null), TypeError);
    assert.throws(() => createTideTable({ portId: 'p', windows: 'x' }), TypeError);
    assert.throws(() => createTideTable({ windows: [] }), TypeError);
  });
});

describe('tides: checks', () => {
  const tb = table([
    { id: 'w-deep', fromUtc: '2030-01-01T00:00:00Z', toUtc: '2030-01-01T06:00:00Z', depthCm: 400 },
    { id: 'w-shallow', fromUtc: '2030-01-01T06:00:00Z', toUtc: '2030-01-01T12:00:00Z', depthCm: 150 },
  ]);

  it('reports a usable window with its id', () => {
    assert.deepEqual(tb.check(t('2030-01-01T01:00:00Z'), 400), { ok: true, windowId: 'w-deep' });
  });

  it('reports insufficient depth', () => {
    const result = tb.check(t('2030-01-01T07:00:00Z'), 200);
    assert.equal(result.ok, false);
    assert.ok(result.reason.includes('150 cm'));
  });

  it('reports a gap between windows', () => {
    const result = tb.check(t('2030-01-01T13:00:00Z'), 0);
    assert.equal(result.ok, false);
    assert.ok(result.reason.includes('no tide window'));
  });

  it('treats the boundary between windows correctly', () => {
    assert.equal(tb.check(t('2030-01-01T05:59:59Z'), 400).ok, true);
    // Exactly at 06:00 the deep window has ended and the shallow one applies.
    const at = tb.check(t('2030-01-01T06:00:00Z'), 400);
    assert.equal(at.ok, false);
    assert.equal(tb.check(t('2030-01-01T06:00:00Z'), 150).ok, true);
  });

  it('finds the next usable opening without extrapolating', () => {
    const next = tb.nextOpening(t('2030-01-01T05:00:00Z'), 350);
    assert.equal(next.windowId, 'w-shallow');
    assert.equal(next.atMs, Date.parse('2030-01-01T06:00:00Z'));
  });

  it('clamps the next opening to the query time', () => {
    const next = tb.nextOpening(t('2030-01-01T02:00:00Z'), 350);
    assert.equal(next.windowId, 'w-deep');
    assert.equal(next.atMs, Date.parse('2030-01-01T02:00:00Z'));
  });

  it('returns null when no recorded window can serve', () => {
    assert.equal(tb.nextOpening(t('2030-01-01T00:00:00Z'), 500), null);
    assert.equal(tb.nextOpening(t('2030-01-02T00:00:00Z'), 0), null);
  });
});

describe('tides: passages', () => {
  const north = table(
    [
      { id: 'n-1', fromUtc: '2030-01-01T00:00:00Z', toUtc: '2030-01-01T06:00:00Z', depthCm: 400 },
