    assert.equal(earlyArrival.ok, false);
    assert.equal(earlyArrival.end, 'arrival');
  });

  it('fails on insufficient depth at either end', () => {
    const shallowArrival = checkPassage(
      { departure: north, arrival: south },
      {
        departsAt: t('2030-01-01T01:00:00Z'),
        arrivesAt: t('2030-01-01T10:00:00Z'),
        departureClearanceCm: 400,
        arrivalClearanceCm: 301,
      },
    );
    assert.equal(shallowArrival.ok, false);
    assert.equal(shallowArrival.end, 'arrival');
  });

  it('validates its inputs', () => {
    assert.throws(() => checkPassage(null, {}), TypeError);
    assert.throws(() => checkPassage({ departure: north, arrival: south }, null), TypeError);
    assert.throws(
      () =>
        checkPassage(
          { departure: north, arrival: south },
          { departsAt: null, arrivesAt: t('2030-01-01T10:00:00Z'), departureClearanceCm: 0, arrivalClearanceCm: 0 },
