/**
 * Operator example: checking a passage against precomputed tide windows.
 *
 * Fictional data only. Run with: node examples/tides-example.js
 *
 * There is no tide prediction here. Every window below is an explicit,
 * precomputed UTC interval with an explicit depth; this program only compares
 * those against a required clearance.
 */

import {
  createBoard,
  metresToCm,
  createTideTable,
  checkPassage,
  instant,
} from '../src/index.js';

// --- Precomputed windows for two fictional ports. -----------------------

const north = createTideTable({
  portId: 'p-north',
  windows: [
    { id: 'n-morning', fromUtc: '2030-01-01T00:00:00Z', toUtc: '2030-01-01T06:00:00Z', depthCm: metresToCm(4), note: 'high water 04:10' },
    { id: 'n-evening', fromUtc: '2030-01-01T12:00:00Z', toUtc: '2030-01-01T18:00:00Z', depthCm: metresToCm(3) },
  ],
});

const south = createTideTable({
  portId: 'p-south',
  windows: [
    { id: 's-midday', fromUtc: '2030-01-01T08:00:00Z', toUtc: '2030-01-01T14:00:00Z', depthCm: metresToCm(3) },
  ],
});

console.log('recorded windows:');
for (const w of [...north.windows(), ...south.windows()]) {
  const hours = (w.to.ms - w.from.ms) / 3_600_000;
  console.log(`  ${w.portId}/${w.id}: ${w.from.utc} for ${hours} h at ${w.depthCm} cm`);
}

// --- One passage, two clearances. ---------------------------------------

const clearances = { departureClearanceCm: metresToCm(4), arrivalClearanceCm: metresToCm(3) };

function attempt(label, departsUtc, arrivesUtc) {
  const result = checkPassage(
    { departure: north, arrival: south },
    { departsAt: instant(departsUtc), arrivesAt: instant(arrivesUtc), ...clearances },
  );
  if (result.ok) {
    console.log(`${label}: ok (${result.departureWindowId} -> ${result.arrivalWindowId})`);
  } else {
    console.log(`${label}: refused at ${result.end} — ${result.reason}`);
  }
}

console.log('');
attempt('depart 01:00, arrive 10:00', '2030-01-01T01:00:00Z', '2030-01-01T10:00:00Z');
attempt('depart 07:00, arrive 10:00', '2030-01-01T07:00:00Z', '2030-01-01T10:00:00Z');
attempt('depart 01:00, arrive 07:00', '2030-01-01T01:00:00Z', '2030-01-01T07:00:00Z');

// The first attempt needs the full 4 m at the origin. A lighter draft can go
// later in the day, once the evening window opens.
console.log('');
attempt('depart 05:59:59 (last minute of deep water)', '2030-01-01T05:59:59Z', '2030-01-01T10:00:00Z');

const lighter = checkPassage(
  { departure: north, arrival: south },
  {
    departsAt: instant('2030-01-01T13:00:00Z'),
    arrivesAt: instant('2030-01-01T10:00:00Z'),
    departureClearanceCm: metresToCm(3),
    arrivalClearanceCm: metresToCm(3),
  },
);
console.log(`evening departure with a light draft: ${lighter.ok ? 'ok' : lighter.reason}`);

// --- The same check through the planning board. -------------------------

const board = createBoard({ startUtc: '2030-01-01T00:00:00Z' });
board.addVessel({ id: 'v-skiff', name: 'Harbor Skiff', capacityKg: 1000 });
board.addSailing({
  id: 's-morning',
  vesselId: 'v-skiff',
  routeId: 'route-north-south',
  originPortId: 'p-north',
  destinationPortId: 'p-south',
  departsAtUtc: '2030-01-01T01:00:00Z',
  arrivesAtUtc: '2030-01-01T10:00:00Z',
});
board.addTideTable({
  portId: 'p-north',
  windows: [
    { id: 'n-morning', fromUtc: '2030-01-01T00:00:00Z', toUtc: '2030-01-01T06:00:00Z', depthCm: metresToCm(4) },
  ],
});
board.addTideTable({
  portId: 'p-south',
  windows: [
    { id: 's-midday', fromUtc: '2030-01-01T08:00:00Z', toUtc: '2030-01-01T14:00:00Z', depthCm: metresToCm(3) },
  ],
});

const boardCheck = board.checkSailingTides('s-morning', clearances);
console.log(`\nboard check for s-morning: ${boardCheck.ok ? 'ok' : boardCheck.reason}`);

const tooDeep = board.checkSailingTides('s-morning', {
  departureClearanceCm: metresToCm(5),
  arrivalClearanceCm: metresToCm(3),
});
console.log(`board check with a 5 m draft: ${tooDeep.ok ? 'ok' : tooDeep.reason}`);

