/**
 * Time handling.
 *
 * Every timestamp in Harbor Dispatch is a UTC value supplied by the caller as
 * an ISO-8601 string ending in "Z". The domain never reads the system clock:
 * all "now" values arrive as arguments. Internally, instants are held as
 * integer milliseconds since the Unix epoch so they can be compared cheaply.
 */

import { parseUtcTimestamp } from '../ports.js';

/**
 * @typedef {object} Instant
 * @property {number} ms
 * @property {string} utc normalised ISO-8601 string
 */

/**
 * Normalise a caller-supplied UTC timestamp.
 *
 * @param {string} value
 * @returns {Readonly<Instant>}
 */
export function instant(value) {
  const ms = parseUtcTimestamp(value);
  return Object.freeze({ ms, utc: new Date(ms).toISOString() });
}

/**
 * Order two instants.
 *
 * @param {{ ms: number }} a
 * @param {{ ms: number }} b
 * @returns {number}
 */
export function compareInstants(a, b) {
  return a.ms - b.ms;
}

/**
 * Whether `instant` lies in the half-open window `[from, to)`.
 *
 * @param {{ ms: number }} value
 * @param {{ ms: number }} from
 * @param {{ ms: number }} to
 * @returns {boolean}
 */
export function isWithin(value, from, to) {
  return value.ms >= from.ms && value.ms < to.ms;
}

/**
 * Duration in whole UTC days between two instants.
 *
 * @param {{ ms: number }} from
 * @param {{ ms: number }} to
 * @returns {number}
 */
export function wholeDaysBetween(from, to) {
  return Math.floor((to.ms - from.ms) / 86_400_000);
}

/**
 * Opaque identifiers.
 *
 * Every identifier in Harbor Dispatch is an opaque string. Callers may have
 * generated them from a counter, a UUID, or anything else, but the domain
 * only ever compares them for equality — it never slices, parses, sorts by
 * meaning, or infers a type from their shape.
