/**
 * Crew qualification rules.
 *
 * Harbor Dispatch records crew as **anonymous duty identities**: an opaque
 * crew id and nothing more. There are no names, no contact details, no dates
 * of birth and no free-text notes about people anywhere in this module. The
 * cooperative's personnel records live elsewhere and are out of scope; what
 * the planner needs is whether a hull can be legally crewed for a given
 * watch.
 *
 * Three rules are enforced:
 *
 *  1. **Certificate expiry.** A crew member holds certificates for roles, each
 *     with an expiry instant. A certificate is valid on `[issuedAt, expiresAt)`
 *     — the expiry instant itself is *not* valid. A crew member may only fill
 *     a role while holding a valid certificate for it.
 *  2. **Watch duration.** A watch has a maximum length in integer minutes. A
 *     watch whose duration exactly equals the limit is allowed; one minute
 *     more is not.
 *  3. **Role coverage.** Every role a watch requires must be filled by a
 *     distinct crew member, and a crew member may only hold one role on a
 *     given watch.
 *
 * All times are caller-supplied UTC instants; nothing here reads the clock.
 */

import { assertOpaqueId } from './ids.js';
import { instant, isWithin } from './time.js';

/* -------------------------------------------------------------------------
 * Roles
 * ---------------------------------------------------------------------- */

/**
 * Roles are opaque tokens (for example `role-helm`). The domain never infers
 * privilege from their text.
 *
 * @typedef {string} CrewRole
 */

/**
 * @param {string} label
 * @param {unknown} value
 * @returns {CrewRole}
 */
export function assertCrewRole(label, value) {
  return assertOpaqueId(label, value);
}

/* -------------------------------------------------------------------------
 * Certificates
 * ---------------------------------------------------------------------- */

/**
 * @typedef {object} Certificate
 * @property {string} id opaque certificate id
 * @property {CrewRole} role
 * @property {Readonly<import('./time.js').Instant>} issuedAt
 * @property {Readonly<import('./time.js').Instant>} expiresAt exclusive
 */

/**
 * @param {{ id: string, role: string, issuedAtUtc: string, expiresAtUtc: string }} spec
 * @returns {Readonly<Certificate>}
 */
export function createCertificate(spec) {
  if (spec === null || typeof spec !== 'object') {
    throw new TypeError('certificate spec must be an object');
  }
  const id = assertOpaqueId('certificate id', spec.id);
  const role = assertCrewRole('certificate role', spec.role);
  const issuedAt = instant(spec.issuedAtUtc);
  const expiresAt = instant(spec.expiresAtUtc);
  if (expiresAt.ms <= issuedAt.ms) {
    throw new RangeError(`certificate ${id} must expire after it was issued`);
  }
  return Object.freeze({ id, role, issuedAt, expiresAt });
}

/**
 * Whether a certificate is valid at an instant. Half-open `[issuedAt,
 * expiresAt)`: valid at issue, invalid at expiry.
 *
 * @param {Readonly<Certificate>} certificate
 * @param {Readonly<import('./time.js').Instant>} at
 * @returns {boolean}
 */
export function certificateValidAt(certificate, at) {
  requireInstant(at, 'certificateValidAt');
  return isWithin(at, certificate.issuedAt, certificate.expiresAt);
}

/* -------------------------------------------------------------------------
 * Crew members
 * ---------------------------------------------------------------------- */

/**
 * @typedef {object} CrewMember
 * @property {string} id opaque crew id; the only identity this system holds
 * @property {ReadonlyArray<Readonly<Certificate>>} certificates
 */

/**
 * Register a crew member as a set of certificates. Certificate ids must be
 * unique within the member.
 *
 * @param {{
 *   id: string,
 *   certificates?: ReadonlyArray<{
 *     id: string,
 *     role: string,
 *     issuedAtUtc: string,
 *     expiresAtUtc: string,
 *   }>,
 * }} spec
 * @returns {Readonly<CrewMember>}
 */
export function createCrewMember(spec) {
  if (spec === null || typeof spec !== 'object') {
    throw new TypeError('crew member spec must be an object');
  }
  const id = assertOpaqueId('crew id', spec.id);
  if (spec.certificates !== undefined && !Array.isArray(spec.certificates)) {
    throw new TypeError('crew member certificates must be an array');
  }
  const seen = new Set();
  const certificates = (spec.certificates ?? []).map((certSpec) => {
    const certificate = createCertificate(certSpec);
    if (seen.has(certificate.id)) {
      throw new RangeError(`duplicate certificate id on crew ${id}: ${certificate.id}`);
    }
    seen.add(certificate.id);
    return certificate;
  });
  return Object.freeze({ id, certificates: Object.freeze(certificates) });
}

/**
 * Certificates held for a role, regardless of validity.
 *
 * @param {Readonly<CrewMember>} crew
 * @param {CrewRole} role
 * @returns {ReadonlyArray<Readonly<Certificate>>}
 */
export function certificatesFor(crew, role) {
  assertCrewRole('role', role);
  return Object.freeze(crew.certificates.filter((certificate) => certificate.role === role));
}

/**
 * Whether a crew member holds a certificate valid for the role at that
 * instant.
 *
 * @param {Readonly<CrewMember>} crew
 * @param {CrewRole} role
 * @param {Readonly<import('./time.js').Instant>} at
 * @returns {boolean}
 */
export function qualifiedFor(crew, role, at) {
  assertCrewRole('role', role);
  requireInstant(at, 'qualifiedFor');
  return crew.certificates.some(
    (certificate) => certificate.role === role && certificateValidAt(certificate, at),
  );
}

/**
 * The certificate that qualifies a crew member for a role at an instant, if
 * any.
 *
 * @param {Readonly<CrewMember>} crew
 * @param {CrewRole} role
 * @param {Readonly<import('./time.js').Instant>} at
 * @returns {Readonly<Certificate>|null}
 */
export function qualifyingCertificate(crew, role, at) {
  assertCrewRole('role', role);
  requireInstant(at, 'qualifyingCertificate');
  return (
    crew.certificates.find(
      (certificate) => certificate.role === role && certificateValidAt(certificate, at),
    ) ?? null
  );
}

/**
 * Roles a crew member can fill at an instant.
 *
 * @param {Readonly<CrewMember>} crew
 * @param {Readonly<import('./time.js').Instant>} at
 * @returns {ReadonlyArray<CrewRole>}
 */
export function rolesAt(crew, at) {
  requireInstant(at, 'rolesAt');
  const roles = new Set();
  for (const certificate of crew.certificates) {
    if (certificateValidAt(certificate, at)) roles.add(certificate.role);
  }
  return Object.freeze([...roles].sort(compareStrings));
}

/* -------------------------------------------------------------------------
 * Watches
 * ---------------------------------------------------------------------- */

/** @typedef {'port'|'sea'} WatchKind */

const WATCH_KINDS = new Set(['port', 'sea']);

/**
 * @param {unknown} kind
 * @returns {WatchKind}
 */
export function assertWatchKind(kind) {
  if (typeof kind !== 'string' || !WATCH_KINDS.has(kind)) {
    throw new RangeError(`watch kind must be port or sea; got ${String(kind)}`);
  }
  return /** @type {WatchKind} */ (kind);
}

/**
 * Duration in whole minutes between two instants. Must be positive and an
 * exact number of minutes: the domain does not round.
 *
 * @param {Readonly<import('./time.js').Instant>} from
 * @param {Readonly<import('./time.js').Instant>} to
 * @returns {number}
 */
export function wholeMinutesBetween(from, to) {
  requireInstant(from, 'wholeMinutesBetween');
  requireInstant(to, 'wholeMinutesBetween');
  const delta = to.ms - from.ms;
  if (delta <= 0) {
    throw new RangeError('watch must end after it starts');
  }
  if (delta % 60_000 !== 0) {
    throw new RangeError('watch duration must be a whole number of minutes');
  }
  return delta / 60_000;
}

/**
 * A watch: a period during which the listed roles must be covered.
 *
 * @param {{
 *   id: string,
 *   kind: WatchKind,
 *   fromUtc: string,
 *   toUtc: string,
 *   requiredRoles: ReadonlyArray<string>,
 *   maxMinutes: number,
 * }} spec
 * @returns {Readonly<object>}
 */
export function defineWatch(spec) {
  if (spec === null || typeof spec !== 'object') {
    throw new TypeError('watch spec must be an object');
  }
  const id = assertOpaqueId('watch id', spec.id);
  const kind = assertWatchKind(spec.kind);
  const from = instant(spec.fromUtc);
  const to = instant(spec.toUtc);
  const minutes = wholeMinutesBetween(from, to);

  if (!Number.isInteger(spec.maxMinutes) || spec.maxMinutes <= 0) {
    throw new RangeError('watch maxMinutes must be a positive integer');
  }
  if (minutes > spec.maxMinutes) {
    throw new RangeError(
      `watch ${id} runs ${minutes} min, over its ${spec.maxMinutes} min limit`,
    );
  }

  if (!Array.isArray(spec.requiredRoles)) {
    throw new TypeError('watch requiredRoles must be an array');
  }
  const roles = [];
  for (const role of spec.requiredRoles) {
    const checked = assertCrewRole('required role', role);
    if (roles.includes(checked)) {
      throw new RangeError(`watch ${id} lists role ${checked} more than once`);
    }
    roles.push(checked);
  }

  return Object.freeze({
    id,
    kind,
    from,
    to,
    minutes,
    maxMinutes: spec.maxMinutes,
    requiredRoles: Object.freeze(roles),
  });
}

/* -------------------------------------------------------------------------
 * Assignment and coverage
 * ---------------------------------------------------------------------- */

/**
 * Assign crew to a watch and check coverage.
 *
 * `assignments` is a list of `{ crewId, role }`. Each entry names an opaque
 * crew id and the role it fills. Checks:
 *
 *  - every assigned role is one the watch requires;
 *  - every required role is filled exactly once;
 *  - a crew member fills at most one role on the watch;
 *  - every assigned crew member is known and qualified at the watch start.
 *
 * Qualification is evaluated at the watch start, which is the strictest
 * reading of the rule for a watch that must be fully crewed on joining.
 *
 * @param {Readonly<object>} watch
 * @param {{
 *   crew: Readonly<Record<string, Readonly<CrewMember>>>,
 *   assignments: ReadonlyArray<{ crewId: string, role: string }>,
 * }} spec
 * @returns {Readonly<object>}
 */
export function coverWatch(watch, spec) {
  if (watch === null || typeof watch !== 'object') {
    throw new TypeError('coverWatch requires a watch');
  }
  if (spec === null || typeof spec !== 'object' || !Array.isArray(spec.assignments)) {
    throw new TypeError('coverWatch requires { crew, assignments }');
  }
  const crewBy = spec.crew ?? {};
  const assignedRoles = new Map();
  const memberRoles = new Map();

  for (const assignment of spec.assignments) {
    if (assignment === null || typeof assignment !== 'object') {
      throw new TypeError('each assignment must be an object');
    }
    const crewId = assertOpaqueId('crew id', assignment.crewId);
    const role = assertCrewRole('assigned role', assignment.role);

    if (!watch.requiredRoles.includes(role)) {
      throw new RangeError(`watch ${watch.id} does not require role ${role}`);
    }
    if (assignedRoles.has(role)) {
      throw new RangeError(`role ${role} is filled more than once on watch ${watch.id}`);
    }
    if (memberRoles.has(crewId)) {
      throw new RangeError(
        `crew ${crewId} cannot fill both ${memberRoles.get(crewId)} and ${role}`,
      );
    }
    const member = crewBy[crewId];
    if (!member) {
      throw new RangeError(`unknown crew member: ${crewId}`);
    }
    if (!qualifiedFor(member, role, watch.from)) {
      throw new RangeError(
        `crew ${crewId} holds no valid ${role} certificate at the start of watch ${watch.id}`,
      );
    }
