    memberRoles.set(crewId, role);
  }

  const missing = watch.requiredRoles.filter((role) => !assignedRoles.has(role));
  if (missing.length > 0) {
    throw new RangeError(
      `watch ${watch.id} is short of ${missing.length} role(s): ${missing.join(', ')}`,
    );
  }

  return Object.freeze({
    watchId: watch.id,
    minutes: watch.minutes,
    coverage: Object.freeze(
      watch.requiredRoles.map((role) =>
        Object.freeze({ role, crewId: /** @type {string} */ (assignedRoles.get(role)) }),
      ),
    ),
  });
}

/**
 * Non-throwing coverage report: `{ ok: true, coverage }` or
 * `{ ok: false, reason }`. Useful for previewing a draft watch list.
 *
 * @param {Readonly<object>} watch
 * @param {Parameters<typeof coverWatch>[1]} spec
 * @returns {{ ok: true, report: Readonly<object> } | { ok: false, reason: string }}
 */
