import { describe, it, assert } from '../tests/helpers.js';

import {
  assertCrewRole,
  createCertificate,
  certificateValidAt,
  createCrewMember,
  certificatesFor,
  qualifiedFor,
  qualifyingCertificate,
  rolesAt,
  assertWatchKind,
  wholeMinutesBetween,
  defineWatch,
  coverWatch,
  inspectCoverage,
  qualifiedCrewFor,
  expiringCertificates,
  DEFAULT_WATCH_ROLES,
  requiredRolesFor,
  crewSailing,
} from '../src/domain/crew.js';
import { instant } from '../src/domain/time.js';
import { createSailing } from '../src/domain/sailings.js';
import { createVessel } from '../src/domain/vessels.js';
import { createBoard } from '../src/domain/board.js';

/* ---------------------------------------------------------------------- */

const t = (utc) => instant(utc);

function certificate(overrides = {}) {
  return createCertificate({
    id: 'cert-1',
    role: 'role-helm',
    issuedAtUtc: '2030-01-01T00:00:00Z',
    expiresAtUtc: '2030-06-01T00:00:00Z',
    ...overrides,
  });
}

function member(id, certificates = []) {
  return createCrewMember({ id, certificates });
}

/** Two crew, each qualified for both sea roles, valid all of 2030. */
function standardCrew() {
  const certs = (prefix) => [
    { id: `${prefix}-h`, role: 'role-helm', issuedAtUtc: '2030-01-01T00:00:00Z', expiresAtUtc: '2031-01-01T00:00:00Z' },
    { id: `${prefix}-e`, role: 'role-engine', issuedAtUtc: '2030-01-01T00:00:00Z', expiresAtUtc: '2031-01-01T00:00:00Z' },
  ];
  return {
    'crew-a': createCrewMember({ id: 'crew-a', certificates: certs('a') }),
    'crew-b': createCrewMember({ id: 'crew-b', certificates: certs('b') }),
  };
}

function seaWatch(overrides = {}) {
  return defineWatch({
    id: 'w-1',
    kind: 'sea',
    fromUtc: '2030-03-01T00:00:00Z',
    toUtc: '2030-03-01T04:00:00Z',
    requiredRoles: ['role-helm', 'role-engine'],
    maxMinutes: 240,
    ...overrides,
  });
}

/* ---------------------------------------------------------------------- */

describe('crew: identities carry no personal data', () => {
  it('stores only an opaque id and certificates', () => {
    const m = member('crew-1', [
      { id: 'c1', role: 'role-helm', issuedAtUtc: '2030-01-01T00:00:00Z', expiresAtUtc: '2030-06-01T00:00:00Z' },
    ]);
    assert.deepEqual(Object.keys(m).sort(), ['certificates', 'id']);
    assert.equal(m.id, 'crew-1');
    assert.ok(Object.isFrozen(m));
  });

  it('rejects attempts to smuggle a name field into the record', () => {
    const m = member('crew-1');
    // Even if a caller passes a name, it is not part of the crew record.
    const withName = createCrewMember({ id: 'crew-2', certificates: [], name: 'Not Stored' });
    assert.deepEqual(Object.keys(withName).sort(), ['certificates', 'id']);
    assert.equal(Object.keys(m).sort(), ['certificates', 'id']);
  });

  it('requires opaque crew ids', () => {
    assert.throws(() => member(''), RangeError);
    assert.throws(() => member(7), TypeError);
    assert.throws(() => createCrewMember(null), TypeError);
  });

  it('rejects duplicate certificate ids on one crew member', () => {
    assert.throws(
      () =>
        member('crew-1', [
          { id: 'c1', role: 'role-helm', issuedAtUtc: '2030-01-01T00:00:00Z', expiresAtUtc: '2030-06-01T00:00:00Z' },
          { id: 'c1', role: 'role-engine', issuedAtUtc: '2030-01-01T00:00:00Z', expiresAtUtc: '2030-06-01T00:00:00Z' },
        ]),
      RangeError,
    );
    assert.throws(() => createCrewMember({ id: 'c', certificates: 'nope' }), TypeError);
  });
});

describe('crew: roles', () => {
  it('treats roles as opaque tokens', () => {
    assert.equal(assertCrewRole('role', 'role-helm'), 'role-helm');
    assert.throws(() => assertCrewRole('role', ''), RangeError);
    assert.throws(() => assertCrewRole('role', 3), TypeError);
  });

  it('declares default roles per watch kind', () => {
    assert.deepEqual(DEFAULT_WATCH_ROLES.port, ['role-helm']);
    assert.deepEqual(DEFAULT_WATCH_ROLES.sea, ['role-helm', 'role-engine']);
    assert.ok(Object.isFrozen(DEFAULT_WATCH_ROLES));
  });

  it('honours per-kind overrides', () => {
    assert.deepEqual(requiredRolesFor({ sea: ['role-helm'] }, 'sea'), ['role-helm']);
    assert.deepEqual(requiredRolesFor(undefined, 'port'), ['role-helm']);
    assert.throws(() => requiredRolesFor({}, 'air'), RangeError);
  });
});

describe('crew: certificate expiry boundaries', () => {
  const cert = certificate();

  it('is valid at issue and invalid at expiry (half-open)', () => {
    assert.equal(certificateValidAt(cert, t('2030-01-01T00:00:00Z')), true, 'exactly at issue');
    assert.equal(certificateValidAt(cert, t('2030-01-01T00:00:01Z')), true);
    assert.equal(certificateValidAt(cert, t('2030-05-31T23:59:59Z')), true);
    assert.equal(certificateValidAt(cert, t('2030-06-01T00:00:00Z')), false, 'exactly at expiry');
    assert.equal(certificateValidAt(cert, t('2030-06-01T00:00:01Z')), false);
  });

  it('is invalid before issue', () => {
    assert.equal(certificateValidAt(cert, t('2029-12-31T23:59:59Z')), false);
  });

  it('requires expiry after issue', () => {
    assert.throws(
      () => certificate({ expiresAtUtc: '2030-01-01T00:00:00Z' }),
      RangeError,
      'zero-length',
    );
    assert.throws(() => certificate({ expiresAtUtc: '2029-01-01T00:00:00Z' }), RangeError);
  });

  it('requires UTC and opaque ids', () => {
    assert.throws(() => certificate({ issuedAtUtc: '2030-01-01T00:00:00+01:00' }), RangeError);
    assert.throws(() => certificate({ id: '' }), RangeError);
    assert.throws(() => certificate({ role: '' }), RangeError);
  });

  it('validates the query instant', () => {
    assert.throws(() => certificateValidAt(cert, null), TypeError);
    assert.throws(() => certificateValidAt(cert, { ms: 'x' }), TypeError);
  });
});

describe('crew: qualification', () => {
  const crew = member('crew-1', [
    { id: 'c-helm', role: 'role-helm', issuedAtUtc: '2030-01-01T00:00:00Z', expiresAtUtc: '2030-06-01T00:00:00Z' },
    { id: 'c-helm-renewal', role: 'role-helm', issuedAtUtc: '2030-05-01T00:00:00Z', expiresAtUtc: '2031-01-01T00:00:00Z' },
    { id: 'c-engine', role: 'role-engine', issuedAtUtc: '2030-03-01T00:00:00Z', expiresAtUtc: '2030-09-01T00:00:00Z' },
  ]);

  it('is qualified while a valid certificate covers the role', () => {
    assert.equal(qualifiedFor(crew, 'role-helm', t('2030-03-01T00:00:00Z')), true);
  });

  it('follows a renewal: the earlier expiry does not end qualification', () => {
    // c-helm expires 2030-06-01 but c-helm-renewal runs to 2031.
    assert.equal(qualifiedFor(crew, 'role-helm', t('2030-07-01T00:00:00Z')), true);
    assert.equal(qualifiedFor(crew, 'role-helm', t('2031-01-01T00:00:00Z')), false);
  });

  it('is unqualified before a certificate is issued', () => {
    assert.equal(qualifiedFor(crew, 'role-engine', t('2030-02-28T23:59:59Z')), false);
    assert.equal(qualifiedFor(crew, 'role-engine', t('2030-03-01T00:00:00Z')), true);
  });

  it('is unqualified for roles never held', () => {
    assert.equal(qualifiedFor(crew, 'role-medic', t('2030-03-01T00:00:00Z')), false);
  });

  it('returns the qualifying certificate', () => {
    assert.equal(qualifyingCertificate(crew, 'role-engine', t('2030-04-01T00:00:00Z')).id, 'c-engine');
    assert.equal(qualifyingCertificate(crew, 'role-medic', t('2030-04-01T00:00:00Z')), null);
  });

  it('lists roles held at an instant, in stable order', () => {
    assert.deepEqual(rolesAt(crew, t('2030-04-01T00:00:00Z')), ['role-engine', 'role-helm']);
    assert.deepEqual(rolesAt(crew, t('2032-01-01T00:00:00Z')), []);
  });

  it('filters certificates by role regardless of validity', () => {
    assert.deepEqual(certificatesFor(crew, 'role-helm').map((c) => c.id), ['c-helm', 'c-helm-renewal']);
    assert.deepEqual(certificatesFor(crew, 'role-medic'), []);
  });

  it('finds qualified crew in a roster', () => {
    const roster = { ...standardCrew(), 'crew-c': member('crew-c') };
    assert.deepEqual(qualifiedCrewFor(roster, 'role-helm', t('2030-05-01T00:00:00Z')), ['crew-a', 'crew-b']);
    assert.deepEqual(qualifiedCrewFor(roster, 'role-medic', t('2030-05-01T00:00:00Z')), []);
  });
});

describe('crew: expiring certificates', () => {
  const roster = {
    'crew-b': member('crew-b', [
      { id: 'b1', role: 'role-helm', issuedAtUtc: '2030-01-01T00:00:00Z', expiresAtUtc: '2030-04-01T00:00:00Z' },
    ]),
    'crew-a': member('crew-a', [
      { id: 'a1', role: 'role-engine', issuedAtUtc: '2030-01-01T00:00:00Z', expiresAtUtc: '2030-04-01T00:00:00Z' },
      { id: 'a2', role: 'role-helm', issuedAtUtc: '2030-01-01T00:00:00Z', expiresAtUtc: '2030-05-01T00:00:00Z' },
    ]),
  };

  it('reports expiries inside a half-open window, sorted by expiry then crew', () => {
    const result = expiringCertificates(roster, t('2030-04-01T00:00:00Z'), t('2030-06-01T00:00:00Z'));
    assert.deepEqual(
      result.map((r) => `${r.crewId}/${r.certificateId}`),
      ['crew-a/a1', 'crew-b/b1', 'crew-a/a2'],
      'ties on expiry sort by crew id',
    );
  });

  it('excludes an expiry exactly at the window end', () => {
    const result = expiringCertificates(roster, t('2030-01-01T00:00:00Z'), t('2030-04-01T00:00:00Z'));
    assert.deepEqual(result, []);
  });

  it('includes an expiry exactly at the window start', () => {
    const result = expiringCertificates(roster, t('2030-04-01T00:00:00Z'), t('2030-05-01T00:00:00Z'));
    assert.deepEqual(result.map((r) => r.certificateId), ['a1', 'b1']);
  });

  it('reports the role and ISO expiry', () => {
    const [first] = expiringCertificates(roster, t('2030-03-01T00:00:00Z'), t('2030-04-02T00:00:00Z'));
    assert.equal(first.role, 'role-engine');
    assert.equal(first.expiresAt, '2030-04-01T00:00:00.000Z');
  });

  it('validates instants', () => {
    assert.throws(() => expiringCertificates(roster, null, t('2030-05-01T00:00:00Z')), TypeError);
  });
});

describe('crew: watch duration', () => {
  it('counts whole minutes between instants', () => {
    assert.equal(wholeMinutesBetween(t('2030-01-01T00:00:00Z'), t('2030-01-01T04:00:00Z')), 240);
    assert.equal(wholeMinutesBetween(t('2030-01-01T00:00:00Z'), t('2030-01-01T00:01:00Z')), 1);
  });

  it('rejects zero, backwards and fractional durations', () => {
    assert.throws(() => wholeMinutesBetween(t('2030-01-01T00:00:00Z'), t('2030-01-01T00:00:00Z')), RangeError);
    assert.throws(() => wholeMinutesBetween(t('2030-01-01T04:00:00Z'), t('2030-01-01T00:00:00Z')), RangeError);
    assert.throws(() => wholeMinutesBetween(t('2030-01-01T00:00:00Z'), t('2030-01-01T00:00:30Z')), RangeError);
  });

  it('accepts a watch exactly at its limit', () => {
    const w = seaWatch({ maxMinutes: 240 });
    assert.equal(w.minutes, 240);
    assert.equal(w.maxMinutes, 240);
  });

  it('rejects a watch one minute over its limit', () => {
    assert.throws(() => seaWatch({ maxMinutes: 239 }), RangeError);
  });

  it('rejects a non-positive limit', () => {
    assert.throws(() => seaWatch({ maxMinutes: 0 }), RangeError);
    assert.throws(() => seaWatch({ maxMinutes: 1.5 }), RangeError);
  });

  it('rejects malformed watches', () => {
    assert.throws(() => defineWatch(null), TypeError);
    assert.throws(() => seaWatch({ kind: 'air' }), RangeError);
    assert.throws(() => assertWatchKind(''), RangeError);
    assert.throws(() => seaWatch({ requiredRoles: 'nope' }), TypeError);
    assert.throws(() => seaWatch({ requiredRoles: ['role-helm', 'role-helm'] }), RangeError, 'duplicate role');
    assert.throws(() => seaWatch({ id: '' }), RangeError);
  });
});

describe('crew: role coverage', () => {
  const crew = standardCrew();

  it('accepts full coverage with distinct crew', () => {
    const report = coverWatch(seaWatch(), {
      crew,
      assignments: [
        { crewId: 'crew-a', role: 'role-helm' },
        { crewId: 'crew-b', role: 'role-engine' },
      ],
    });
    assert.deepEqual(report.coverage, [
      { role: 'role-helm', crewId: 'crew-a' },
      { role: 'role-engine', crewId: 'crew-b' },
    ]);
    assert.equal(report.minutes, 240);
    assert.ok(Object.isFrozen(report));
  });

  it('accepts coverage listed in a different order', () => {
    const report = coverWatch(seaWatch(), {
      crew,
      assignments: [
        { crewId: 'crew-b', role: 'role-engine' },
        { crewId: 'crew-a', role: 'role-helm' },
      ],
    });
    assert.deepEqual(report.coverage.map((c) => c.role), ['role-helm', 'role-engine'], 'watch order preserved');
  });

  it('rejects a missing role', () => {
    assert.throws(
      () =>
        coverWatch(seaWatch(), {
          crew,
          assignments: [{ crewId: 'crew-a', role: 'role-helm' }],
        }),
      RangeError,
      'short of 1 role',
    );
  });

  it('rejects a role the watch does not require', () => {
    assert.throws(
      () =>
        coverWatch(seaWatch({ requiredRoles: ['role-helm'] }), {
          crew,
          assignments: [
            { crewId: 'crew-a', role: 'role-helm' },
            { crewId: 'crew-b', role: 'role-engine' },
          ],
        }),
      RangeError,
    );
  });

  it('rejects one person filling two roles', () => {
    assert.throws(
      () =>
        coverWatch(seaWatch(), {
          crew,
          assignments: [
            { crewId: 'crew-a', role: 'role-helm' },
            { crewId: 'crew-a', role: 'role-engine' },
          ],
        }),
      RangeError,
      'cannot fill both',
    );
  });

  it('rejects one role filled twice', () => {
    assert.throws(
      () =>
        coverWatch(seaWatch(), {
          crew,
          assignments: [
            { crewId: 'crew-a', role: 'role-helm' },
            { crewId: 'crew-b', role: 'role-helm' },
          ],
        }),
      RangeError,
      'filled more than once',
    );
  });

  it('rejects unknown crew', () => {
    assert.throws(
      () =>
        coverWatch(seaWatch(), {
          crew,
          assignments: [
            { crewId: 'crew-z', role: 'role-helm' },
            { crewId: 'crew-b', role: 'role-engine' },
          ],
        }),
      RangeError,
    );
  });

  it('rejects crew whose certificate has expired by the watch start', () => {
    const expiring = {
      'crew-a': member('crew-a', [
        { id: 'a-h', role: 'role-helm', issuedAtUtc: '2030-01-01T00:00:00Z', expiresAtUtc: '2030-03-01T00:00:00Z' },
      ]),
      'crew-b': crew['crew-b'],
    };
    assert.throws(
      () =>
        coverWatch(seaWatch(), {
          crew: expiring,
          assignments: [
            { crewId: 'crew-a', role: 'role-helm' },
            { crewId: 'crew-b', role: 'role-engine' },
          ],
        }),
      RangeError,
      'valid at watch start is required',
    );
  });

  it('allows a certificate that expires during the watch but was valid at its start', () => {
    const lapsing = {
      'crew-a': member('crew-a', [
        { id: 'a-h', role: 'role-helm', issuedAtUtc: '2030-01-01T00:00:00Z', expiresAtUtc: '2030-03-01T02:00:00Z' },
      ]),
      'crew-b': crew['crew-b'],
    };
    const report = coverWatch(seaWatch(), {
      crew: lapsing,
      assignments: [
        { crewId: 'crew-a', role: 'role-helm' },
        { crewId: 'crew-b', role: 'role-engine' },
      ],
    });
    assert.equal(report.watchId, 'w-1');
  });

  it('accepts a port watch needing only the helm', () => {
    const port = defineWatch({
      id: 'w-port',
      kind: 'port',
      fromUtc: '2030-03-01T00:00:00Z',
      toUtc: '2030-03-01T01:00:00Z',
      requiredRoles: requiredRolesFor(undefined, 'port'),
      maxMinutes: 60,
    });
    const report = coverWatch(port, { crew, assignments: [{ crewId: 'crew-a', role: 'role-helm' }] });
    assert.equal(report.coverage.length, 1);
  });

  it('validates its inputs', () => {
    assert.throws(() => coverWatch(null, { crew, assignments: [] }), TypeError);
    assert.throws(() => coverWatch(seaWatch(), null), TypeError);
    assert.throws(() => coverWatch(seaWatch(), { crew, assignments: 'x' }), TypeError);
    assert.throws(() => coverWatch(seaWatch(), { crew, assignments: [null] }), TypeError);
  });

  it('inspects coverage without throwing', () => {
    const good = inspectCoverage(seaWatch(), {
      crew,
      assignments: [
        { crewId: 'crew-a', role: 'role-helm' },
        { crewId: 'crew-b', role: 'role-engine' },
      ],
    });
    assert.equal(good.ok, true);

    const bad = inspectCoverage(seaWatch(), { crew, assignments: [] });
    assert.equal(bad.ok, false);
    assert.ok(bad.reason.includes('short of'));
  });
});

describe('crew: sailing-level checks', () => {
  const vessel = createVessel({ id: 'v-1', capacityKg: 1000 });
  const sailing = createSailing(
