      id: 's-1',
      vesselId: 'v-1',
      routeId: 'r-1',
      originPortId: 'p-north',
      destinationPortId: 'p-south',
      departsAtUtc: '2030-03-01T00:00:00Z',
      arrivesAtUtc: '2030-03-01T08:00:00Z',
    },
    { vessel },
  );
  const crew = standardCrew();
  const assignments = [
    [
      { crewId: 'crew-a', role: 'role-helm' },
      { crewId: 'crew-b', role: 'role-engine' },
    ],
    [
      { crewId: 'crew-b', role: 'role-helm' },
      { crewId: 'crew-a', role: 'role-engine' },
    ],
  ];

  function watches(total = 480) {
    const half = total / 2;
    const mid = new Date(Date.parse('2030-03-01T00:00:00Z') + half * 60_000).toISOString();
    return [
      defineWatch({ id: 'w-1', kind: 'sea', fromUtc: '2030-03-01T00:00:00Z', toUtc: mid, requiredRoles: ['role-helm', 'role-engine'], maxMinutes: half }),
      defineWatch({ id: 'w-2', kind: 'sea', fromUtc: mid, toUtc: '2030-03-01T08:00:00Z', requiredRoles: ['role-helm', 'role-engine'], maxMinutes: half }),
    ];
  }

  it('covers a sailing exactly to its length', () => {
    const report = crewSailing(sailing, watches(480), crew, assignments);
    assert.equal(report.sailingMinutes, 480);
    assert.equal(report.watchMinutes, 480);
    assert.equal(report.watches.length, 2);
    assert.ok(Object.isFrozen(report));
  });

  it('rejects watches longer than the sailing', () => {
    assert.throws(() => crewSailing(sailing, watches(480), crew, assignments) === undefined, assert.AssertionError);
    const overlong = watches(480);
    const stretched = [
      overlong[0],
      defineWatch({ id: 'w-2', kind: 'sea', fromUtc: overlong[1].from.utc, toUtc: '2030-03-01T09:00:00Z', requiredRoles: ['role-helm', 'role-engine'], maxMinutes: 540 }),
    ];
    assert.throws(() => crewSailing(sailing, stretched, crew, [[], []]), RangeError);
  });

  it('requires one assignment list per watch', () => {
    assert.throws(() => crewSailing(sailing, watches(480), crew, [assignments[0]]), RangeError);
    assert.throws(() => crewSailing(null, watches(480), crew, assignments), TypeError);
    assert.throws(() => crewSailing(sailing, 'x', crew, assignments), TypeError);
  });

  it('propagates coverage failures', () => {
    assert.throws(
      () => crewSailing(sailing, watches(480), crew, [[assignments[0][0]], assignments[1]]),
      RangeError,
    );
  });

  it('integrates with the board', () => {
    const board = createBoard({ startUtc: '2030-01-01T00:00:00Z' });
    board.addVessel({ id: 'v-1', capacityKg: 1000 });
    board.addSailing({
