/**
 * Operator example: crewing a sailing under qualification rules.
 *
 * Fictional data only. Run with: node examples/crew-example.js
 *
 * Crew are anonymous duty identities: an opaque id and certificates. No names,
 * contacts or other personal details exist in this system.
 */

import {
  createCrewMember,
  defineWatch,
  coverWatch,
  inspectCoverage,
  qualifiedCrewFor,
  expiringCertificates,
  requiredRolesFor,
  instant,
} from '../src/index.js';

const t = (utc) => instant(utc);

// --- Two anonymous duty identities, with certificates. ------------------

const crew = {
  'crew-alpha': createCrewMember({
    id: 'crew-alpha',
    certificates: [
      { id: 'ca-helm', role: 'role-helm', issuedAtUtc: '2030-01-01T00:00:00Z', expiresAtUtc: '2030-04-01T00:00:00Z' },
      { id: 'ca-engine', role: 'role-engine', issuedAtUtc: '2030-01-01T00:00:00Z', expiresAtUtc: '2031-01-01T00:00:00Z' },
    ],
  }),
  'crew-bravo': createCrewMember({
    id: 'crew-bravo',
    certificates: [
      { id: 'cb-helm', role: 'role-helm', issuedAtUtc: '2030-01-01T00:00:00Z', expiresAtUtc: '2031-01-01T00:00:00Z' },
    ],
  }),
};

console.log('qualified for the sea watch at 2030-03-01T00:00Z:');
for (const role of requiredRolesFor(undefined, 'sea')) {
  console.log(`  ${role}: ${qualifiedCrewFor(crew, role, t('2030-03-01T00:00:00Z')).join(', ') || '(none)'}`);
}

// --- The watch itself. --------------------------------------------------

const watch = defineWatch({
  id: 'w-sea',
  kind: 'sea',
  fromUtc: '2030-03-01T00:00:00Z',
  toUtc: '2030-03-01T04:00:00Z',
  requiredRoles: requiredRolesFor(undefined, 'sea'),
  maxMinutes: 240,
});
console.log(`\nwatch ${watch.id}: ${watch.minutes} min, needs ${watch.requiredRoles.join(' + ')}`);

const report = coverWatch(watch, {
  crew,
  assignments: [
    { crewId: 'crew-alpha', role: 'role-engine' },
    { crewId: 'crew-bravo', role: 'role-helm' },
  ],
});
console.log('covered:');
for (const entry of report.coverage) {
  console.log(`  ${entry.role} -> ${entry.crewId}`);
}

