/**
 * The maintenance planner.
 *
 * A hull is unavailable while it is in maintenance. Two kinds of window
 * matter to planning:
 *
 *  1. **Planned downtime** — scheduled work with a known UTC window. It blocks
 *     any sailing that overlaps it, and it can be planned ahead of time so
 *     that new sailings avoid it.
 *  2. **Emergency withdrawals** — an unplanned stoppage. The window may not be
 *     known precisely at first, so a withdrawal records the earliest instant
 *     the hull became unavailable and an optional expected return. A
 *     withdrawal with no expected return blocks everything after it.
 *
 * Windows are half-open `[from, to)`, consistent with closures, tide windows
 * and planning horizons: a sailing that ends exactly when downtime begins does
 * not overlap it, and one that departs exactly when downtime ends does not
 * either.
 *
 * A **sailing is affected** when its execution overlaps the window. Overlap is
 * measured against the sailing's whole span `[departsAt, arrivesAt)`, because a
 * hull that is in pieces at departure cannot sail, and one withdrawn mid-passage
 * puts the passage itself at risk.
 *
 * Nothing here reads the clock: every timestamp is caller-supplied.
 */

import { assertOpaqueId } from './ids.js';
import { assertPortId } from '../ports.js';
import { instant } from './time.js';
import { isCancellable } from './sailing-state.js';

/** @typedef {'planned'|'emergency'} DowntimeKind */

const KINDS = new Set(['planned', 'emergency']);

/**
 * @param {unknown} kind
 * @returns {DowntimeKind}
 */
export function assertDowntimeKind(kind) {
  if (typeof kind !== 'string' || !KINDS.has(kind)) {
    throw new RangeError(`downtime kind must be planned or emergency; got ${String(kind)}`);
  }
  return /** @type {DowntimeKind} */ (kind);
}

/**
 * @typedef {object} DowntimeWindow
 * @property {string} id opaque window id
 * @property {string} vesselId
 * @property {DowntimeKind} kind
 * @property {Readonly<import('./time.js').Instant>} from inclusive start
 * @property {Readonly<import('./time.js').Instant>|null} to exclusive end; null means open-ended
 * @property {string|null} reason operator-facing description
 */

/**
 * Define a downtime window.
 *
 * `toUtc` may be omitted for an emergency withdrawal whose return is unknown;
 * the window then extends indefinitely. A planned window must have an end.
 *
 * @param {{
 *   id: string,
 *   vesselId: string,
 *   kind: DowntimeKind,
 *   fromUtc: string,
 *   toUtc?: string,
 *   reason?: string,
 * }} spec
 * @returns {Readonly<DowntimeWindow>}
 */
export function defineDowntime(spec) {
  if (spec === null || typeof spec !== 'object') {
    throw new TypeError('downtime spec must be an object');
  }
  const id = assertOpaqueId('downtime id', spec.id);
  const vesselId = assertOpaqueId('vessel id', spec.vesselId);
  const kind = assertDowntimeKind(spec.kind);
  const from = instant(spec.fromUtc);

  if (spec.toUtc === undefined || spec.toUtc === null) {
    if (kind === 'planned') {
      throw new RangeError(`planned downtime ${id} must have an end instant`);
    }
  }
  const to = spec.toUtc === undefined || spec.toUtc === null ? null : instant(spec.toUtc);
  if (to !== null && to.ms <= from.ms) {
    throw new RangeError(`downtime ${id} must end after it starts`);
  }
  if (spec.reason !== undefined && typeof spec.reason !== 'string') {
    throw new TypeError('downtime reason must be a string');
  }
  const reason = spec.reason === undefined || spec.reason.length === 0 ? null : spec.reason;

  return Object.freeze({ id, vesselId, kind, from, to, reason });
}

/**
 * Whether a half-open span `[spanFrom, spanTo)` overlaps a downtime window.
 * An open-ended window overlaps every span that ends after it starts.
 *
 * @param {Readonly<DowntimeWindow>} window
 * @param {Readonly<import('./time.js').Instant>} spanFrom
 * @param {Readonly<import('./time.js').Instant>} spanTo
 * @returns {boolean}
 */
export function downtimeOverlaps(window, spanFrom, spanTo) {
  requireInstant(spanFrom, 'downtimeOverlaps');
  requireInstant(spanTo, 'downtimeOverlaps');
  if (spanTo.ms <= spanFrom.ms) {
    throw new RangeError('overlap span must end after it starts');
  }
  const windowEndMs = window.to === null ? Infinity : window.to.ms;
  return spanFrom.ms < windowEndMs && spanTo.ms > window.from.ms;
}

/**
 * Whether a sailing is affected by a downtime window: same hull, overlapping
 * span, and not already cancelled before the window began.
 *
 * A sailing that is already `cancelled` or `arrived` cannot be further
 * affected; it is reported separately by `affectedSailings`.
 *
 * @param {Readonly<DowntimeWindow>} window
 * @param {Readonly<import('./sailings.js').Sailing>} sailing
 * @returns {boolean}
 */
export function sailingAffectedBy(window, sailing) {
  if (sailing === null || typeof sailing !== 'object') {
    throw new TypeError('sailingAffectedBy requires a sailing');
  }
  if (sailing.vesselId !== window.vesselId) return false;
  return downtimeOverlaps(window, sailing.departsAt, sailing.arrivesAt);
}

/**
 * Build the maintenance record for one hull.
 *
 * Windows on the same hull may abut but may not overlap: two simultaneous
 * outages would make the return time ambiguous. An open-ended window swallows
 * every later window and is rejected as a conflict.
 *
 * @param {{
 *   vesselId: string,
 *   windows: ReadonlyArray<Parameters<typeof defineDowntime>[0]>,
 * }} spec
 * @returns {Readonly<object>}
 */
export function createMaintenancePlan(spec) {
  if (spec === null || typeof spec !== 'object') {
    throw new TypeError('maintenance plan spec must be an object');
  }
  const vesselId = assertPortIdOrVessel(spec.vesselId);
  if (!Array.isArray(spec.windows)) {
    throw new TypeError('maintenance plan windows must be an array');
  }

  /** @type {Map<string, Readonly<DowntimeWindow>>} */
  const byId = new Map();
  /** @type {DowntimeWindow[]} */
  const windows = [];

  for (const windowSpec of spec.windows) {
    if (
      windowSpec !== null &&
      typeof windowSpec === 'object' &&
      windowSpec.vesselId !== undefined &&
      windowSpec.vesselId !== vesselId
    ) {
      throw new RangeError(
        `downtime ${String(windowSpec.id)} names vessel ${String(windowSpec.vesselId)}, ` +
          `not ${vesselId}`,
      );
    }
    const window = defineDowntime({ ...windowSpec, vesselId });
    if (byId.has(window.id)) {
      throw new RangeError(`duplicate downtime id: ${window.id}`);
    }
    byId.set(window.id, window);
    windows.push(window);
  }

  // Deterministic order: by start, then id.
  windows.sort((a, b) => a.from.ms - b.from.ms || compareStrings(a.id, b.id));

  for (let i = 1; i < windows.length; i += 1) {
    const previous = windows[i - 1];
    const current = windows[i];
    const previousEndMs = previous.to === null ? Infinity : previous.to.ms;
    if (current.from.ms < previousEndMs) {
      throw new RangeError(
        `downtime windows ${previous.id} and ${current.id} overlap on vessel ${vesselId}`,
      );
    }
  }

  const api = {
    vesselId,

    /** @returns {ReadonlyArray<Readonly<DowntimeWindow>>} */
    windows() {
      return Object.freeze([...windows]);
    },

    /**
     * @param {string} windowId
     * @returns {Readonly<DowntimeWindow>}
     */
    requireWindow(windowId) {
      const window = byId.get(windowId);
      if (!window) {
        throw new RangeError(`unknown downtime window: ${String(windowId)}`);
      }
      return window;
    },

    /**
     * Whether the hull is unavailable at an instant.
     *
     * @param {Readonly<import('./time.js').Instant>} at
     * @returns {Readonly<DowntimeWindow>|null}
     */
    downtimeAt(at) {
      requireInstant(at, 'downtimeAt');
      for (const window of windows) {
        const endMs = window.to === null ? Infinity : window.to.ms;
        if (at.ms >= window.from.ms && at.ms < endMs) return window;
      }
      return null;
    },

    /**
     * Whether a sailing on this hull would be blocked by any window.
     *
     * @param {Readonly<import('./sailings.js').Sailing>} sailing
     * @returns {Readonly<DowntimeWindow>|null}
     */
    blocksSailing(sailing) {
      if (sailing === null || typeof sailing !== 'object') {
        throw new TypeError('blocksSailing requires a sailing');
      }
      if (sailing.vesselId !== vesselId) {
        throw new RangeError(
          `sailing ${sailing.id} is on vessel ${sailing.vesselId}, not ${vesselId}`,
        );
      }
      for (const window of windows) {
        if (downtimeOverlaps(window, sailing.departsAt, sailing.arrivesAt)) return window;
      }
      return null;
    },

    /**
     * The first instant at or after `from` when the hull is free. Scans the
     * recorded windows only; it never extrapolates.
     *
     * @param {Readonly<import('./time.js').Instant>} from
     * @returns {{ freeAtMs: number }|null} null when an open-ended window
     *   covers `from`
     */
    nextFreeAt(from) {
      requireInstant(from, 'nextFreeAt');
      let cursor = from.ms;
      for (const window of windows) {
        const endMs = window.to === null ? Infinity : window.to.ms;
        if (endMs <= cursor) continue;
        if (window.from.ms > cursor) return Object.freeze({ freeAtMs: cursor });
        if (window.to === null) return null;
        cursor = window.to.ms;
      }
      return Object.freeze({ freeAtMs: cursor });
    },
  };

  return Object.freeze(api);
}

/**
 * Add an emergency withdrawal for a hull. Convenience wrapper that keeps the
 * `kind` correct and requires the replacement window to end after it starts.
 *
 * @param {{
 *   id: string,
 *   vesselId: string,
 *   fromUtc: string,
 *   expectedReturnUtc?: string,
 *   reason?: string,
 * }} spec
 * @returns {Readonly<DowntimeWindow>}
 */
export function withdrawVessel(spec) {
  if (spec === null || typeof spec !== 'object') {
    throw new TypeError('withdrawal spec must be an object');
  }
  return defineDowntime({
    id: spec.id,
    vesselId: spec.vesselId,
    kind: 'emergency',
    fromUtc: spec.fromUtc,
    toUtc: spec.expectedReturnUtc,
    reason: spec.reason,
  });
}

/**
 * Report which sailings are affected by a set of downtime windows.
 *
 * Sailings already `cancelled` or `arrived` are not reported as affected,
 * because nothing can be done about them; they are listed separately so the
 * report is complete rather than merely actionable.
 *
 * @param {ReadonlyArray<Readonly<import('./sailings.js').Sailing>>} sailings
 * @param {ReadonlyArray<Readonly<DowntimeWindow>>} windows
 * @returns {Readonly<{
 *   affected: ReadonlyArray<{ sailingId: string, vesselId: string, windowId: string, status: string, cancellable: boolean, departsAtUtc: string, arrivesAtUtc: string }>,
 *   unaffected: ReadonlyArray<{ sailingId: string, vesselId: string, windowId: string, status: string }>,
 * }>}
 */
export function affectedSailings(sailings, windows) {
  if (!Array.isArray(sailings)) {
    throw new TypeError('affectedSailings requires an array of sailings');
  }
  if (!Array.isArray(windows)) {
    throw new TypeError('affectedSailings requires an array of windows');
  }

  const affected = [];
  const unaffected = [];

  for (const sailing of [...sailings].sort((a, b) => compareStrings(a.id, b.id))) {
    for (const window of windows) {
      if (!sailingAffectedBy(window, sailing)) continue;
      const settled = sailing.status === 'cancelled' || sailing.status === 'arrived';
      if (settled) {
        unaffected.push(
          Object.freeze({
            sailingId: sailing.id,
            vesselId: sailing.vesselId,
            windowId: window.id,
            status: sailing.status,
          }),
        );
        continue;
      }
      affected.push(
        Object.freeze({
          sailingId: sailing.id,
          vesselId: sailing.vesselId,
          windowId: window.id,
          status: sailing.status,
          cancellable: isCancellable(sailing.status),
          departsAtUtc: sailing.departsAt.utc,
          arrivesAtUtc: sailing.arrivesAt.utc,
        }),
      );
    }
  }

  return Object.freeze({
    affected: Object.freeze(affected),
    unaffected: Object.freeze(unaffected),
  });
}

/**
 * @param {unknown} value
 * @returns {string}
 */
function assertPortIdOrVessel(value) {
  // Vessel ids follow the same opaque-string rules as port ids; delegate to
  // the shared assertion so the message names the right concept.
  return assertOpaqueId('vessel id', value);
}

/**
 * @param {unknown} value
 * @param {string} what
 * @returns {void}
 */
function requireInstant(value, what) {
  if (value === null || typeof value !== 'object' || typeof value.ms !== 'number') {
    throw new TypeError(`${what} requires an explicit UTC instant`);
  }
}

/**
 * @param {string} a
 * @param {string} b
 * @returns {number}
 */
function compareStrings(a, b) {
  if (a < b) return -1;
  if (a > b) return 1;
  return 0;
}

// Re-exported so callers do not need a second import for vessel id checks.
export { assertPortId as assertVesselId };

