import { createCrewMember, crewSailing } from './crew.js';
import {
  createMaintenancePlan,
  withdrawVessel,
  affectedSailings as reportAffectedSailings,
} from './maintenance.js';

  crew: new Map(),
  downtime: new Map(),
};

export {
  assertDowntimeKind,
  defineDowntime,
  downtimeOverlaps,
  sailingAffectedBy,
  createMaintenancePlan,
  withdrawVessel,
  affectedSailings,
} from './domain/maintenance.js';
export { createBoard } from './domain/board.js';

/**
 * Record planned downtime for a hull on the board. The plan replaces any
 * previous windows for that hull, so callers pass the complete set.
 *
 * @param {Board} board
 * @param {{ vesselId: string, windows: ReadonlyArray<any> }} spec
 */
function addDowntime(board, spec) {
  const plan = createMaintenancePlan(spec);
  if (board.downtime.has(plan.vesselId)) {
    throw new RangeError(`duplicate downtime plan for vessel: ${plan.vesselId}`);
  }
  board.downtime.set(plan.vesselId, plan);
  return plan;
}

/**
 * Withdraw a hull in an emergency and report what it affects. The withdrawal
 * is appended to the hull's plan (creating one if needed).
 *
 * @param {Board} board
 * @param {{ id: string, vesselId: string, fromUtc: string, expectedReturnUtc?: string, reason?: string }} spec
 */
function withdrawVesselOnBoard(board, spec) {
  const window = withdrawVessel(spec);
  const existing = board.downtime.get(window.vesselId);
  const previous = existing ? existing.windows() : [];
  const plan = createMaintenancePlan({
    vesselId: window.vesselId,
    windows: [...previous, window],
  });
  board.downtime.set(window.vesselId, plan);
  return Object.freeze({ window, plan });
}

/**
 * @param {Board} board
 * @param {string} vesselId
 */
function affectedSailingsOnBoard(board, vesselId) {
  const plan = board.downtime.get(vesselId);
  if (!plan) {
    throw new RangeError(`no downtime recorded for vessel: ${String(vesselId)}`);
  }
  const sailings = [...board.sailings.values()].filter((s) => s.vesselId === vesselId);
  return reportAffectedSailings(sailings, plan.windows());
}

/**
 * Cancel every affected, still-cancellable sailing for a hull at a supplied
 * UTC instant, and report what changed.
 *
 * @param {Board} board
 * @param {string} vesselId
 * @param {string} atUtc
 */
function cancelAffectedSailingsOnBoard(board, vesselId, atUtc) {
  const report = affectedSailingsOnBoard(board, vesselId);
  const cancelled = [];
  const skipped = [];
  for (const entry of report.affected) {
    if (!entry.cancellable) {
      skipped.push(Object.freeze({ sailingId: entry.sailingId, status: entry.status }));
      continue;
    }
    const next = transitionSailing(board, entry.sailingId, 'cancelled', {
      atUtc,
      note: `maintenance ${entry.windowId}`,
    });
    cancelled.push(Object.freeze({ sailingId: next.id, status: next.status }));
  }
  return Object.freeze({
    cancelled: Object.freeze(cancelled),
    skipped: Object.freeze(skipped),
    unaffected: report.unaffected,
  });
}

