import { describe, it, assert } from '../tests/helpers.js';

import {
  assertDowntimeKind,
  defineDowntime,
  downtimeOverlaps,
  sailingAffectedBy,
  createMaintenancePlan,
  withdrawVessel,
  affectedSailings,
} from '../src/domain/maintenance.js';
import { instant } from '../src/domain/time.js';
import { createSailing } from '../src/domain/sailings.js';
import { createVessel } from '../src/domain/vessels.js';
import { createBoard } from '../src/domain/board.js';

/* ---------------------------------------------------------------------- */

const t = (utc) => instant(utc);

function downtime(overrides = {}) {
  return defineDowntime({
    id: 'd-1',
    vesselId: 'v-1',
    kind: 'planned',
    fromUtc: '2030-01-10T00:00:00Z',
    toUtc: '2030-01-12T00:00:00Z',
    ...overrides,
  });
}

const vessel = createVessel({ id: 'v-1', capacityKg: 1000 });

function sailing(overrides = {}) {
  return createSailing(
    {
      id: 's-1',
      vesselId: 'v-1',
      routeId: 'r-1',
      originPortId: 'p-north',
      destinationPortId: 'p-south',
      departsAtUtc: '2030-01-05T00:00:00Z',
      arrivesAtUtc: '2030-01-06T00:00:00Z',
      ...overrides,
    },
    { vessel },
  );
}

/* ---------------------------------------------------------------------- */

describe('maintenance: kinds', () => {
  it('accepts exactly two kinds', () => {
    for (const kind of ['planned', 'emergency']) {
      assert.equal(assertDowntimeKind(kind), kind);
    }
    assert.throws(() => assertDowntimeKind('refit'), RangeError);
    assert.throws(() => assertDowntimeKind(''), RangeError);
    assert.throws(() => assertDowntimeKind(undefined), RangeError);
  });
});

describe('maintenance: window definition', () => {
  it('defines a planned window with opaque ids and UTC bounds', () => {
    const w = downtime({ reason: 'hull survey' });
    assert.deepEqual(
      {
        id: w.id,
        vesselId: w.vesselId,
        kind: w.kind,
        from: w.from.utc,
        to: w.to.utc,
        reason: w.reason,
      },
      {
        id: 'd-1',
        vesselId: 'v-1',
        kind: 'planned',
        from: '2030-01-10T00:00:00.000Z',
        to: '2030-01-12T00:00:00.000Z',
        reason: 'hull survey',
      },
    );
    assert.ok(Object.isFrozen(w));
  });

  it('requires planned downtime to have an end', () => {
    assert.throws(() => downtime({ toUtc: undefined }), RangeError, 'planned without end');
    assert.throws(() => downtime({ toUtc: null }), RangeError, 'planned null end');
  });

  it('allows an emergency withdrawal with no known return', () => {
    const w = downtime({ kind: 'emergency', toUtc: undefined });
    assert.equal(w.to, null);
    assert.equal(w.kind, 'emergency');
  });

  it('rejects zero-length and backwards windows', () => {
    assert.throws(() => downtime({ toUtc: '2030-01-10T00:00:00Z' }), RangeError);
    assert.throws(() => downtime({ toUtc: '2030-01-09T00:00:00Z' }), RangeError);
  });

  it('requires UTC, opaque ids and a string reason', () => {
    assert.throws(() => downtime({ fromUtc: '2030-01-10T00:00:00+01:00' }), RangeError);
    assert.throws(() => downtime({ id: '' }), RangeError);
    assert.throws(() => downtime({ vesselId: '' }), RangeError);
    assert.throws(() => downtime({ reason: 5 }), TypeError);
    assert.throws(() => defineDowntime(null), TypeError);
  });

  it('defaults the reason to null', () => {
    assert.equal(downtime().reason, null);
  });
});

describe('maintenance: half-open overlap', () => {
  const w = downtime(); // [Jan 10, Jan 12)

  it('does not overlap a span that ends exactly at the start', () => {
    assert.equal(downtimeOverlaps(w, t('2030-01-09T00:00:00Z'), t('2030-01-10T00:00:00Z')), false);
  });

  it('overlaps a span that starts exactly at the start', () => {
    assert.equal(downtimeOverlaps(w, t('2030-01-10T00:00:00Z'), t('2030-01-11T00:00:00Z')), true);
  });

  it('overlaps a span that begins inside the window', () => {
    assert.equal(downtimeOverlaps(w, t('2030-01-11T00:00:00Z'), t('2030-01-13T00:00:00Z')), true);
  });

  it('does not overlap a span that starts exactly at the end', () => {
    assert.equal(downtimeOverlaps(w, t('2030-01-12T00:00:00Z'), t('2030-01-13T00:00:00Z')), false);
  });

  it('overlaps a span that wholly contains the window', () => {
    assert.equal(downtimeOverlaps(w, t('2030-01-01T00:00:00Z'), t('2030-02-01T00:00:00Z')), true);
  });

  it('treats an open-ended window as covering everything after its start', () => {
    const open = downtime({ kind: 'emergency', toUtc: undefined });
    assert.equal(downtimeOverlaps(open, t('2029-01-01T00:00:00Z'), t('2030-01-10T00:00:00Z')), false, 'ends exactly at start');
    assert.equal(downtimeOverlaps(open, t('2030-01-10T00:00:00Z'), t('2030-01-11T00:00:00Z')), true);
    assert.equal(downtimeOverlaps(open, t('2040-01-01T00:00:00Z'), t('2040-01-02T00:00:00Z')), true);
  });

  it('rejects a degenerate span', () => {
    assert.throws(() => downtimeOverlaps(w, t('2030-01-10T00:00:00Z'), t('2030-01-10T00:00:00Z')), RangeError);
    assert.throws(() => downtimeOverlaps(w, null, t('2030-01-10T00:00:00Z')), TypeError);
  });
});

describe('maintenance: sailing affectedness', () => {
  const w = downtime();

  it('affects a sailing that overlaps the window', () => {
    assert.equal(sailingAffectedBy(w, sailing({ departsAtUtc: '2030-01-09T00:00:00Z', arrivesAtUtc: '2030-01-11T00:00:00Z' })), true);
  });

  it('ignores a sailing that ends exactly when downtime starts', () => {
    assert.equal(sailingAffectedBy(w, sailing({ departsAtUtc: '2030-01-08T00:00:00Z', arrivesAtUtc: '2030-01-10T00:00:00Z' })), false);
  });

  it('ignores a sailing that departs exactly when downtime ends', () => {
    assert.equal(sailingAffectedBy(w, sailing({ departsAtUtc: '2030-01-12T00:00:00Z', arrivesAtUtc: '2030-01-13T00:00:00Z' })), false);
  });

  it('ignores sailings on other hulls', () => {
    const other = createVessel({ id: 'v-2', capacityKg: 1000 });
    const elsewhere = createSailing(
      {
        id: 's-2',
        vesselId: 'v-2',
        routeId: 'r-1',
        originPortId: 'p-north',
        destinationPortId: 'p-south',
        departsAtUtc: '2030-01-10T00:00:00Z',
        arrivesAtUtc: '2030-01-11T00:00:00Z',
      },
      { vessel: other },
    );
    assert.equal(sailingAffectedBy(w, elsewhere), false);
  });

  it('validates its inputs', () => {
    assert.throws(() => sailingAffectedBy(w, null), TypeError);
  });
});

describe('maintenance: plans', () => {
  it('sorts windows and rejects overlapping ones', () => {
    const plan = createMaintenancePlan({
      vesselId: 'v-1',
      windows: [
        { id: 'd-late', kind: 'planned', fromUtc: '2030-02-01T00:00:00Z', toUtc: '2030-02-03T00:00:00Z' },
        { id: 'd-early', kind: 'planned', fromUtc: '2030-01-01T00:00:00Z', toUtc: '2030-01-03T00:00:00Z' },
      ],
    });
    assert.deepEqual(plan.windows().map((w) => w.id), ['d-early', 'd-late']);
    assert.ok(Object.isFrozen(plan.windows()));
  });

  it('accepts abutting windows', () => {
    const plan = createMaintenancePlan({
      vesselId: 'v-1',
      windows: [
        { id: 'd-1', kind: 'planned', fromUtc: '2030-01-01T00:00:00Z', toUtc: '2030-01-03T00:00:00Z' },
        { id: 'd-2', kind: 'planned', fromUtc: '2030-01-03T00:00:00Z', toUtc: '2030-01-05T00:00:00Z' },
      ],
    });
    assert.equal(plan.windows().length, 2);
  });

  it('rejects overlapping windows', () => {
    assert.throws(
      () =>
        createMaintenancePlan({
          vesselId: 'v-1',
          windows: [
            { id: 'd-1', kind: 'planned', fromUtc: '2030-01-01T00:00:00Z', toUtc: '2030-01-05T00:00:00Z' },
            { id: 'd-2', kind: 'planned', fromUtc: '2030-01-04T00:00:00Z', toUtc: '2030-01-08T00:00:00Z' },
          ],
        }),
      RangeError,
    );
  });

  it('lets an open-ended window swallow every later window', () => {
    assert.throws(
      () =>
        createMaintenancePlan({
          vesselId: 'v-1',
          windows: [
            { id: 'd-1', kind: 'emergency', fromUtc: '2030-01-01T00:00:00Z' },
            { id: 'd-2', kind: 'planned', fromUtc: '2030-02-01T00:00:00Z', toUtc: '2030-02-03T00:00:00Z' },
          ],
        }),
      RangeError,
    );
  });

  it('rejects duplicate ids and foreign vessels', () => {
    assert.throws(
      () =>
        createMaintenancePlan({
          vesselId: 'v-1',
          windows: [
            { id: 'd-1', kind: 'planned', fromUtc: '2030-01-01T00:00:00Z', toUtc: '2030-01-02T00:00:00Z' },
            { id: 'd-1', kind: 'planned', fromUtc: '2030-01-03T00:00:00Z', toUtc: '2030-01-04T00:00:00Z' },
          ],
        }),
      RangeError,
    );
    assert.throws(
      () =>
        createMaintenancePlan({
          vesselId: 'v-1',
          windows: [
            { id: 'd-1', vesselId: 'v-2', kind: 'planned', fromUtc: '2030-01-01T00:00:00Z', toUtc: '2030-01-02T00:00:00Z' },
          ],
        }),
      RangeError,
    );
  });

  it('rejects malformed specs and allows an empty plan', () => {
    assert.throws(() => createMaintenancePlan(null), TypeError);
    assert.throws(() => createMaintenancePlan({ vesselId: 'v-1', windows: 'x' }), TypeError);
    assert.throws(() => createMaintenancePlan({ vesselId: '', windows: [] }), RangeError);
    assert.deepEqual(createMaintenancePlan({ vesselId: 'v-1', windows: [] }).windows(), []);
  });

  it('reports downtime at an instant, half-open', () => {
    const plan = createMaintenancePlan({
      vesselId: 'v-1',
      windows: [{ id: 'd-1', kind: 'planned', fromUtc: '2030-01-10T00:00:00Z', toUtc: '2030-01-12T00:00:00Z' }],
    });
    assert.equal(plan.downtimeAt(t('2030-01-09T23:59:59Z')), null);
    assert.equal(plan.downtimeAt(t('2030-01-10T00:00:00Z')).id, 'd-1');
    assert.equal(plan.downtimeAt(t('2030-01-11T12:00:00Z')).id, 'd-1');
    assert.equal(plan.downtimeAt(t('2030-01-12T00:00:00Z')), null);
    assert.throws(() => plan.downtimeAt(null), TypeError);
  });

  it('blocks sailings on its own hull only', () => {
    const plan = createMaintenancePlan({
      vesselId: 'v-1',
      windows: [{ id: 'd-1', kind: 'planned', fromUtc: '2030-01-10T00:00:00Z', toUtc: '2030-01-12T00:00:00Z' }],
    });
    assert.equal(plan.blocksSailing(sailing({ departsAtUtc: '2030-01-10T00:00:00Z', arrivesAtUtc: '2030-01-11T00:00:00Z' })).id, 'd-1');
    assert.equal(plan.blocksSailing(sailing({ departsAtUtc: '2030-01-01T00:00:00Z', arrivesAtUtc: '2030-01-02T00:00:00Z' })), null);
    const other = createVessel({ id: 'v-2', capacityKg: 1000 });
    const elsewhere = createSailing(
      { id: 's-9', vesselId: 'v-2', routeId: 'r', originPortId: 'p-a', destinationPortId: 'p-b', departsAtUtc: '2030-01-10T00:00:00Z', arrivesAtUtc: '2030-01-11T00:00:00Z' },
      { vessel: other },
    );
    assert.throws(() => plan.blocksSailing(elsewhere), RangeError);
  });

  it('finds the next free instant without extrapolating', () => {
    const plan = createMaintenancePlan({
      vesselId: 'v-1',
      windows: [{ id: 'd-1', kind: 'planned', fromUtc: '2030-01-10T00:00:00Z', toUtc: '2030-01-12T00:00:00Z' }],
    });
    assert.equal(plan.nextFreeAt(t('2030-01-01T00:00:00Z')).freeAtMs, Date.parse('2030-01-01T00:00:00Z'));
    assert.equal(plan.nextFreeAt(t('2030-01-10T00:00:00Z')).freeAtMs, Date.parse('2030-01-12T00:00:00Z'));
    assert.equal(plan.nextFreeAt(t('2030-01-11T00:00:00Z')).freeAtMs, Date.parse('2030-01-12T00:00:00Z'));
    assert.equal(plan.nextFreeAt(t('2030-01-12T00:00:00Z')).freeAtMs, Date.parse('2030-01-12T00:00:00Z'));
  });

  it('reports no free instant while an open-ended withdrawal stands', () => {
    const plan = createMaintenancePlan({
      vesselId: 'v-1',
      windows: [{ id: 'd-1', kind: 'emergency', fromUtc: '2030-01-10T00:00:00Z' }],
    });
    assert.equal(plan.nextFreeAt(t('2030-01-11T00:00:00Z')), null);
    assert.equal(plan.nextFreeAt(t('2030-01-09T00:00:00Z')).freeAtMs, Date.parse('2030-01-09T00:00:00Z'));
  });

  it('looks windows up by id', () => {
    const plan = createMaintenancePlan({
      vesselId: 'v-1',
      windows: [{ id: 'd-1', kind: 'planned', fromUtc: '2030-01-10T00:00:00Z', toUtc: '2030-01-12T00:00:00Z' }],
    });
    assert.equal(plan.requireWindow('d-1').id, 'd-1');
    assert.throws(() => plan.requireWindow('nope'), RangeError);
  });
});

describe('maintenance: emergency withdrawal helper', () => {
  it('builds an emergency window', () => {
    const w = withdrawVessel({
      id: 'x-1',
      vesselId: 'v-1',
      fromUtc: '2030-01-10T00:00:00Z',
      expectedReturnUtc: '2030-01-14T00:00:00Z',
      reason: 'engine fault',
    });
    assert.equal(w.kind, 'emergency');
    assert.equal(w.to.utc, '2030-01-14T00:00:00.000Z');
    assert.equal(w.reason, 'engine fault');
  });

  it('allows an unknown return', () => {
    const w = withdrawVessel({ id: 'x-1', vesselId: 'v-1', fromUtc: '2030-01-10T00:00:00Z' });
    assert.equal(w.to, null);
  });

  it('rejects a return before the withdrawal', () => {
    assert.throws(
      () =>
        withdrawVessel({
          id: 'x-1',
          vesselId: 'v-1',
          fromUtc: '2030-01-10T00:00:00Z',
          expectedReturnUtc: '2030-01-09T00:00:00Z',
        }),
      RangeError,
    );
    assert.throws(() => withdrawVessel(null), TypeError);
  });
});

describe('maintenance: affected sailing reports', () => {
  const early = sailing({ id: 's-early', departsAtUtc: '2030-01-01T00:00:00Z', arrivesAtUtc: '2030-01-02T00:00:00Z' });
  const mid = sailing({ id: 's-mid', departsAtUtc: '2030-01-10T12:00:00Z', arrivesAtUtc: '2030-01-11T00:00:00Z' });
  const boundary = sailing({ id: 's-boundary', departsAtUtc: '2030-01-12T00:00:00Z', arrivesAtUtc: '2030-01-13T00:00:00Z' });
  const w = downtime();

  it('reports only the overlapping sailings, in stable order', () => {
    const report = affectedSailings([mid, early, boundary], [w]);
    assert.deepEqual(report.affected.map((a) => a.sailingId), ['s-mid']);
    assert.deepEqual(report.unaffected, []);
  });

  it('carries the window, status and cancellability', () => {
    const report = affectedSailings([mid], [w]);
    const [entry] = report.affected;
    assert.equal(entry.windowId, 'd-1');
    assert.equal(entry.vesselId, 'v-1');
    assert.equal(entry.status, 'draft');
    assert.equal(entry.cancellable, true);
    assert.equal(entry.departsAtUtc, '2030-01-10T12:00:00.000Z');
    assert.ok(Object.isFrozen(entry));
  });

  it('lists cancelled or arrived sailings separately', () => {
    const cancelled = createSailing(
      {
        id: 's-cancelled',
        vesselId: 'v-1',
        routeId: 'r',
        originPortId: 'p-a',
        destinationPortId: 'p-b',
        departsAtUtc: '2030-01-10T12:00:00Z',
        arrivesAtUtc: '2030-01-11T00:00:00Z',
        status: 'cancelled',
      },
      { vessel },
    );
    const report = affectedSailings([cancelled, mid], [w]);
    assert.deepEqual(report.affected.map((a) => a.sailingId), ['s-mid']);
    assert.deepEqual(report.unaffected.map((a) => a.sailingId), ['s-cancelled']);
  });

  it('can pair one sailing with several windows', () => {
    const w2 = defineDowntime({
      id: 'd-2',
      vesselId: 'v-1',
      kind: 'emergency',
      fromUtc: '2030-01-10T12:00:00Z',
    });
    const report = affectedSailings([mid], [w, w2]);
    assert.deepEqual(report.affected.map((a) => a.windowId), ['d-1', 'd-2']);
  });

  it('returns empty reports for no matches', () => {
    const report = affectedSailings([early, boundary], [w]);
    assert.deepEqual(report.affected, []);
    assert.deepEqual(report.unaffected, []);
    assert.ok(Object.isFrozen(report));
  });

  it('validates inputs', () => {
    assert.throws(() => affectedSailings('x', [w]), TypeError);
    assert.throws(() => affectedSailings([], 'x'), TypeError);
  });
});

describe('maintenance: integration with the board', () => {
  function seededBoard() {
    const board = createBoard({ startUtc: '2030-01-01T00:00:00Z' });
    board.addVessel({ id: 'v-1', capacityKg: 1000 });
    board.addSailing({
      id: 's-early',
      vesselId: 'v-1',
      routeId: 'r-1',
      originPortId: 'p-north',
      destinationPortId: 'p-south',
      departsAtUtc: '2030-01-01T00:00:00Z',
      arrivesAtUtc: '2030-01-02T00:00:00Z',
    });
    board.addSailing({
      id: 's-mid',
      vesselId: 'v-1',
      routeId: 'r-1',
      originPortId: 'p-north',
      destinationPortId: 'p-south',
      departsAtUtc: '2030-01-10T12:00:00Z',
      arrivesAtUtc: '2030-01-11T00:00:00Z',
    });
    return board;
  }

  it('records planned downtime and reports affected sailings', () => {
    const board = seededBoard();
    board.addDowntime({
      vesselId: 'v-1',
      windows: [{ id: 'd-1', kind: 'planned', fromUtc: '2030-01-10T00:00:00Z', toUtc: '2030-01-12T00:00:00Z' }],
    });
    const report = board.affectedSailings('v-1');
    assert.deepEqual(report.affected.map((a) => a.sailingId), ['s-mid']);
  });

  it('rejects duplicate plans and unknown vessels', () => {
    const board = seededBoard();
    board.addDowntime({ vesselId: 'v-1', windows: [] });
    assert.throws(() => board.addDowntime({ vesselId: 'v-1', windows: [] }), RangeError);
    assert.throws(() => board.affectedSailings('v-2'), RangeError);
  });

  it('cancels affected sailings at a supplied instant', () => {
    const board = seededBoard();
    board.addDowntime({
      vesselId: 'v-1',
      windows: [{ id: 'd-1', kind: 'planned', fromUtc: '2030-01-10T00:00:00Z', toUtc: '2030-01-12T00:00:00Z' }],
    });
    const result = board.cancelAffectedSailings('v-1', '2030-01-09T00:00:00Z');
    assert.deepEqual(result.cancelled.map((c) => c.sailingId), ['s-mid']);
    assert.equal(board.sailings.get('s-mid').status, 'cancelled');
    assert.equal(board.sailings.get('s-early').status, 'draft', 'unaffected sailing untouched');
    assert.equal(board.sailings.get('s-mid').history.length, 1);
  });

  it('skips sailings that can no longer be cancelled', () => {
    const board = seededBoard();
    board.transitionSailing('s-mid', 'scheduled', { atUtc: '2030-01-02T00:00:00Z' });
    board.transitionSailing('s-mid', 'boarding', { atUtc: '2030-01-10T00:00:00Z', nowUtc: '2030-01-10T00:00:00Z' });
    board.addDowntime({
      vesselId: 'v-1',
      windows: [{ id: 'd-1', kind: 'planned', fromUtc: '2030-01-10T00:00:00Z', toUtc: '2030-01-12T00:00:00Z' }],
    });
    const result = board.cancelAffectedSailings('v-1', '2030-01-10T01:00:00Z');
    assert.deepEqual(result.cancelled, []);
    assert.deepEqual(result.skipped.map((s) => s.sailingId), ['s-mid']);
    assert.equal(board.sailings.get('s-mid').status, 'boarding');
  });

  it('withdraws a hull in an emergency', () => {
    const board = seededBoard();
    const { window, plan } = board.withdrawVessel({
      id: 'x-1',
      vesselId: 'v-1',
      fromUtc: '2030-01-10T00:00:00Z',
      reason: 'engine fault',
    });
    assert.equal(window.kind, 'emergency');
    assert.equal(plan.windows().length, 1);
    assert.deepEqual(board.affectedSailings('v-1').affected.map((a) => a.sailingId), ['s-mid']);
  });

  it('appends a withdrawal to an existing plan', () => {
    const board = seededBoard();
    board.addDowntime({
      vesselId: 'v-1',
      windows: [{ id: 'd-1', kind: 'planned', fromUtc: '2030-02-01T00:00:00Z', toUtc: '2030-02-03T00:00:00Z' }],
    });
    const { plan } = board.withdrawVessel({ id: 'x-1', vesselId: 'v-1', fromUtc: '2030-01-10T00:00:00Z' });
    assert.deepEqual(plan.windows().map((w) => w.id), ['x-1', 'd-1']);
  });

  it('rejects a withdrawal that overlaps existing downtime', () => {
    const board = seededBoard();
    board.addDowntime({
      vesselId: 'v-1',
      windows: [{ id: 'd-1', kind: 'planned', fromUtc: '2030-01-10T00:00:00Z', toUtc: '2030-01-12T00:00:00Z' }],
    });
    assert.throws(
      () => board.withdrawVessel({ id: 'x-1', vesselId: 'v-1', fromUtc: '2030-01-11T00:00:00Z' }),
      RangeError,
    );
    assert.equal(board.downtime.get('v-1').windows().length, 1, 'plan untouched after refusal');
  });

  it('rejects an invalid cancellation instant', () => {
    const board = seededBoard();
    board.addDowntime({
      vesselId: 'v-1',
      windows: [{ id: 'd-1', kind: 'planned', fromUtc: '2030-01-10T00:00:00Z', toUtc: '2030-01-12T00:00:00Z' }],
    });
    assert.throws(() => board.cancelAffectedSailings('v-1', 'not-a-date'), RangeError);
  });
});

