/**
 * Check a sailing's departure and arrival against the ports' tide tables.
 * Both the origin and destination must have a table registered.
 *
 * @param {Board} board
 * @param {string} sailingId
 * @param {{ departureClearanceCm: number, arrivalClearanceCm: number }} clearances
 */
function checkSailingTidesOnBoard(board, sailingId, clearances) {
  const sailing = board.sailings.get(sailingId);
  if (!sailing) {
    throw new RangeError(`unknown sailing: ${String(sailingId)}`);
  }
  const departure = board.tideTables.get(sailing.originPortId);
  if (!departure) {
    throw new RangeError(`no tide table for port: ${sailing.originPortId}`);
  }
  const arrival = board.tideTables.get(sailing.destinationPortId);
  if (!arrival) {
    throw new RangeError(`no tide table for port: ${sailing.destinationPortId}`);
  }
  return checkTidesForSailing({ departure, arrival }, sailing, clearances);
}

/**
 * Record planned downtime for a hull on the board. The plan replaces any
 * previous windows for that hull, so callers pass the complete set.
 *
 * @param {Board} board
 * @param {{ vesselId: string, windows: ReadonlyArray<any> }} spec
 */
function addDowntime(board, spec) {
  const plan = createMaintenancePlan(spec);
  if (board.downtime.has(plan.vesselId)) {
    throw new RangeError(`duplicate downtime plan for vessel: ${plan.vesselId}`);
  }
  board.downtime.set(plan.vesselId, plan);
  return plan;
}

/**
 * Withdraw a hull in an emergency and report what it affects. The withdrawal
 * is appended to the hull's plan (creating one if needed).
 *
 * @param {Board} board
 * @param {{ id: string, vesselId: string, fromUtc: string, expectedReturnUtc?: string, reason?: string }} spec
 */
function withdrawVesselOnBoard(board, spec) {
  const window = withdrawVessel(spec);
  const existing = board.downtime.get(window.vesselId);
  const previous = existing ? existing.windows() : [];
  const plan = createMaintenancePlan({
    vesselId: window.vesselId,
    windows: [...previous, window],
  });
  board.downtime.set(window.vesselId, plan);
  return Object.freeze({ window, plan });
}


