/**
 * Operator example: planned downtime, an emergency withdrawal, and the
 * affected-sailing report.
 *
 * Fictional data only. Run with: node examples/maintenance-example.js
 *
 * Deterministic: every timestamp is supplied here.
 */

import {
  createBoard,
  defineDowntime,
  createMaintenancePlan,
  affectedSailings,
  withdrawVessel,
} from '../src/index.js';

const board = createBoard({ startUtc: '2030-01-01T00:00:00Z' });

board.addVessel({ id: 'v-skiff', name: 'Harbor Skiff', capacityKg: 1000 });
board.addVessel({ id: 'v-tramp', name: 'Kelpline', capacityKg: 2000 });

function addSailing(id, vesselId, departs, arrives) {
  board.addSailing({
    id,
    vesselId,
    routeId: 'route-north-south',
    originPortId: 'p-north',
    destinationPortId: 'p-south',
    departsAtUtc: departs,
    arrivesAtUtc: arrives,
  });
}

addSailing('s-before', 'v-skiff', '2030-01-02T06:00:00Z', '2030-01-02T18:00:00Z');
addSailing('s-during', 'v-skiff', '2030-01-10T06:00:00Z', '2030-01-10T18:00:00Z');
addSailing('s-after', 'v-skiff', '2030-01-14T06:00:00Z', '2030-01-14T18:00:00Z');
addSailing('s-other-hull', 'v-tramp', '2030-01-10T06:00:00Z', '2030-01-10T18:00:00Z');

// --- 1. Block planned downtime for the skiff. --------------------------
board.addDowntime({
  vesselId: 'v-skiff',
  windows: [
    {
      id: 'd-survey',
      kind: 'planned',
      fromUtc: '2030-01-09T00:00:00Z',
      toUtc: '2030-01-12T00:00:00Z',
      reason: 'annual hull survey',
    },
  ],
});

function showReport(label, report) {
  console.log(`\n${label}`);
  if (report.affected.length === 0) {
    console.log('  (no sailings affected)');
  }
  for (const entry of report.affected) {
    console.log(
      `  ${entry.sailingId.padEnd(14)} ${entry.status.padEnd(9)} blocked by ${entry.windowId}` +
        ` (${entry.departsAtUtc} -> ${entry.arrivesAtUtc})` +
        `${entry.cancellable ? '' : ', not cancellable'}`,
    );
  }
  for (const entry of report.unaffected) {
    console.log(`  ${entry.sailingId.padEnd(14)} ${entry.status.padEnd(9)} already settled`);
  }
}

showReport('planned downtime report:', board.affectedSailings('v-skiff'));

// The boundary matters: a sailing ending exactly at 2030-01-09T00:00Z would
// not be blocked, because windows are half-open.
const boundaryWindow = defineDowntime({
  id: 'd-check',
  vesselId: 'v-skiff',
  kind: 'planned',
  fromUtc: '2030-01-09T00:00:00Z',
  toUtc: '2030-01-12T00:00:00Z',
});
const edges = createMaintenancePlan({
  vesselId: 'v-skiff',
  windows: [boundaryWindow],
});
console.log(
  `\na sailing ending exactly at the window start is blocked: ` +
    `${edges.blocksSailing(board.sailings.get('s-before')) !== null}`,
);

// --- 2. Cancel what the downtime blocks. -------------------------------
const cancellation = board.cancelAffectedSailings('v-skiff', '2030-01-08T09:00:00Z');
console.log(`\ncancelled: ${cancellation.cancelled.map((c) => c.sailingId).join(', ') || '(none)'}`);
showReport('after cancellation:', board.affectedSailings('v-skiff'));

// --- 3. An emergency withdrawal with an unknown return. ----------------
const { window } = board.withdrawVessel({
  id: 'x-engine',
  vesselId: 'v-skiff',
  fromUtc: '2030-01-14T00:00:00Z',
  reason: 'engine fault',
});
console.log(`\nemergency withdrawal ${window.id} from ${window.from.utc}, return ${window.to === null ? 'unknown' : window.to.utc}`);

showReport('after withdrawal:', board.affectedSailings('v-skiff'));

// The other hull is untouched by all of this.
showReport('other hull:', board.affectedSailings('v-tramp'));

// --- 4. Open-ended windows swallow later windows. ----------------------
try {
  createMaintenancePlan({
    vesselId: 'v-skiff',
    windows: [
      { id: 'x-open', kind: 'emergency', fromUtc: '2030-01-14T00:00:00Z' },
      { id: 'd-later', kind: 'planned', fromUtc: '2030-02-01T00:00:00Z', toUtc: '2030-02-03T00:00:00Z' },
    ],
  });
} catch (error) {
  console.log(`\nopen-ended then planned: refused — ${error.message}`);
}

// A plain report over arbitrary sailings and windows also works standalone.
const standalone = affectedSailings(
  [...board.sailings.values()],
  [withdrawVessel({ id: 'x-14', vesselId: 'v-tramp', fromUtc: '2030-01-10T00:00:00Z', expectedReturnUtc: '2030-01-11T00:00:00Z' })],
);
console.log(`\nstandalone report: ${standalone.affected.map((a) => a.sailingId).join(', ') || '(none)'}`);

