// The boundary matters: windows are half-open, so a passage ending exactly
// when downtime begins is NOT blocked, and one departing exactly when it ends
// is not blocked either. Build two ad-hoc sailings to show both edges.
const edges = createMaintenancePlan({
  vesselId: 'v-skiff',
  windows: [
    defineDowntime({
      id: 'd-check',
      vesselId: 'v-skiff',
      kind: 'planned',
      fromUtc: '2030-01-09T00:00:00Z',
      toUtc: '2030-01-12T00:00:00Z',
    }),
  ],
});

// Ending exactly at the window start (2030-01-09T00:00Z).
const endingAtStart = {
  ...board.sailings.get('s-before'),
  departsAt: { ms: Date.parse('2030-01-08T00:00:00Z') },
  arrivesAt: { ms: Date.parse('2030-01-09T00:00:00Z') },
};
// Departing exactly at the window end (2030-01-12T00:00Z).
const departingAtEnd = {
  ...board.sailings.get('s-before'),
  departsAt: { ms: Date.parse('2030-01-12T00:00:00Z') },
  arrivesAt: { ms: Date.parse('2030-01-13T00:00:00Z') },
};
console.log(
  `\nending exactly at the window start is blocked: ` +
    `${edges.blocksSailing(endingAtStart) !== null}`,
);
console.log(
  `departing exactly at the window end is blocked: ` +
    `${edges.blocksSailing(departingAtEnd) !== null}`,
);

